entry.string:
operation evm_block_op(network_id: integer, evm_block_height: integer, evm_block_hash: byte_array, events: list<event_data>) {
                                    evm_block_fn(network_id, evm_block_height, evm_block_hash, events);
                                    }

import admin: ^.lib.access.admin;
                                    import acc: ^.lib.ft3.account;
                                    import ft3: ^.lib.ft3.core;
                                    import evm: ^.lib.ft3.evm;
                                    import dip: ^.lib.dip.core;
                                    import og: ^.lib.originals.core;
                                    import ^.lib.ft3_helper.*;

                                    struct module_args {
                                    sync_transfers_inside_dapp: boolean;
                                    }

                                    namespace eif.INonFungibleOriginal {
                                    val interface = "eif.INonFungibleOriginal";

                                    function dependencies() = [
                                    og.chromia.INonFungibleOriginal.interface
                                    ];

                                    val id = dip.Attribute.I(interface, name = "id");
                                    val address = dip.Attribute.I(interface, name = "address");
                                    val symbol = dip.Attribute.I(interface, name = "symbol");
                                    val uri = dip.Attribute.I(interface, name = "uri");

                                    function register(account: ft3.acc.account) {
                                    dip.InterfaceFactory.new(interface,
                                    [
                                    id: dip.Type(dip.Integer.T()),
                                    address: dip.Type(dip.Text.T(), [dip.Optional()]),
                                    symbol: dip.Type(dip.Text.T(), [dip.Optional()]),
                                    uri: dip.Type(dip.Text.T(), [dip.Optional()])
                                    ],
                                    dependencies() @* {} (dip.Interface.get($)),
                                    account = account,
                                    is_open = true
                                    );
                                    }

                                    function get() = dip.Interface.get(interface);
                                    function has(dip.instance) = dip.Interface.is_a(instance, get());
                                    }

                                    entity token_mapping {
                                    key token: evm_erc20;
                                    key asset: ft3.asset;
                                    }

                                    entity nft_mapping {
                                    network_id: integer;
                                    address: text;
                                    interface: dip.Interface.dclass;
                                    key network_id, address;
                                    }

                                    entity evm_account_link {
                                    network_id: integer;
                                    state_n: integer;
                                    evm_beneficiary: text;
                                    key network_id, state_n, evm_beneficiary;
                                    }

                                    entity evm_block {
                                    network_id: integer;
                                    evm_block_height: integer;
                                    evm_block_hash: byte_array;
                                    key network_id, evm_block_height, evm_block_hash;
                                    }

                                    entity evm_erc20 {
                                    network_id: integer;
                                    address: text;
                                    name: text;
                                    symbol: text;
                                    decimals: integer;
                                    key network_id, address;
                                    }

                                    entity evm_erc721 {
                                    key network_id: integer, address: text, token_id: integer;
                                    name: text;
                                    symbol: text;
                                    uri: text;
                                    }

                                    entity evm_event {
                                    index evm_block;
                                    tnx_hash: byte_array;
                                    log_index: integer;
                                    event_signature: byte_array;
                                    contract_address: byte_array;
                                    indexed_values: byte_array;
                                    non_indexed_values: byte_array;
                                    }

                                    entity evm_erc20_balance {
                                    network_id: integer;
                                    token: evm_erc20;
                                    beneficiary: text;
                                    mutable amount: integer;
                                    key token, beneficiary;
                                    }

                                    entity evm_erc721_balance {
                                    network_id: integer;
                                    token: evm_erc721;
                                    beneficiary: text;
                                    key token, beneficiary;
                                    }

                                    entity evm_erc20_withdraw {
                                    key serial: integer;
                                    network_id: integer;
                                    index token: evm_erc20;
                                    index beneficiary: text;
                                    amount: integer;
                                    }

                                    entity evm_erc721_withdraw {
                                    key serial: integer;
                                    network_id: integer;
                                    index token: evm_erc721;
                                    index beneficiary: text;
                                    }

                                    object withdraw_stats {
                                    mutable withdraw_count: integer = 0;
                                    }

                                    struct event_data {
                                    tnx_hash: byte_array;
                                    log_index: integer;
                                    signature: byte_array;
                                    contract_address: byte_array;
                                    name: text;
                                    indexed_values: list<gtv>;
                                    non_indexed_values: list<gtv>;
                                    }

                                    struct state_data {
                                    state_n: integer;
                                    account: list<gtv>;
                                    }

                                    struct state_address_dto {
                                    state_n: integer;
                                    evm_address: text;
                                    }

                                    query get_network_accounts(network_id: integer) : list<state_address_dto>{
                                    var accounts = evm_account_link @* {.network_id == network_id};
                                    val accounts_dto = list<state_address_dto>();
                                    for(account in accounts){
                                    accounts_dto.add(state_address_dto(state_n=account.state_n, evm_address=account.evm_beneficiary));
                                    }
                                    return accounts_dto;
                                    }

                                    query get_last_evm_block(network_id: integer) { return evm_block @? {network_id} (@sort_desc .evm_block_height, .evm_block_hash) limit 1;}

                                    query get_erc20_withdrawal(network_id: integer, token_address: text, beneficiary: text) {
                                    val token = evm_erc20 @? { network_id, .address.lower_case() == token_address.lower_case() };
                                    if (empty(token)) {
                                    return null;
                                    }

                                    return evm_erc20_withdraw @* { network_id, token , beneficiary } (@sort_desc .serial, .network_id, token = .token.address, .beneficiary, .amount);
                                    }

                                    query get_erc721_withdrawal(network_id: integer, token_address: text, token_id: integer, beneficiary: text) {
                                    val token = evm_erc721 @? { network_id, .address.lower_case() == token_address.lower_case(), token_id };
                                    if (empty(token)) {
                                    return null;
                                    }

                                    return evm_erc721_withdraw @* { network_id, token, beneficiary } (@sort_desc .serial, .network_id, token = .token.address, .beneficiary);
                                    }

                                    query evm_balance_of_erc20(network_id: integer, token_address: text, beneficiary: text): integer {
                                    val t = evm_erc20 @? { network_id, .address.lower_case() == token_address.lower_case() };
                                    if (empty(t)) {
                                    return 0;
                                    }
                                    val b = evm_erc20_balance @? { network_id, .token == t, beneficiary } (.amount);
                                    if (empty(b)) {
                                    return 0;
                                    }
                                    return b;
                                    }

                                    query evm_has_erc721(network_id: integer, token_address: text, token_id: integer, beneficiary: text): boolean {
                                    val t = evm_erc721 @? { network_id, .address.lower_case() == token_address.lower_case(), token_id };
                                    if (empty(t)) {
                                    return false;
                                    }
                                    val b = evm_erc721_balance @? { network_id, .token == t, beneficiary };
                                    return not empty(b);
                                    }

                                    operation __evm_block(network_id: integer, evm_block_height: integer, evm_block_hash: byte_array, events: list<event_data>) {
                                    evm_block_fn(network_id, evm_block_height, evm_block_hash, events);
                                    }

                                    function evm_block_fn(network_id: integer, evm_block_height: integer, evm_block_hash: byte_array, events: list<event_data>) {
                                    val evm_block = create evm_block(
                                    network_id,
                                    evm_block_height,
                                    evm_block_hash
                                    );

                                    for (event in events) {
                                    var indexed_values_bytes = x"";
                                    for (value in event.indexed_values) {
                                    indexed_values_bytes += value.to_bytes();
                                    }
                                    var non_indexed_values_bytes = x"";
                                    for (value in event.non_indexed_values) {
                                    non_indexed_values_bytes += value.to_bytes();
                                    }

                                    // ignore invalid events' network id
                                    val net_id = integer.from_gtv(event.non_indexed_values[0]);
                                    if (net_id != network_id) {
                                    log("ignore invalid events' network id: " + net_id + " : " + network_id);
                                    continue;
                                    }
                                    val evm_address = byte_array.from_gtv(event.indexed_values[0]);
                                    val beneficiary = to_zero_padded_hex(evm_address);
                                    val token_address = to_zero_padded_hex(byte_array.from_gtv(event.indexed_values[1]));
                                    val evm_account = evm.evm_account @? { .address == evm_address };

                                    when (event.name) {
                                    "DepositedERC20" -> {
                                    // ignore the unsupport token, move to process next events if any
                                    val token = evm_erc20 @? { network_id, .address.lower_case() == token_address.lower_case() };
                                    if (empty(token)) {
                                    log("ignore the unsupport token, move to process next events if any: " + token_address);
                                    continue;
                                    }
                                    val token_mapping = token_mapping @? { .token == token!! };
                                    if (empty(token_mapping)) {
                                    log("no token_mapping");
                                    continue;
                                    }

                                    // ignore event if ft3 asset does not exist
                                    val ft3_asset = ft3.asset @? { .id == token_mapping!!.asset.id };
                                    if (empty(ft3_asset)) {
                                    log("ignore event if ft3 asset does not exist: " + token_mapping.asset.id);
                                    continue;
                                    }
                                    val amount = integer.from_gtv(event.non_indexed_values[1]);
                                    val evm_event = create evm_event(
                                    evm_block,
                                    tnx_hash = event.tnx_hash,
                                    log_index = event.log_index,
                                    event_signature = event.signature,
                                    contract_address = event.contract_address,
                                    indexed_values = indexed_values_bytes,
                                    non_indexed_values = non_indexed_values_bytes
                                    );

                                    // if user account does not exist, record the state into EIF for withdraw back to EVM chains later.
                                    // This feature is to avoid losing fund of user
                                    if (empty(evm_account)) {
                                    val name = text.from_gtv(event.non_indexed_values[2]);
                                    val symbol = text.from_gtv(event.non_indexed_values[3]);
                                    val decimals = integer.from_gtv(event.non_indexed_values[4]);
                                    log("record the state into EIF for withdraw back to EVM chains later for beneficiary: " + beneficiary);
                                    deposit_ERC20(network_id, beneficiary, token_address, amount, name, symbol, decimals);

                                    val account_link = get_or_create_evm_account_link(network_id, beneficiary);
                                    val state = build_account_state(network_id, beneficiary, null);
                                    val state_data = state_data(
                                    account_link.state_n,
                                    account = state
                                    );
                                    op_context.emit_event("eif_state", state_data.to_gtv());
                                    } else {
                                    // mint postchain token for ft3 account
                                    val ft3_account = evm_account.account;
                                    log("mint postchain token for ft3 account: " + ft3_account.id);
                                    val ft3_balance = ft3.ensure_balance( ft3_account, ft3_asset!! );
                                    ft3_balance.amount += amount;
                                    val ft3_beneficiary = to_zero_padded_hex(evm.evm_account @ { .account == ft3_account } ( .address ));
                                    val account_link = get_or_create_evm_account_link(token_mapping.token.network_id, ft3_beneficiary);
                                    val state = build_account_state(network_id, ft3_beneficiary, ft3_account);
                                    val state_data = state_data(
                                    account_link.state_n,
                                    account = state
                                    );
                                    op_context.emit_event("eif_state", state_data.to_gtv());
                                    }
                                    }
                                    "DepositedERC721" -> {
                                    // ignore event if dip instance does not exist
                                    val interface = nft_mapping @? { network_id, .address.lower_case() == token_address.lower_case() }.interface;
                                    if (empty(interface)) {
                                    log("nft token was not mapping yet: " + token_address);
                                    continue;
                                    }

                                    val evm_event = create evm_event(
                                    evm_block,
                                    tnx_hash = event.tnx_hash,
                                    log_index = event.log_index,
                                    event_signature = event.signature,
                                    contract_address = event.contract_address,
                                    indexed_values = indexed_values_bytes,
                                    non_indexed_values = non_indexed_values_bytes
                                    );

                                    val token_id = integer.from_gtv(event.non_indexed_values[1]);
                                    val name = text.from_gtv(event.non_indexed_values[2]);
                                    val symbol = text.from_gtv(event.non_indexed_values[3]);
                                    val uri = text.from_gtv(event.non_indexed_values[4]);

                                    if (empty(evm_account)) {
                                    log("deposit nft into EIF: " + name);
                                    deposit_ERC721(network_id, beneficiary, token_address, token_id, name, symbol, uri);

                                    val account_link = get_or_create_evm_account_link(network_id, beneficiary);
                                    val state = build_account_state(network_id, beneficiary, null);
                                    val state_data = state_data(
                                    account_link.state_n,
                                    account = state
                                    );
                                    op_context.emit_event("eif_state", state_data.to_gtv());
                                    } else {
                                    val ft3_account = evm_account.account;
                                    log("mint postchain original for ft3 account: " + ft3_account.id);
                                    require(interface!!.name == eif.INonFungibleOriginal.interface, "interface is not supported: " + interface!!.name);
                                    val original_type = og.Minter.I(
                                    interface_name = interface.name,
                                    [
                                    eif.INonFungibleOriginal.symbol: dip.Text.T(symbol),
                                    // eif.INonFungibleOriginal.uri: dip.Text.T(uri),
                                    eif.INonFungibleOriginal.id: dip.Integer.T(token_id),
                                    // eif.INonFungibleOriginal.address: dip.Text.T(token_address),
                                    og.chromia.IOriginal.name: dip.Text.T(name),
                                    og.chromia.IOriginal.creator_id: dip.ByteArray.T(ft3_account.id),
                                    og.chromia.IOriginal.creator_name: dip.Text.T("User")
                                    ]
                                    );
                                    og.Minter.mint_non_fungible_original(ft3_account, original_type);
                                    }
                                    }
                                    }
                                    }
                                    }

                                    operation add_new_evm_erc20(network_id: integer, token_address: text, name: text, symbol: text, decimals: integer) {
                                    admin.require_admin("Only admin can add new token mapping");
                                    require(empty(evm_erc20 @? { network_id, .address.lower_case() == token_address.lower_case() }), "token already existed");
                                    create evm_erc20(
                                    network_id,
                                    address = token_address,
                                    name,
                                    symbol,
                                    decimals
                                    );
                                    }

                                    operation add_new_token_mapping(network_id: integer, token_address: text, asset_id: byte_array) {
                                    admin.require_admin("Only admin can add new token mapping");

                                    val token = require(
                                    evm_erc20 @? { network_id, .address.lower_case() == token_address.lower_case() },
                                    "Token does not exist: " + token_address
                                    );

                                    val asset = require(
                                    ft3.asset @? { .id == asset_id },
                                    "Asset does not exist: " + asset_id
                                    );

                                    require(
                                    empty(token_mapping @? { token, asset }),
                                    "Token was already mapped: " + token_address
                                    );

                                    create token_mapping(token, asset);
                                    }

                                    operation register_chromia_base_originals() {
                                    admin.require_admin("Only admin can init chromia base original interfaces");

                                    val admin_account = require(
                                    acc.account @? { .id == admin.account_id() },
                                    "admin account was not defined: " + admin.account_id()
                                    );

                                    val dclass = dip.Interface.dclass @? { og.chromia.INonFungibleOriginal.interface };
                                    if (empty(dclass)) {
                                    og.initialize_original_interfaces(admin_account);
                                    }
                                    }

                                    operation init_eif_original_interface() {
                                    admin.require_admin("Only admin can define new original interface");

                                    val admin_account = require(
                                    acc.account @? { .id == admin.account_id() },
                                    "admin account was not defined: " + admin.account_id()
                                    );

                                    require(
                                    empty(dip.Interface.dclass @? { eif.INonFungibleOriginal.interface }),
                                    "eif non fungible original interface was already defined"
                                    );
                                    eif.INonFungibleOriginal.register(admin_account);
                                    }

                                    operation add_eif_nft_mapping(network_id: integer, token_address: text) {
                                    admin.require_admin("Only admin can do eif nft mapping");

                                    val dclass = require(
                                    dip.Interface.dclass @? { eif.INonFungibleOriginal.interface },
                                    "dclass does not exist: " + eif.INonFungibleOriginal.interface
                                    );

                                    require(
                                    empty(nft_mapping @? {}),
                                    "eif non fungible token was already mapped: " + token_address
                                    );

                                    create nft_mapping(network_id, token_address, dclass);
                                    }

                                    operation deposit_ft3_token(auth_id, network_id: integer, token_address: text, beneficiary: text, amount: integer) {
                                    require(amount > 0, "amount should larger than 0");
                                    val token = require(evm_erc20 @? { network_id, .address.lower_case() == token_address.lower_case() }, "token is not support");
                                    val token_mapping = require(token_mapping @? { token }, "token is not support");
                                    val asset = require(ft3.asset @? { .id == token_mapping.asset.id }, "asset does not exist");

                                    val account = do_auth(auth_id, ["T"]);

                                    // burn ft3 token of the account
                                    destroy_asset(account, asset, amount);

                                    // update the postchain EIF state for equivalent account
                                    deposit_ERC20(network_id, beneficiary, token_address, amount, token_mapping.token.name, token_mapping.token.symbol, token_mapping.token.decimals);

                                    // update relevant account state
                                    update_account_state(account.id, asset.id);
                                    }

                                    operation bridge_ft3_token_to_evm(auth_id, network_id: integer, token_address: text, beneficiary: text, amount: integer) {
                                    require(amount > 0, "amount should larger than 0");
                                    val token = require(evm_erc20 @? { network_id, .address.lower_case() == token_address.lower_case() }, "token is not support");
                                    val token_mapping = require(token_mapping @? { token }, "token is not support");
                                    val asset = require(ft3.asset @? { .id == token_mapping.asset.id }, "asset does not exist");

                                    val account = do_auth(auth_id, ["T"]);

                                    // burn ft3 token of the account and update relevant account state
                                    destroy_asset(account, asset, amount);
                                    update_account_state(account.id, asset.id);

                                    update withdraw_stats(withdraw_count += 1);
                                    val next_serial = withdraw_stats.withdraw_count;

                                    create evm_erc20_withdraw(
                                    serial = next_serial,
                                    network_id,
                                    token,
                                    beneficiary,
                                    amount
                                    );

                                    val withdraw_info = list<gtv>();
                                    withdraw_info.add(next_serial.to_gtv());
                                    withdraw_info.add(network_id.to_gtv());
                                    withdraw_info.add(byte_array.from_hex("000000000000000000000000" + token_address.sub(2)).to_gtv());
                                    withdraw_info.add(byte_array.from_hex("000000000000000000000000" + beneficiary.sub(2)).to_gtv());
                                    withdraw_info.add(amount.to_gtv());

                                    op_context.emit_event("eif_event", withdraw_info.to_gtv());
                                    }

                                    operation deposit_non_fungible_original(auth_id, asset_id: byte_array, network_id: integer, token_address: text, beneficiary: text) {
                                    val account = do_auth(auth_id, ["T"]);
                                    val ft3_burn_account = og.ensure_locked_account("BURN", account);

                                    val instance = og.Id.get_instance(asset_id);
                                    val dclass = dip.instance_dclass @ { instance, .direct == true} .dclass;
                                    require(dclass.name == eif.INonFungibleOriginal.interface, "interface is not support: " + dclass.name);
                                    og.Ownership.transfer(account, instance, ft3_burn_account.id, 1);

                                    val token_id = dip.Integer.get_value(instance, eif.INonFungibleOriginal.id);
                                    var name = dip.Text.get_value(instance, og.chromia.IOriginal.name) ?: "";
                                    var symbol = dip.Text.get_value(instance, eif.INonFungibleOriginal.symbol) ?: "";
                                    var uri = dip.Text.get_value(instance, eif.INonFungibleOriginal.uri) ?: "";

                                    deposit_ERC721(network_id, beneficiary, token_address, token_id!!, name, symbol, uri);
                                    }

                                    operation bridge_non_fungible_original_to_evm(auth_id, asset_id: byte_array, network_id: integer, token_address: text, beneficiary: text) {
                                    val account = do_auth(auth_id, ["T"]);
                                    val ft3_burn_account = og.ensure_locked_account("BURN", account);

                                    val instance = og.Id.get_instance(asset_id);
                                    val dclass = dip.instance_dclass @ { instance, .direct == true} .dclass;
                                    require(dclass.name == eif.INonFungibleOriginal.interface, "interface is not support: " + dclass.name);
                                    og.Ownership.transfer(account, instance, ft3_burn_account.id, 1);

                                    require(
                                    nft_mapping @? { network_id, .address.lower_case() == token_address.lower_case() }.interface,
                                    "nft token was not mapping yet: " + token_address
                                    );

                                    var token_id = require(dip.Integer.get_value(instance, eif.INonFungibleOriginal.id), "cannot bridge the non fungile token without token id");
                                    var name = dip.Text.get_value(instance, og.chromia.IOriginal.name) ?: "";
                                    var symbol = dip.Text.get_value(instance, eif.INonFungibleOriginal.symbol) ?: "";
                                    var uri = dip.Text.get_value(instance, eif.INonFungibleOriginal.uri) ?: "";

                                    var token = evm_erc721 @? { network_id, .address.lower_case() == token_address.lower_case(), token_id };
                                    if (empty(token)) {
                                    token = create evm_erc721(
                                    network_id,
                                    address = token_address,
                                    token_id,
                                    name,
                                    symbol,
                                    uri
                                    );
                                    }

                                    update withdraw_stats(withdraw_count += 1);
                                    val next_serial = withdraw_stats.withdraw_count;

                                    create evm_erc721_withdraw(
                                    serial = next_serial,
                                    network_id,
                                    token,
                                    beneficiary
                                    );

                                    val withdraw_info = list<gtv>();
                                    withdraw_info.add(next_serial.to_gtv());
                                    withdraw_info.add(network_id.to_gtv());
                                    withdraw_info.add(byte_array.from_hex("000000000000000000000000" + token_address.sub(2)).to_gtv());
                                    withdraw_info.add(byte_array.from_hex("000000000000000000000000" + beneficiary.sub(2)).to_gtv());
                                    withdraw_info.add(token_id.to_gtv());

                                    op_context.emit_event("eif_event", withdraw_info.to_gtv());
                                    }

                                    // user can claim ft3 asset back to specific account id on postchain after deposit it into EIF
                                    operation claim_ERC20(network_id: integer, token_address: text, beneficiary: text, amount: integer,
                                    r: byte_array, s: byte_array, v: integer, pk: text, account_id: byte_array) {
                                    require(amount > 0, "Must withdraw an amount larger than 0");
                                    val recovered_pubkey = crypto.eth_ecrecover(r, s, v, hash_eth_message(pk));
                                    val eth_address = get_eth_address(recovered_pubkey);
                                    require(eth_address == beneficiary.sub(2), "beneficiary is not correct, " + "b: " + beneficiary.sub(2) + " e: " + eth_address);
                                    val participants = op_context.get_signers();
                                    require_not_empty(participants, "participants is empty");
                                    require(participants.size() == 1, "only support single auth");
                                    require(participants[0].to_hex() == pk, "ft3 participant is not correct, " + participants[0].to_hex() + ", " + pk);

                                    val token = require(
                                    evm_erc20 @? { network_id, .address.lower_case() == token_address.lower_case() },
                                    "unsupport token: " + token_address
                                    );
                                    val token_mapping = require(
                                    token_mapping @? { .token == token },
                                    "no token mapping"
                                    );
                                    val ft3_asset = require(
                                    ft3.asset @? { .id == token_mapping.asset.id },
                                    "ft3 asset does not exist: " + token_mapping.asset.id
                                    );
                                    val balance = evm_erc20_balance @? { network_id, token, beneficiary };
                                    require_not_empty(balance, "No balance for this token");
                                    require(balance.amount >= amount, "Balance is too low");
                                    update balance(.amount -= amount);

                                    update withdraw_stats(withdraw_count += 1);
                                    val next_serial = withdraw_stats.withdraw_count;

                                    // net_id = 0 means withdraw from postchain snapshot state into FT3
                                    val net_id = 0;
                                    create evm_erc20_withdraw(
                                    serial = next_serial,
                                    network_id = net_id,
                                    token,
                                    beneficiary,
                                    amount
                                    );

                                    val withdraw_info = list<gtv>();
                                    withdraw_info.add(next_serial.to_gtv());
                                    withdraw_info.add(net_id.to_gtv());
                                    withdraw_info.add(byte_array.from_hex("000000000000000000000000" + token_address.sub(2)).to_gtv());
                                    withdraw_info.add(byte_array.from_hex("000000000000000000000000" + beneficiary.sub(2)).to_gtv());
                                    withdraw_info.add(amount.to_gtv());

                                    val account = acc.account @ { account_id };
                                    val ft3_balance = ft3.ensure_balance(account , ft3_asset );
                                    ft3_balance.amount += amount;
                                    emit_withdraw(network_id, beneficiary, account, withdraw_info);
                                    }

                                    // user can claim non-fungible token instance back to specific account id on postchain after deposit it into EIF
                                    operation claim_ERC721(network_id: integer, token_address: text, beneficiary: text, token_id: integer,
                                    r: byte_array, s: byte_array, v: integer, pk: text, account_id: byte_array) {
                                    val recovered_pubkey = crypto.eth_ecrecover(r, s, v, hash_eth_message(pk));
                                    val eth_address = get_eth_address(recovered_pubkey);
                                    require(eth_address == beneficiary.sub(2), "beneficiary is not correct, " + "b: " + beneficiary.sub(2) + " e: " + eth_address);
                                    val participants = op_context.get_signers();
                                    require_not_empty(participants, "participants is empty");
                                    require(participants.size() == 1, "only support single auth");
                                    require(participants[0].to_hex() == pk, "ft3 participant is not correct, " + participants[0].to_hex() + ", " + pk);

                                    val token = require(
                                    evm_erc721 @? { network_id, .address.lower_case() == token_address.lower_case(), token_id },
                                    "token does not exist: " + token_address + " : " + token_id
                                    );

                                    val interface = require(
                                    nft_mapping @? { network_id, .address.lower_case() == token_address.lower_case() }.interface,
                                    "nft token was not mapping yet: " + token_address
                                    );
                                    require(interface.name == eif.INonFungibleOriginal.interface, "interface is not support: " + interface.name);

                                    val balance = evm_erc721_balance @? { network_id, token, beneficiary };
                                    require_not_empty(balance, "No balance for this token");
                                    delete balance;

                                    update withdraw_stats(withdraw_count += 1);
                                    val next_serial = withdraw_stats.withdraw_count;

                                    // net_id = 0 means withdraw from postchain snapshot state into FT3
                                    val net_id = 0;
                                    create evm_erc721_withdraw(
                                    serial = next_serial,
                                    network_id = net_id,
                                    token,
                                    beneficiary
                                    );

                                    val withdraw_info = list<gtv>();
                                    withdraw_info.add(next_serial.to_gtv());
                                    withdraw_info.add(net_id.to_gtv());
                                    withdraw_info.add(byte_array.from_hex("000000000000000000000000" + token_address.sub(2)).to_gtv());
                                    withdraw_info.add(byte_array.from_hex("000000000000000000000000" + beneficiary.sub(2)).to_gtv());
                                    withdraw_info.add(token_id.to_gtv());

                                    val original_type = og.Minter.I(
                                    interface_name = interface.name,
                                    [
                                    eif.INonFungibleOriginal.symbol: dip.Text.T(token.symbol),
                                    // eif.INonFungibleOriginal.uri: dip.Text.T(uri),
                                    eif.INonFungibleOriginal.id: dip.Integer.T(token.token_id),
                                    // eif.INonFungibleOriginal.address: dip.Text.T(token_address),
                                    og.chromia.IOriginal.name: dip.Text.T(token.name),
                                    og.chromia.IOriginal.creator_id: dip.ByteArray.T(account_id),
                                    og.chromia.IOriginal.creator_name: dip.Text.T("User")
                                    ]
                                    );
                                    val account = require(acc.account @? { account_id }, "account does not exist: " + account_id);
                                    og.Minter.mint_non_fungible_original(account, original_type);

                                    emit_withdraw(network_id, beneficiary, account, withdraw_info);
                                    }

                                    operation withdraw_ERC20(network_id: integer, token_address: text, beneficiary: text, amount: integer,
                                    r: byte_array, s: byte_array, v: integer, pk: text) {
                                    require(amount > 0, "Must withdraw an amount larger than 0");

                                    // ensure that the signer also control the beneficiary account
                                    val recovered_pubkey = crypto.eth_ecrecover(r, s, v, hash_eth_message(pk));
                                    val eth_address = get_eth_address(recovered_pubkey);
                                    require(eth_address == beneficiary.sub(2), "beneficiary is not correct, " + "b: " + beneficiary.sub(2) + " e: " + eth_address);
                                    val participants = op_context.get_signers();
                                    require_not_empty(participants, "participants is empty");
                                    require(participants.size() == 1, "only support single auth");
                                    require(participants[0].to_hex() == pk, "ft3 participant is not correct, " + participants[0].to_hex() + ", " + pk);

                                    val token = evm_erc20 @? { network_id, .address.lower_case() == token_address.lower_case() };
                                    if (empty(token)) {
                                    return;
                                    }
                                    val balance = evm_erc20_balance @? { network_id, token, beneficiary };
                                    require_not_empty(balance, "No balance for this token");
                                    require(balance.amount >= amount, "Balance is too low");
                                    update balance(.amount -= amount);

                                    update withdraw_stats(withdraw_count += 1);
                                    val next_serial = withdraw_stats.withdraw_count;

                                    create evm_erc20_withdraw(
                                    serial = next_serial,
                                    network_id,
                                    token,
                                    beneficiary,
                                    amount
                                    );

                                    val withdraw_info = list<gtv>();
                                    withdraw_info.add(next_serial.to_gtv());
                                    withdraw_info.add(network_id.to_gtv());
                                    withdraw_info.add(byte_array.from_hex("000000000000000000000000" + token_address.sub(2)).to_gtv());
                                    withdraw_info.add(byte_array.from_hex("000000000000000000000000" + beneficiary.sub(2)).to_gtv());
                                    withdraw_info.add(amount.to_gtv());

                                    val account_id = evm.get_account_by_evm_address(byte_array.from_hex(eth_address));
                                    val ft3_account = if (account_id == null) null else acc.account @? { .id == account_id };
                                    emit_withdraw(network_id, beneficiary, ft3_account, withdraw_info);
                                    }

                                    operation withdraw_ERC721(network_id: integer, token_address: text, beneficiary: text, token_id: integer,
                                    r: byte_array, s: byte_array, v: integer, pk: text) {
                                    // ensure that the signer also control the beneficiary account
                                    val recovered_pubkey = crypto.eth_ecrecover(r, s, v, hash_eth_message(pk));
                                    val eth_address = get_eth_address(recovered_pubkey);
                                    require(eth_address == beneficiary.sub(2), "beneficiary is not correct, " + "b: " + beneficiary.sub(2) + " e: " + eth_address);
                                    val participants = op_context.get_signers();
                                    require_not_empty(participants, "participants is empty");
                                    require(participants.size() == 1, "only support single auth");
                                    require(participants[0].to_hex() == pk, "ft3 participant is not correct, " + participants[0].to_hex() + ", " + pk);

                                    val token = evm_erc721 @? { network_id, .address.lower_case() == token_address.lower_case(), token_id };
                                    if (empty(token)) {
                                    return;
                                    }

                                    val balance = evm_erc721_balance @? { network_id, token, beneficiary };
                                    require_not_empty(balance, "No balance for this token");
                                    delete balance;

                                    update withdraw_stats(withdraw_count += 1);
                                    val next_serial = withdraw_stats.withdraw_count;

                                    create evm_erc721_withdraw(
                                    serial = next_serial,
                                    network_id,
                                    token,
                                    beneficiary
                                    );

                                    val withdraw_info = list<gtv>();
                                    withdraw_info.add(next_serial.to_gtv());
                                    withdraw_info.add(network_id.to_gtv());
                                    withdraw_info.add(byte_array.from_hex("000000000000000000000000" + token_address.sub(2)).to_gtv());
                                    withdraw_info.add(byte_array.from_hex("000000000000000000000000" + beneficiary.sub(2)).to_gtv());
                                    withdraw_info.add(token_id.to_gtv());

                                    val account_id = evm.get_account_by_evm_address(byte_array.from_hex(eth_address));
                                    val ft3_account = if (account_id == null) null else acc.account @? { .id == account_id };
                                    emit_withdraw(network_id, beneficiary, ft3_account, withdraw_info);
                                    }

                                    function get_or_create_evm_account_link(network_id: integer, beneficiary: text): evm_account_link {
                                    val account = evm_account_link @? { network_id, beneficiary };
                                    if (empty(account)) {
                                    val last_state_n = evm_account_link @? {} (@sort_desc .state_n) limit 1;
                                    var next_state_n = 0;
                                    if (empty(last_state_n)) {
                                    next_state_n = 1;
                                    } else {
                                    next_state_n = last_state_n + 1;
                                    }

                                    return create evm_account_link(
                                    network_id,
                                    state_n = next_state_n,
                                    beneficiary
                                    );
                                    };
                                    return account;
                                    }

                                    function build_account_state(network_id: integer, beneficiary: text, account: acc.account?) {
                                    val state = list<gtv>();
                                    state.add(byte_array.from_hex("000000000000000000000000" + beneficiary.sub(2)).to_gtv());
                                    // In order of asset type
                                    // 0: ERC20
                                    val erc20_balances = evm_erc20_balance @* { network_id, beneficiary };
                                    val balances = list<ft3.balance>();
                                    if (account != null) {
                                    val ft3_balances = ft3.balance @* { .account == account };
                                    for (ft3_balance in ft3_balances) {
                                    val token_mapping = token_mapping @? {.asset == ft3_balance.asset};
                                    if (token_mapping != null) {
                                    if (token_mapping.token.network_id != network_id) {
                                    continue;
                                    }
                                    balances.add(ft3_balance);
                                    }
                                    }
                                    }
                                    val erc20_byte_offset = (erc20_balances.size() + balances.size()) * 2 * 32; // 2 values per entry
                                    state.add(erc20_byte_offset.to_gtv());

                                    // update state for eif balance
                                    for (balance in erc20_balances) {
                                    state.add(byte_array.from_hex("000000000000000000000000" + balance.token.address.sub(2)).to_gtv());
                                    state.add((balance.amount).to_gtv());
                                    }

                                    // update state for ft3 balance
                                    for (balance in balances) {
                                    val token_mapping = token_mapping @ {.asset == balance.asset};
                                    state.add(byte_array.from_hex("000000000000000000000000" + token_mapping.token.address.sub(2)).to_gtv());
                                    state.add((balance.amount).to_gtv());
                                    }

                                    // 1: ERC721
                                    // val erc721_balances = evm_erc721_balance @* { network_id, beneficiary };
                                    // val erc721_byte_offset = erc721_balances.size() * 2 * 32; // 2 values per entry
                                    // state.add(erc721_byte_offset.to_gtv());
                                    // for (balance in erc721_balances) {
                                    // 	state.add(byte_array.from_hex("000000000000000000000000" + balance.token.address.sub(2)).to_gtv());
                                    // 	state.add(balance.token.token_id.to_gtv());
                                    // }
                                    // Add new asset types here
                                    // ------------------------ //
                                    return state;
                                    }

                                    function deposit_ERC20(network_id: integer, beneficiary: text, token_address: text, amount: integer, name: text, symbol: text, decimals: integer) {
                                    log("deposit_ERC20: " + token_address + " : " + beneficiary + " : " + name);
                                    var token = evm_erc20 @? { network_id, .address.lower_case() == token_address.lower_case() };
                                    if (empty(token)) {
                                    token = create evm_erc20(
                                    network_id,
                                    address = token_address,
                                    name,
                                    symbol,
                                    decimals
                                    );
                                    }

                                    val balance = evm_erc20_balance @? { network_id, token, beneficiary };
                                    if (empty(balance)) {
                                    create evm_erc20_balance(
                                    network_id,
                                    token,
                                    beneficiary,
                                    amount
                                    );
                                    } else {
                                    update balance (.amount += amount);
                                    }
                                    }

                                    function deposit_ERC721(network_id: integer, beneficiary: text, token_address: text, token_id: integer, name: text, symbol: text, uri: text) {
                                    var token = evm_erc721 @? { network_id, .address.lower_case() == token_address.lower_case(), token_id };
                                    if (empty(token)) {
                                    token = create evm_erc721(
                                    network_id,
                                    address = token_address,
                                    token_id,
                                    name,
                                    symbol,
                                    uri
                                    );
                                    }

                                    create evm_erc721_balance(
                                    network_id,
                                    token,
                                    beneficiary
                                    );
                                    }

                                    function emit_withdraw(network_id: integer, beneficiary: text, account: acc.account?, eth_event_data: list<gtv>) {
                                    val account_link = get_or_create_evm_account_link(network_id, beneficiary);
                                    val state = build_account_state(network_id, beneficiary, account);
                                    val state_data = state_data(
                                    account_link.state_n,
                                    account = state
                                    );

                                    op_context.emit_event("eif_state", state_data.to_gtv());
                                    op_context.emit_event("eif_event", eth_event_data.to_gtv());
                                    }

                                    function to_zero_padded_hex(array: byte_array) = "0x" + array.to_hex();

                                    function get_eth_address(pk: byte_array) = crypto.keccak256(pk).sub(12).to_hex();

                                    function hash_eth_message(msg: text) = crypto.keccak256(("\u0019Ethereum Signed Message:\n" + msg.size().to_text() + msg).to_bytes());

                                    function is_syncing_transfers_inside_dapp() = chain_context.args.sync_transfers_inside_dapp;

                                    @extend(ft3.after_transfer) function after_transfer_eif(inputs: list<ft3.xfer_input>, outputs: list<ft3.xfer_output>) {
                                    if (not is_syncing_transfers_inside_dapp()) return;

                                    for (i in inputs) {
                                    update_account_state(i.account_id, i.asset_id);
                                    }
                                    for (o in outputs) {
                                    update_account_state(o.account_id, o.asset_id);
                                    }
                                    }

                                    function update_account_state(account_id: byte_array, asset_id: byte_array) {
                                    val account = acc.account @ { .id == account_id };
                                    val beneficiary = to_zero_padded_hex(evm.evm_account @ { .account == account } ( .address ));
                                    val asset = ft3.asset @ { .id == asset_id };
                                    val token_mapping = token_mapping @? { .asset == asset };
                                    if (empty(token_mapping)) {
                                    return;
                                    }
                                    val network_id = token_mapping.token.network_id;
                                    val account_link = get_or_create_evm_account_link(network_id, beneficiary);
                                    val state = build_account_state(network_id, beneficiary, account);
                                    val state_data = state_data(
                                    account_link.state_n,
                                    account = state
                                    );
                                    op_context.emit_event("eif_state", state_data.to_gtv());
                                    }

import ^^.ft3.account.{
account,
auth_descriptor,
create_account_with_auth
};

struct module_args {
admin_pubkey: pubkey;
}

function admin_pubkey() = chain_context.args.admin_pubkey;

function admin_auth_descriptor()
= auth_descriptor(
"S",
[chain_context.args.admin_pubkey],
[
["A", "T"].to_gtv(),
chain_context.args.admin_pubkey.to_hex().to_gtv()
],
null.to_gtv()
);

function account_id()
= admin_auth_descriptor().hash();

function register_account(): account {
val admin_auth_descriptor = admin_auth_descriptor();
val admin_account = account @? { admin_auth_descriptor.hash() };
require(empty(admin_account), "Admin account already registered");

val account_id = create_account_with_auth(admin_auth_descriptor);
return account @ { account_id };
}

function require_admin(message: text = "Admin expected") {
require(op_context.is_signer(admin_pubkey()), message);
}

namespace Boolean {
                                    entity boolean_attribute {
                                    index instance, attribute, value;
                                    index attribute, value;
                                    mutable value: boolean;
                                    }

                                    function T(value: boolean? = null): attribute_type {
                                    return attribute_type(type = Attribute.type.boolean, value = value?.to_gtv());
                                    }

                                    function create_value(instance, attribute_name: Attribute.I, value: boolean) {
                                    val attribute = Attribute.get(attribute_name);
                                    util.ensure_not_implemented(instance, attribute);
                                    Meta.Engine.execute_value(instance, attribute, value.to_gtv());
                                    Unsafe.add_value_by_attribute(instance, attribute, value);
                                    }

                                    function add_value(instance, attribute_name: Attribute.I, value: boolean) {
                                    val attribute = Attribute.get(attribute_name);
                                    util.ensure_attribute_can_be_added(instance, attribute);
                                    Meta.Engine.execute_value(instance, attribute, value.to_gtv());
                                    Unsafe.add_value_by_attribute(instance, attribute, value);
                                    }

                                    function update_value(instance, attribute_name: Attribute.I, value: boolean) {
                                    val attribute = Attribute.get(attribute_name);
                                    Meta.Engine.execute_value(instance, attribute, value.to_gtv());
                                    Unsafe.update_value_by_attribute(instance, attribute, value);
                                    }

                                    function set_value(instance, attribute_name: Attribute.I, value: boolean) {
                                    val attribute = Attribute.get(attribute_name);
                                    var attr = boolean_attribute @? {instance, attribute};
                                    if(attr == null) {
                                    add_value(instance, attribute_name, value);
                                    } else {
                                    update_value(instance, attribute_name, value);
                                    }
                                    }

                                    function remove_value(instance, attribute_name: Attribute.I): boolean {
                                    val attribute = Attribute.get(attribute_name);
                                    util.ensure_optional(attribute);
                                    return Unsafe.remove_value_by_attribute(instance, attribute);
                                    }

                                    function get_value (instance, attribute_name: Attribute.I): boolean? {
                                    val attribute = Attribute.get(attribute_name);
                                    var attr = boolean_attribute @? { instance, attribute };

                                    if(attr??) {
                                    return attr.value;
                                    } else {
                                    val prototypes = Prototype.get_all(instance);
                                    for (p in prototypes) {
                                    attr = boolean_attribute @? { p, attribute };
                                    if(attr??) {
                                    return attr.value;
                                    }
                                    }
                                    }
                                    return null;
                                    }

                                    function get_value_as_text(instance, attribute_name: Attribute.I): text {
                                    return "%s".format(get_value(instance, attribute_name));
                                    }

                                    function fetch_range_from(attribute, value: boolean, from: rowid, _limit: integer = 100) {
                                    return boolean_attribute @* {
                                    attribute, .value == value, .instance.rowid > from
                                    } (.instance) limit _limit;
                                    }

                                    function apply_filter(instances: list<instance>, filter: Filter.I_by_attribute, from: Filter.p_from):
                                    (results: list<instance>, from: Filter.p_from?) {
                                    val limit_count = 100;
                                    val attribute = filter.attribute;
                                    val value = boolean.from_gtv(filter.parameter);

                                    if(instances.empty()) {
                                    val attribute_name = Attribute.def_I(attribute.dclass.name, attribute.name);
                                    return Attribute.find_instances(attribute_name, value.to_gtv(), from, limit_count);
                                    };

                                    var res = list<instance>();

                                    val first = instances[0];
                                    val last = instances[instances.size() - 1];

                                    val in_prototype = (a: boolean_attribute, ip: instance_prototype) @* {
                                    a.attribute == attribute, a.value == value,
                                    ip.prototype == a.instance,
                                    ip.instance >= first, ip.instance <= last
                                    } (ip.instance) limit limit_count;

                                    res.add_all(in_prototype);

                                    val in_attribute = (a: boolean_attribute) @* {
                                    attribute,
                                    a.value == value,
                                    a.instance >= first, a.instance <= last
                                    } (a.instance) limit limit_count;

                                    res.add_all(in_attribute);

                                    val prior_instances = set(instances);
                                    res = res @* {prior_instances.contains($)};

                                    return (results = res, from = null);
                                    }
                                    }

                                    namespace Boolean.Unsafe {
                                    function add_value (instance, attribute_name: Attribute.I, value: boolean) {
                                    val attribute = Attribute.get(attribute_name);
                                    add_value_by_attribute(instance, attribute, value);
                                    }

                                    function add_value_by_attribute(instance, attribute, value: boolean) {
                                    util.ensure_type(Attribute.type.boolean, attribute.type);
                                    Hooks.before_add_value(instance, attribute, value);
                                    val boolean_attribute = create boolean_attribute ( instance, attribute, value );
                                    Hooks.after_add_value(boolean_attribute);
                                    }

                                    function update_value (instance, attribute_name: Attribute.I, value: boolean) {
                                    val attribute = Attribute.get(attribute_name);
                                    update_value_by_attribute(instance, attribute, value);
                                    }

                                    function update_value_by_attribute (instance, attribute, value: boolean) {
                                    util.ensure_type(Attribute.type.boolean, attribute.type);
                                    val boolean_attribute = boolean_attribute @ { instance, attribute };

                                    Hooks.before_update_value(boolean_attribute, value);
                                    if (boolean_attribute.value != value) {
                                    boolean_attribute.value = value;
                                    }
                                    Hooks.after_update_value(boolean_attribute);
                                    }

                                    function set_value(instance, attribute_name: Attribute.I, value: boolean) {
                                    val attribute = Attribute.get(attribute_name);
                                    set_value_by_attribute(instance, attribute, value);
                                    }

                                    function set_value_by_attribute(instance, attribute, value: boolean) {
                                    var attr = boolean_attribute @? {instance, attribute};

                                    Hooks.before_set_value(instance, attribute, attr, value);
                                    if(attr == null) {
                                    attr = create boolean_attribute ( instance, attribute, value );
                                    } else {
                                    attr.value = value;
                                    }
                                    Hooks.after_set_value(attr);
                                    }

                                    function remove_value (instance, attribute_name: Attribute.I): boolean {
                                    val attribute = Attribute.get(attribute_name);
                                    return remove_value_by_attribute(instance, attribute);
                                    }

                                    function remove_value_by_attribute (instance, attribute): boolean {
                                    val boolean_attribute = boolean_attribute @ {instance, attribute};
                                    val value = boolean_attribute.value;

                                    Hooks.before_remove_value(boolean_attribute);
                                    delete boolean_attribute;
                                    Hooks.after_remove_value(instance, attribute, value);

                                    return value;
                                    }
                                    }

                                    namespace Boolean.Hooks {
                                    @extendable
                                    function before_add_value(instance, attribute, value: boolean);

                                    @extendable
                                    function after_add_value(boolean_attribute);

                                    @extendable
                                    function before_remove_value(boolean_attribute);

                                    @extendable
                                    function after_remove_value(instance, attribute, value: boolean);

                                    @extendable
                                    function before_update_value(boolean_attribute, value: boolean);

                                    @extendable
                                    function after_update_value(boolean_attribute);

                                    @extendable
                                    function before_set_value(instance, attribute, boolean_attribute?, value: boolean);

                                    @extendable
                                    function after_set_value(boolean_attribute);
                                    }

                                    namespace Boolean.Private {
                                    function is_unique_value(instance, attribute, value: boolean) {
                                    val boolean_attribute = boolean_attribute @? { attribute, value } limit 1;
                                    return boolean_attribute == null or boolean_attribute.instance == instance;
                                    }
                                    }

namespace ByteArray {
                                    entity byte_array_attribute {
                                    index instance, attribute, value;
                                    index attribute, value;
                                    mutable value: byte_array;
                                    }

                                    function T(value: byte_array? = null): attribute_type {
                                    return attribute_type(type = Attribute.type.byte_array, value = value?.to_gtv());
                                    }

                                    function create_value(instance, attribute_name: Attribute.I, value: byte_array) {
                                    val attribute = Attribute.get(attribute_name);
                                    util.ensure_not_implemented(instance, attribute);
                                    Meta.Engine.execute_value(instance, attribute, value.to_gtv());
                                    Unsafe.add_value_by_attribute(instance, attribute, value);
                                    }

                                    function add_value(instance, attribute_name: Attribute.I, value: byte_array) {
                                    val attribute = Attribute.get(attribute_name);
                                    util.ensure_attribute_can_be_added(instance, attribute);
                                    Meta.Engine.execute_value(instance, attribute, value.to_gtv());
                                    Unsafe.add_value_by_attribute(instance, attribute, value);
                                    }

                                    function update_value(instance, attribute_name: Attribute.I, value: byte_array) {
                                    val attribute = Attribute.get(attribute_name);
                                    Meta.Engine.execute_value(instance, attribute, value.to_gtv());
                                    Unsafe.update_value_by_attribute(instance, attribute, value);
                                    }

                                    function set_value(instance, attribute_name: Attribute.I, value: byte_array) {
                                    val attribute = Attribute.get(attribute_name);
                                    var attr = byte_array_attribute @? {instance, attribute};
                                    if(attr == null) {
                                    add_value(instance, attribute_name, value);
                                    } else {
