                                    return Attribute.find_instances(attribute_name, value.to_gtv(), from, limit_count);
                                    };

                                    var res = list<instance>();

                                    val first = instances[0];
                                    val last = instances[instances.size() - 1];

                                    val in_prototype = (a: instance_attribute, ip: instance_prototype) @* {
                                    a.attribute == attribute, a.value == value,
                                    ip.prototype == a.instance,
                                    ip.instance >= first, ip.instance <= last
                                    } (ip.instance) limit limit_count;

                                    res.add_all(in_prototype);

                                    val in_attribute = (a: instance_attribute) @* {
                                    attribute,
                                    a.value == value,
                                    a.instance >= first, a.instance <= last
                                    } (a.instance) limit limit_count;

                                    res.add_all(in_attribute);

                                    val prior_instances = set(instances);
                                    res = res @* {prior_instances.contains($)};

                                    return (results = res, from = null);
                                    }
                                    }

                                    namespace Instance.Unsafe {
                                    function add_value (instance, attribute_name: Attribute.I, value: instance) {
                                    val attribute = Attribute.get(attribute_name);
                                    add_value_by_attribute(instance, attribute, value);
                                    }

                                    function add_value_by_attribute(instance, attribute, value: instance) {
                                    util.ensure_type(Attribute.type.instance, attribute.type);
                                    Hooks.before_add_value(instance, attribute, value);
                                    val instance_attribute = create instance_attribute ( instance, attribute, value );
                                    Hooks.after_add_value(instance_attribute);
                                    }

                                    function update_value (instance, attribute_name: Attribute.I, value: instance) {
                                    val attribute = Attribute.get(attribute_name);
                                    update_value_by_attribute(instance, attribute, value);
                                    }

                                    function update_value_by_attribute (instance, attribute, value: instance) {
                                    util.ensure_type(Attribute.type.instance, attribute.type);
                                    val instance_attribute = instance_attribute @ { instance, attribute };

                                    Hooks.before_update_value(instance_attribute, value);
                                    if (instance_attribute.value != value) {
                                    instance_attribute.value = value;
                                    }
                                    Hooks.after_update_value(instance_attribute);
                                    }

                                    function set_value(instance, attribute_name: Attribute.I, value: instance) {
                                    val attribute = Attribute.get(attribute_name);
                                    set_value_by_attribute(instance, attribute, value);
                                    }

                                    function set_value_by_attribute(instance, attribute, value: instance) {
                                    var attr = instance_attribute @? {instance, attribute};
                                    Hooks.before_set_value(instance, attribute, attr, value);
                                    if (attr == null) {
                                    attr = create instance_attribute ( instance, attribute, value );
                                    } else {
                                    attr.value = value;
                                    }
                                    Hooks.after_set_value(attr);
                                    }

                                    function remove_value (instance, attribute_name: Attribute.I): instance {
                                    val attribute = Attribute.get(attribute_name);
                                    return remove_value_by_attribute(instance, attribute);
                                    }

                                    function remove_value_by_attribute (instance, attribute): instance {
                                    val instance_attribute = instance_attribute @ {instance, attribute};
                                    val value = instance_attribute.value;

                                    Hooks.before_remove_value(instance_attribute);
                                    delete instance_attribute;
                                    Hooks.after_remove_value(instance, attribute, value);

                                    return value;
                                    }
                                    }


                                    namespace Instance.Hooks {
                                    @extendable
                                    function before_add_value(instance, attribute, value: instance);

                                    @extendable
                                    function after_add_value(instance_attribute);

                                    @extendable
                                    function before_remove_value(instance_attribute);

                                    @extendable
                                    function after_remove_value(instance, attribute, value: instance);

                                    @extendable
                                    function before_update_value(instance_attribute, value: instance);

                                    @extendable
                                    function after_update_value(instance_attribute);

                                    @extendable
                                    function before_set_value(instance, attribute, instance_attribute?, value: instance);

                                    @extendable
                                    function after_set_value(instance_attribute);
                                    }

                                    namespace Instance.Private {
                                    function is_unique_value(instance, attribute, value: instance) {
                                    // How to compare instances?
                                    require(false, "instance is_unique_value: Not implemented");
                                    return true;
                                    }
                                    }

namespace Integer {
                                    entity integer_attribute {
                                    index instance, attribute, value;
                                    index attribute, value;
                                    mutable value: integer;
                                    }

                                    function T(value: integer? = null): attribute_type {
                                    return attribute_type(type = Attribute.type.integer, value = value?.to_gtv());
                                    }

                                    function create_value(instance, attribute_name: Attribute.I, value: integer) {
                                    val attribute = Attribute.get(attribute_name);
                                    util.ensure_not_implemented(instance, attribute);
                                    Meta.Engine.execute_value(instance, attribute, value.to_gtv());
                                    Unsafe.add_value_by_attribute(instance, attribute, value);
                                    }

                                    function add_value(instance, attribute_name: Attribute.I, value: integer) {
                                    val attribute = Attribute.get(attribute_name);
                                    util.ensure_attribute_can_be_added(instance, attribute);
                                    Meta.Engine.execute_value(instance, attribute, value.to_gtv());
                                    Unsafe.add_value_by_attribute(instance, attribute, value);
                                    }

                                    function update_value(instance, attribute_name: Attribute.I, value: integer) {
                                    val attribute = Attribute.get(attribute_name);
                                    Meta.Engine.execute_value(instance, attribute, value.to_gtv());
                                    Unsafe.update_value_by_attribute(instance, attribute, value);
                                    }

                                    function set_value(instance, attribute_name: Attribute.I, value: integer) {
                                    val attribute = Attribute.get(attribute_name);
                                    var attr = integer_attribute @? {instance, attribute};
                                    if(attr == null) {
                                    add_value(instance, attribute_name, value);
                                    } else {
                                    update_value(instance, attribute_name, value);
                                    }
                                    }

                                    function remove_value(instance, attribute_name: Attribute.I): integer {
                                    val attribute = Attribute.get(attribute_name);
                                    util.ensure_optional(attribute);
                                    return Unsafe.remove_value_by_attribute(instance, attribute);
                                    }

                                    function get_value (instance, attribute_name: Attribute.I): integer? {
                                    val attribute = Attribute.get(attribute_name);
                                    var attr = integer_attribute @? { instance, attribute };

                                    if(attr??) {
                                    return attr.value;
                                    } else {
                                    val prototypes = Prototype.get_all(instance);
                                    for (p in prototypes) {
                                    attr = integer_attribute @? { p, attribute };
                                    if(attr??) {
                                    return attr.value;
                                    }
                                    }
                                    }
                                    return null;
                                    }

                                    function get_value_as_text(instance, attribute_name: Attribute.I): text {
                                    return "%s".format(get_value(instance, attribute_name));
                                    }

                                    function fetch_range_from(attribute, value: integer, from: rowid, _limit: integer = 100) {
                                    return integer_attribute @* {
                                    attribute, .value == value, .instance.rowid > from
                                    } (.instance) limit _limit;
                                    }

                                    function apply_filter(instances: list<instance>, filter: Filter.I_by_attribute, from: Filter.p_from):
                                    (results: list<instance>, from: Filter.p_from?) {
                                    val limit_count = 100;
                                    val attribute = filter.attribute;
                                    val value = integer.from_gtv(filter.parameter);

                                    if(instances.empty()) {
                                    val attribute_name = Attribute.def_I(attribute.dclass.name, attribute.name);
                                    return Attribute.find_instances(attribute_name, value.to_gtv(), from, limit_count);
                                    };

                                    var res = list<instance>();

                                    val first = instances[0];
                                    val last = instances[instances.size() - 1];

                                    val in_prototype = (a: integer_attribute, ip: instance_prototype) @* {
                                    a.attribute == attribute, a.value == value,
                                    ip.prototype == a.instance,
                                    ip.instance >= first, ip.instance <= last
                                    } (ip.instance) limit limit_count;

                                    res.add_all(in_prototype);

                                    val in_attribute = (a: integer_attribute) @* {
                                    attribute,
                                    a.value == value,
                                    a.instance >= first, a.instance <= last
                                    } (a.instance) limit limit_count;

                                    res.add_all(in_attribute);

                                    val prior_instances = set(instances);
                                    res = res @* {prior_instances.contains($)};

                                    return (results = res, from = null);
                                    }
                                    }

                                    namespace Integer.Unsafe {
                                    function add_value (instance, attribute_name: Attribute.I, value: integer) {
                                    val attribute = Attribute.get(attribute_name);
                                    add_value_by_attribute(instance, attribute, value);
                                    }

                                    function add_value_by_attribute(instance, attribute, value: integer) {
                                    util.ensure_type(Attribute.type.integer, attribute.type);
                                    Hooks.before_add_value(instance, attribute, value);
                                    val integer_attribute = create integer_attribute ( instance, attribute, value );
                                    Hooks.after_add_value(integer_attribute);
                                    }

                                    function update_value (instance, attribute_name: Attribute.I, value: integer) {
                                    val attribute = Attribute.get(attribute_name);
                                    update_value_by_attribute(instance, attribute, value);
                                    }

                                    function update_value_by_attribute (instance, attribute, value: integer) {
                                    util.ensure_type(Attribute.type.integer, attribute.type);
                                    val integer_attribute = require(
                                    integer_attribute @? { instance, attribute }
                                    );

                                    Hooks.before_update_value(integer_attribute, value);
                                    if (integer_attribute.value != value) {
                                    integer_attribute.value = value;
                                    }
                                    Hooks.after_update_value(integer_attribute);
                                    }

                                    function set_value(instance, attribute_name: Attribute.I, value: integer) {
                                    val attribute = Attribute.get(attribute_name);
                                    set_value_by_attribute(instance, attribute, value);
                                    }

                                    function set_value_by_attribute(instance, attribute, value: integer) {
                                    var attr = integer_attribute @? {instance, attribute};
                                    Hooks.before_set_value(instance, attribute, attr, value);
                                    if(attr == null) {
                                    attr = create integer_attribute ( instance, attribute, value );
                                    } else {
                                    attr.value = value;
                                    }
                                    Hooks.after_set_value(attr);
                                    }

                                    function remove_value (instance, attribute_name: Attribute.I): integer {
                                    val attribute = Attribute.get(attribute_name);
                                    return remove_value_by_attribute(instance, attribute);
                                    }

                                    function remove_value_by_attribute (instance, attribute): integer {
                                    val i = integer_attribute @ {instance, attribute};
                                    val value = i.value;
                                    Hooks.before_remove_value(i);
                                    delete i;
                                    Hooks.after_remove_value(attribute, value);
                                    return value;
                                    }
                                    }

                                    namespace Integer.Hooks {
                                    @extendable
                                    function before_add_value(instance, attribute, value: integer);

                                    @extendable
                                    function after_add_value(integer_attribute);

                                    @extendable
                                    function before_remove_value(integer_attribute);

                                    @extendable
                                    function after_remove_value(attribute, value: integer);

                                    @extendable
                                    function before_update_value(integer_attribute, value: integer);

                                    @extendable
                                    function after_update_value(integer_attribute);

                                    @extendable
                                    function before_set_value(instance, attribute, integer_attribute?, value: integer);

                                    @extendable
                                    function after_set_value(integer_attribute);
                                    }

                                    namespace Integer.Private {
                                    function is_unique_value(instance, attribute, value: integer) {
                                    val integer_attribute = integer_attribute @? { attribute, value } limit 1;
                                    return integer_attribute == null or integer_attribute.instance == instance;
                                    }
                                    }

namespace ListInstanceDef {
function T(instance_defs: list<attribute_type>) {
return attribute_type(
type = Attribute.type.ordered_container,
value = instance_defs.to_gtv(),
inner_type = Attribute.type.instance_def.to_gtv()
);
}
}

namespace List {
entity list_attribute {
index instance, attribute;
}

function T(inner_type: Attribute.type, value: gtv? = null): attribute_type {
return attribute_type(inner_type = inner_type.to_gtv(), type = Attribute.type.ordered_container, value = value?.to_gtv());
}

function create_type(attribute, value_type: Attribute.type) {
util.ensure_simple_type(value_type);
Map.create_type(attribute, Attribute.type.integer, value_type);
}

function create_elements(instance, attribute_name: Attribute.I, elements: gtv) {
val attribute = Attribute.get(attribute_name);
util.ensure_not_implemented(instance, attribute);
Meta.Engine.execute_value(instance, attribute, elements);
Unsafe.add_elements_by_attribute(instance, attribute, elements);
}

function add_elements(instance, attribute_name: Attribute.I, elements: gtv) {
val attribute = Attribute.get(attribute_name);
util.ensure_attribute_can_be_added(instance, attribute);
Meta.Engine.execute_value(instance, attribute, elements);
Unsafe.add_elements_by_attribute(instance, attribute, elements);
}

function update_elements(instance, attribute_name: Attribute.I, elements: gtv) {
val attribute = Attribute.get(attribute_name);
Meta.Engine.execute_value(instance, attribute, elements);
Unsafe.update_elements_by_attribute(instance, attribute, elements);
}

function set_elements(instance, attribute_name: Attribute.I, elements: gtv) {
val attribute = Attribute.get(attribute_name);
var attr = list_attribute @? {instance, attribute};
if(attr == null) {
add_elements(instance, attribute_name, elements);
} else {
update_elements(instance, attribute_name, elements);
}
}

function remove_elements(instance, attribute_name: Attribute.I): gtv {
val attribute = Attribute.get(attribute_name);
util.ensure_optional(attribute);
return Unsafe.remove_elements_by_attribute(instance, attribute);
}

function add_element(instance, attribute_name: Attribute.I, element: gtv) {
val attribute = Attribute.get(attribute_name);
Meta.Engine.execute_value(instance, attribute, element);
Unsafe.add_by_attribute(instance, attribute, element);
}

function remove_element(instance, attribute_name: Attribute.I, element: gtv) {
val attribute = Attribute.get(attribute_name);
Meta.Engine.execute_value(instance, attribute, element);
Unsafe.remove_by_attribute(instance, attribute, element);
}

function unpack(instance, attribute_name: Attribute.I): (type: Attribute.type, values: gtv)? {
val attribute = Attribute.get(attribute_name);
return unpack_by_attribute(instance, attribute);
}

function get_value_as_text(instance, attribute_name: Attribute.I): text {
require(false, "list get_value_as_text: Not implementation");
return "";
}

function unpack_by_attribute(instance, attribute): (type: Attribute.type, values: gtv)? {
val list_attrs = _get_list_types(attribute);
if (not util.is_implemented(instance, attribute)) return null;

var ret: gtv? = null;
val instances = Prototype.get_all(instance);
instances.add(instance);

when (list_attrs.V.type) {
Attribute.type.boolean -> ret = (i: Instance.instance_attribute, k: Integer.integer_attribute, v: Boolean.boolean_attribute) @* {
i.value in instances,
i.attribute == list_attrs.I,
i.instance == k.instance,
i.instance == v.instance,
k.attribute == list_attrs.K,
v.attribute == list_attrs.V
} (v.value, @sort @omit k.value).to_gtv();
Attribute.type.byte_array -> ret = (i: Instance.instance_attribute, k: Integer.integer_attribute, v: ByteArray.byte_array_attribute) @* {
i.value in instances,
i.attribute == list_attrs.I,
i.instance == k.instance,
i.instance == v.instance,
k.attribute == list_attrs.K,
v.attribute == list_attrs.V
} (v.value, @sort @omit k.value).to_gtv();
Attribute.type.decimal -> ret = (i: Instance.instance_attribute, k: Integer.integer_attribute, v: Decimal.decimal_attribute) @* {
i.value in instances,
i.attribute == list_attrs.I,
i.instance == k.instance,
i.instance == v.instance,
k.attribute == list_attrs.K,
v.attribute == list_attrs.V
} (v.value, @sort @omit k.value).to_gtv();
Attribute.type.instance -> ret = (i: Instance.instance_attribute, k: Integer.integer_attribute, v: Instance.instance_attribute) @* {
i.value in instances,
i.attribute == list_attrs.I,
i.instance == k.instance,
i.instance == v.instance,
k.attribute == list_attrs.K,
v.attribute == list_attrs.V
} (v.value, @sort @omit k.value).to_gtv();
Attribute.type.integer -> ret = (i: Instance.instance_attribute, k: Integer.integer_attribute, v: Integer.integer_attribute) @* {
i.value in instances,
i.attribute == list_attrs.I,
i.instance == k.instance,
i.instance == v.instance,
k.attribute == list_attrs.K,
v.attribute == list_attrs.V
} (v.value, @sort @omit k.value).to_gtv();
Attribute.type.text -> ret = (i: Instance.instance_attribute, k: Integer.integer_attribute, v: Text.text_attribute) @* {
i.value in instances,
i.attribute == list_attrs.I,
i.instance == k.instance,
i.instance == v.instance,
k.attribute == list_attrs.K,
v.attribute == list_attrs.V
} (v.value, @sort @omit k.value).to_gtv();
else -> require(false, "Unimplemented path");
}

return (type = list_attrs.V.type, values = ret!!);
}

function sizeof(instance, attribute_name: Attribute.I) {
return Map.sizeof(instance, attribute_name);
}

function contains(instance, attribute_name: Attribute.I, value: gtv) {
val attribute = Attribute.get(attribute_name);
val list_attrs = _get_list_types(attribute);
return Map._find_instance_by_value_in_map(instance, value, list_attrs) != null;
}

function contains_all(instance, attribute_name: Attribute.I, values: gtv) {
val attribute = Attribute.get(attribute_name);
val list_attrs = _get_list_types(attribute);
val l = util.gtv_to_list_of_gtv(values, list_attrs.V.type);

for (e in l) {
if (Map._find_instance_by_value_in_map(instance, e, list_attrs) == null) {
return false;
}
}

return true;
}

function get(instance, attribute_name: Attribute.I, idx: integer) {
return Map.get(instance, attribute_name, idx.to_gtv());
}

function is_empty(instance, attribute_name: Attribute.I) {
return Map.sizeof(instance, attribute_name) == 0;
}

function fetch_range_from(attribute, value: gtv, from: rowid) {
val list_attrs = _get_list_types(attribute);

when (list_attrs.V.type) {
Attribute.type.boolean -> return (i: Instance.instance_attribute, a: Boolean.boolean_attribute) @* {
a.attribute == list_attrs.V,
a.value == boolean.from_gtv(value),
i.attribute == list_attrs.I,
i.instance == a.instance,
i.value.rowid > from
} (i.value) limit 100;
Attribute.type.byte_array -> return (i: Instance.instance_attribute, a: ByteArray.byte_array_attribute) @* {
a.attribute == list_attrs.V,
a.value == byte_array.from_gtv(value),
i.attribute == list_attrs.I,
i.instance == a.instance,
i.value.rowid > from
} (i.value) limit 100;
Attribute.type.decimal -> return (i: Instance.instance_attribute, a: Decimal.decimal_attribute) @* {
a.attribute == list_attrs.V,
a.value == decimal.from_gtv(value),
i.attribute == list_attrs.I,
i.instance == a.instance,
i.value.rowid > from
} (i.value) limit 100;
Attribute.type.instance -> return (i: Instance.instance_attribute, a: Instance.instance_attribute) @* {
a.attribute == list_attrs.V,
a.value == instance.from_gtv(value),
i.attribute == list_attrs.I,
i.instance == a.instance,
i.value.rowid > from
} (i.value) limit 100;
Attribute.type.integer -> return (i: Instance.instance_attribute, a: Integer.integer_attribute) @* {
a.attribute == list_attrs.V,
a.value == integer.from_gtv(value),
i.attribute == list_attrs.I,
i.instance == a.instance,
i.value.rowid > from
} (i.value) limit 100;
Attribute.type.text -> return (i: Instance.instance_attribute, a: Text.text_attribute) @* {
a.attribute == list_attrs.V,
a.value == text.from_gtv(value),
i.attribute == list_attrs.I,
i.instance == a.instance,
i.value.rowid > from
} (i.value) limit 100;
else -> {require(false, "Unimplemented path"); return list<instance>();}
}
}

function _get_list_types(attr: attribute): (K: attribute, V: attribute, I: attribute) {
return Map._get_map_types(attr);
}

function _index_of(instance, attribute, value: gtv): integer {
val list_attrs = _get_list_types(attribute);
val f = Map._find_instance_by_value_in_map(instance, value, list_attrs);
if (f??) {
return Integer.integer_attribute @ {f.instance, list_attrs.K}.value;
}

return -1;
}
}

namespace List.Unsafe {

function add_elements (instance, attribute_name: Attribute.I, elements: gtv) {
val attribute = Attribute.get(attribute_name);
add_elements_by_attribute(instance, attribute, elements);
}

function add_elements_by_attribute (instance, attribute, elements: gtv) {
util.ensure_type(Attribute.type.ordered_container, attribute.type);

val list_attrs = _get_list_types(attribute);
var m = _list_to_map(util.gtv_to_list_of_gtv(elements, list_attrs.V.type));

create list_attribute (instance, attribute);
Map.Unsafe._create_map_attribute(instance, attribute, m.to_gtv());
}

function update_elements(instance, attribute_name: Attribute.I, elements: gtv) {
val attribute = Attribute.get(attribute_name);
update_elements_by_attribute(instance, attribute, elements);
}

function update_elements_by_attribute(instance, attribute, elements: gtv) {
val list_attrs = _get_list_types(attribute);
val l = util.gtv_to_list_of_gtv(elements, list_attrs.V.type);
val m = _list_to_map(l);

Map.Unsafe.update_elements_by_attribute(instance, attribute, m.to_gtv());
}

function set_elements(instance, attribute_name: Attribute.I, elements: gtv) {
val attribute = Attribute.get(attribute_name);
set_elements_by_attribute(instance, attribute, elements);
}

function set_elements_by_attribute(instance, attribute, elements: gtv) {
var attr = list_attribute @? {instance, attribute};
if(attr == null) {
add_elements_by_attribute(instance, attribute, elements );
} else {
update_elements_by_attribute(instance, attribute, elements );
}
}

function remove_elements(instance, attribute_name: Attribute.I): gtv {
val attribute = Attribute.get(attribute_name);
return remove_elements_by_attribute(instance, attribute);
}

function remove_elements_by_attribute(instance, attribute): gtv {
val l = unpack_by_attribute(instance, attribute);

clear_by_attribute(instance, attribute);
delete list_attribute @ {instance, attribute};

return l!!.to_gtv();
}

function add(instance, attribute_name: Attribute.I, value: gtv, pos: integer = -1) {
val attribute = Attribute.get(attribute_name);
add_by_attribute(instance, attribute, value, pos);
}

function add_by_attribute(instance, attribute, value: gtv, pos: integer = -1) {
val list_attrs = _get_list_types(attribute);
val add_pos = _get_list_add_position(instance, attribute, list_attrs, pos);

Map.Unsafe.put_by_attribute(instance, attribute, (add_pos.to_gtv(), value).to_gtv());
}

function add_all(instance, attribute_name: Attribute.I, values: gtv, pos: integer = -1) {
val attribute = Attribute.get(attribute_name);
add_all_by_attribute(instance, attribute, values, pos);
}

function add_all_by_attribute(instance, attribute, values: gtv, pos: integer = -1) {
val list_attrs = _get_list_types(attribute);
val l = util.gtv_to_list_of_gtv(values, list_attrs.V.type);
val add_pos = _get_list_add_position(instance, attribute, list_attrs, pos, l.size());

val m = _list_to_map(l, add_pos);
Map.Unsafe.put_all_by_attribute(instance, attribute, m);
}

function clear(instance, attribute_name: Attribute.I) {
val attribute = Attribute.get(attribute_name);
clear_by_attribute(instance, attribute);
}

function clear_by_attribute(instance, attribute) {
Map.Unsafe.clear_by_attribute(instance, attribute);
}

function remove(instance, attribute_name: Attribute.I, value: gtv) {
val attribute = Attribute.get(attribute_name);
remove_by_attribute(instance, attribute, value);
}

function remove_by_attribute(instance, attribute, value: gtv) {
val list_attrs = _get_list_types(attribute);
Map.Unsafe._map_remove(instance, list_attrs.V, list_attrs.I, list_attrs.K, value);
_reduce_list_position(instance, list_attrs, _index_of(instance, attribute, value));
}

function remove_all(instance, attribute_name: Attribute.I, values: gtv) {
val attribute = Attribute.get(attribute_name);
remove_all_by_attribute(instance, attribute, values);
}

function remove_all_by_attribute(instance, attribute, values: gtv) {
val list_attrs = _get_list_types(attribute);
val l = util.gtv_to_list_of_gtv(values, list_attrs.V.type);

for (e in l) {
Map.Unsafe._map_remove(instance, list_attrs.V, list_attrs.I, list_attrs.K, e);
}
_reduce_list_position(instance, list_attrs, _index_of(instance, attribute, l[0]), l.size());
}

function remove_at(instance, attribute_name: Attribute.I, idx: integer) {
val attribute = Attribute.get(attribute_name);
remove_at_by_attribute(instance, attribute, idx);
}

function remove_at_by_attribute(instance, attribute, idx: integer) {
val list_attrs = _get_list_types(attribute);
Map.Unsafe.remove_by_attribute(instance, attribute, idx.to_gtv());
_reduce_list_position(instance, list_attrs, idx);
}

function _reduce_list_position(
instance,
list_attrs: (K: attribute, V: attribute, I: attribute),
pos: integer, elements: integer = 1
) {
update (a: Integer.integer_attribute, i: Instance.instance_attribute) @* {
i.value == instance,
i.instance == a.instance,
i.attribute == list_attrs.I,
a.attribute == list_attrs.K,
a.value >= pos
} (a.value - elements);
}

function _list_to_map(values: list<gtv>, pos: integer = 0) {
val m = map<gtv,gtv>();
var i = pos;

for (value in values) {
m.put(i.to_gtv(), value);
i++;
}
return m;
}

function _get_list_add_position(instance, attribute,
list_attrs: (K: attribute, V: attribute, I: attribute), pos: integer, elements: integer = 1
) {
if (pos >= 0) {
update (a: Integer.integer_attribute, i: Instance.instance_attribute) @* {
i.value == instance,
i.instance == a.instance,
i.attribute == list_attrs.I,
a.attribute == list_attrs.K,
a.value >= pos
} (a.value + elements);

return pos;
}

return Map.sizeof_by_attribute(instance, attribute);
}
}

namespace List.Private {
function is_unique_value(instance, attribute, elements: gtv) {
require(false, "list is_unique_value: Not implemented");
return true;
}
}

namespace Map {
val MAP = "/map";
val MAP_K = "/key";
val MAP_V = "/value";
val MAP_I = "/instance";

struct types {
K: Attribute.type;
V: Attribute.type;
}

entity map_attribute {
index instance, attribute;
}

function T(inner_types: types, value: map<gtv, gtv>? = null): attribute_type {
return attribute_type(inner_type = inner_types.to_gtv(), type = Attribute.type.addressable_container, value = value?.to_gtv());
}

function create_type(attribute, key_type: Attribute.type, value_type: Attribute.type) {
util.ensure_simple_type(key_type);
util.ensure_simple_type(value_type);

require(key_type in [Attribute.type.integer, Attribute.type.text], "Invalid key type, only integer and text are allowed");

val elements_dclass = create Interface.dclass(.name = attribute.dclass.name + attribute.name + MAP);
val key_attribute = create attribute(elements_dclass, attribute.name + MAP_K, key_type);
val value_attribute = create attribute(elements_dclass, attribute.name + MAP_V, value_type);
val instance_attribute = create attribute(elements_dclass, attribute.name + MAP_I, Attribute.type.instance);
}

function create_elements(instance, attribute_name: Attribute.I, elements: gtv) {
val attribute = Attribute.get(attribute_name);
util.ensure_not_implemented(instance, attribute);
Meta.Engine.execute_value(instance, attribute, elements);
Unsafe.add_elements_by_attribute(instance, attribute, elements);
}

function add_elements(instance, attribute_name: Attribute.I, elements: gtv) {
val attribute = Attribute.get(attribute_name);
util.ensure_attribute_can_be_added(instance, attribute);
Meta.Engine.execute_value(instance, attribute, elements);
Unsafe.add_elements_by_attribute(instance, attribute, elements);
}

function update_elements(instance, attribute_name: Attribute.I, elements: gtv) {
val attribute = Attribute.get(attribute_name);
Meta.Engine.execute_value(instance, attribute, elements);
Unsafe.update_elements_by_attribute(instance, attribute, elements);
}

function set_elements(instance, attribute_name: Attribute.I, elements: gtv) {
val attribute = Attribute.get(attribute_name);
var attr = map_attribute @? {instance, attribute};
if(attr == null) {
add_elements(instance, attribute_name, elements);
} else {
update_elements(instance, attribute_name, elements);
}
}

function remove_elements(instance, attribute_name: Attribute.I): gtv {
val attribute = Attribute.get(attribute_name);
util.ensure_optional(attribute);
return Unsafe.remove_elements_by_attribute(instance, attribute);
}

function add_element(instance, attribute_name: Attribute.I, element: gtv) {
val attribute = Attribute.get(attribute_name);
Meta.Engine.execute_value(instance, attribute, element);
Unsafe.put_by_attribute(instance, attribute, element);
}

function remove_element(instance, attribute_name: Attribute.I, element: gtv) {
val attribute = Attribute.get(attribute_name);
Meta.Engine.execute_value(instance, attribute, element);
Unsafe.remove_by_attribute(instance, attribute, element);
}

function unpack(instance, attribute_name: Attribute.I): (types: (K: Attribute.type, V: Attribute.type), values: map<gtv, gtv>)? {
val attribute = Attribute.get(attribute_name);
return unpack_by_attribute(instance, attribute);
}

function get_value_as_text(instance, attribute_name: Attribute.I): text {
require(false, "map get_value_as_text: Not implementation");
return "";
}

function unpack_by_attribute(instance, attribute): (types: (K: Attribute.type, V: Attribute.type), values: map<gtv, gtv>)? {
val map_attrs = _get_map_types(attribute);
if (not util.is_implemented(instance, attribute)) return null;

val instances = Instance.instance_attribute @* {.value == instance, map_attrs.I};
var ret = map<gtv, gtv>();

for (i in instances) {
ret.put(_get_map_value_by_instance(i.instance, map_attrs.K)!!, _get_map_value_by_instance(i.instance, map_attrs.V)!!);
}

return (types = (K=map_attrs.K.type, V=map_attrs.V.type), values = ret);
}

function get(instance, attribute_name: Attribute.I, idx: gtv): gtv {
val attribute = Attribute.get(attribute_name);
val map_attrs = _get_map_types(attribute);
val instance_attr = _find_instance_by_key_in_map(instance, idx, map_attrs)!!;

return _get_map_value_by_instance(instance_attr.instance, map_attrs.V)!!;
}

function sizeof(instance, attribute_name: Attribute.I): integer {
val attribute = Attribute.get(attribute_name);
return sizeof_by_attribute(instance, attribute);
}

function sizeof_by_attribute(instance, attribute): integer {
val map_attrs = _get_map_types(attribute);

return Instance.instance_attribute @ {.value == instance, map_attrs.I} (@sum 1);
}

function is_empty(instance, attribute_name: Attribute.I): boolean {
return sizeof(instance, attribute_name) == 0;
}

function contains_key(instance, attribute_name: Attribute.I, idx: gtv): boolean {
val attribute = Attribute.get(attribute_name);
val map_attrs = _get_map_types(attribute);

return _find_instance_by_key_in_map(instance, idx, map_attrs) != null;
}

function keys(instance, attribute_name: Attribute.I): (type: Attribute.type, keys: gtv) {
val attribute = Attribute.get(attribute_name);
val map_attrs = _get_map_types(attribute);

return (type = map_attrs.K.type, keys = _get_map_values(instance, map_attrs.K, map_attrs.I)!!);
}

function values(instance, attribute_name: Attribute.I): (type: Attribute.type, values: gtv) {
val attribute = Attribute.get(attribute_name);
val map_attrs = _get_map_types(attribute);

return (type = map_attrs.V.type, values = _get_map_values(instance, map_attrs.V, map_attrs.I)!!);
}

function _get_map_types(attr: attribute): (K: attribute, V: attribute, I: attribute) {
val e = Interface.dclass @ {attr.dclass.name + attr.name + MAP};
val k_attr = attribute @ {e, attr.name + MAP_K};
val v_attr = attribute @ {e, attr.name + MAP_V};
val i_attr = attribute @ {e, attr.name + MAP_I};

return (K=k_attr, V=v_attr, I=i_attr);
}

function _get_map_value_by_instance(instance, attribute) {
when (attribute.type) {
Attribute.type.boolean -> return Boolean.boolean_attribute @? {attribute, instance} (.value)?.to_gtv();
Attribute.type.byte_array -> return ByteArray.byte_array_attribute @? {attribute, instance} (.value)?.to_gtv();
Attribute.type.decimal -> return Decimal.decimal_attribute @? {attribute, instance} (.value)?.to_gtv();
Attribute.type.instance -> return Instance.instance_attribute @? {attribute, instance} (.value)?.to_gtv();
Attribute.type.integer -> return Integer.integer_attribute @? {attribute, instance} (.value)?.to_gtv();
Attribute.type.text -> return Text.text_attribute @? {attribute, instance} (.value)?.to_gtv();
else -> {require(false, "Unimplemented path"); return null;}
}
}

function fetch_range_from(attribute, value: gtv, from: rowid) {
val map_attrs = _get_map_types(attribute);
when (map_attrs.K.type) {
Attribute.type.integer -> {
return (i: Instance.instance_attribute, a: Integer.integer_attribute) @* {
a.attribute == map_attrs.K,
a.value == integer.from_gtv(value),
i.attribute == map_attrs.I,
i.instance == a.instance,
i.value.rowid > from
} (i.value) limit 100;
}
Attribute.type.text -> {
return (i: Instance.instance_attribute, a: Text.text_attribute) @* {
a.attribute == map_attrs.K,
a.value == text.from_gtv(value),
i.attribute == map_attrs.I,
i.instance == a.instance,
i.value.rowid > from
} (i.value) limit 100;
}
else -> {require(false, "Unimplemented path"); return list<instance>();}
}
}

function _find_instance_by_key_in_map(instance, key_val: gtv, map_attrs: (K: attribute, V: attribute, I: attribute)): Instance.instance_attribute? {
when (map_attrs.K.type) {
Attribute.type.integer -> return (i: Instance.instance_attribute, a: Integer.integer_attribute) @? {
i.value == instance,
i.instance == a.instance,
i.attribute == map_attrs.I,
a.attribute == map_attrs.K,
a.value == integer.from_gtv(key_val)
} (i);
Attribute.type.text -> return (i: Instance.instance_attribute, a: Text.text_attribute) @? {
i.value == instance,
i.instance == a.instance,
i.attribute == map_attrs.I,
a.attribute == map_attrs.K,
a.value == text.from_gtv(key_val)
} (i);
else -> {require(false, "Unimplemented path"); return null;};
}
}

function _find_instance_by_value_in_map(_instance: instance, value: gtv, map_attrs: (K: attribute, V: attribute, I: attribute)): Instance.instance_attribute? {
when (map_attrs.V.type) {
Attribute.type.boolean -> return (i: Instance.instance_attribute, a: Boolean.boolean_attribute) @? {
i.value == _instance,
i.instance == a.instance,
i.attribute == map_attrs.I,
a.attribute == map_attrs.V,
a.value == boolean.from_gtv(value)
} (i);
Attribute.type.byte_array -> return (i: Instance.instance_attribute, a: ByteArray.byte_array_attribute) @? {
i.value == _instance,
i.instance == a.instance,
i.attribute == map_attrs.I,
a.attribute == map_attrs.V,
a.value == byte_array.from_gtv(value)
} (i);
Attribute.type.decimal -> return (i: Instance.instance_attribute, a: Decimal.decimal_attribute) @? {
i.value == _instance,
i.instance == a.instance,
i.attribute == map_attrs.I,
a.attribute == map_attrs.V,
a.value == decimal.from_gtv(value)
} (i);
Attribute.type.instance -> return (i: Instance.instance_attribute, a: Instance.instance_attribute) @? {
i.value == _instance,
i.instance == a.instance,
i.attribute == map_attrs.I,
a.attribute == map_attrs.V,
a.value == instance.from_gtv(value)
} (i);
Attribute.type.integer -> return (i: Instance.instance_attribute, a: Integer.integer_attribute) @? {
i.value == _instance,
i.instance == a.instance,
i.attribute == map_attrs.I,
a.attribute == map_attrs.V,
a.value == integer.from_gtv(value)
} (i);
Attribute.type.text -> return (i: Instance.instance_attribute, a: Text.text_attribute) @? {
i.value == _instance,
i.instance == a.instance,
i.attribute == map_attrs.I,
a.attribute == map_attrs.V,
a.value == text.from_gtv(value)
} (i);
else -> {require(false, "Unimplemented path"); return null;};
}
}

function _get_map_values(instance, attribute, I: attribute): gtv? {
when (attribute.type) {
Attribute.type.boolean -> return set((i: Instance.instance_attribute, a: Boolean.boolean_attribute) @* {
i.value == instance,
i.instance == a.instance,
i.attribute == I,
a.attribute == attribute
} (a.value)).to_gtv();
Attribute.type.byte_array -> return set((i: Instance.instance_attribute, a: ByteArray.byte_array_attribute) @* {
i.value == instance,
i.instance == a.instance,
i.attribute == I,
a.attribute == attribute
} (a.value)).to_gtv();
Attribute.type.decimal -> return set((i: Instance.instance_attribute, a: Decimal.decimal_attribute) @* {
i.value == instance,
i.instance == a.instance,
i.attribute == I,
a.attribute == attribute
} (a.value)).to_gtv();
Attribute.type.instance -> return set((i: Instance.instance_attribute, a: Instance.instance_attribute) @* {
i.value == instance,
i.instance == a.instance,
i.attribute == I,
a.attribute == attribute
} (a.value)).to_gtv();
Attribute.type.integer -> return set((i: Instance.instance_attribute, a: Integer.integer_attribute) @* {
i.value == instance,
i.instance == a.instance,
i.attribute == I,
a.attribute == attribute
} (a.value)).to_gtv();
Attribute.type.text -> return set((i: Instance.instance_attribute, a: Text.text_attribute) @* {
i.value == instance,
i.instance == a.instance,
i.attribute == I,
a.attribute == attribute
} (a.value)).to_gtv();
else -> {require(false, "Unimplemented path"); return null;}
}
}
}

namespace Map.Unsafe {
function add_elements (instance, attribute_name: Attribute.I, elements: gtv) {
val attribute = Attribute.get(attribute_name);
add_elements_by_attribute(instance, attribute, elements);
}

function add_elements_by_attribute (instance, attribute, elements: gtv) {
util.ensure_type(Attribute.type.addressable_container, attribute.type);

create map_attribute ( instance, attribute );
_create_map_attribute(instance, attribute, elements);
}

function update_elements (instance, attribute_name: Attribute.I, elements: gtv) {
val attribute = Attribute.get(attribute_name);
update_elements_by_attribute(instance, attribute, elements);
}

function update_elements_by_attribute (instance, attribute, elements: gtv) {
val m = map<gtv,gtv>.from_gtv(elements);

clear_by_attribute(instance, attribute);
put_all_by_attribute(instance, attribute, m);
}

function set_elements(instance, attribute_name: Attribute.I, elements: gtv) {
val attribute = Attribute.get(attribute_name);
set_elements_by_attribute(instance, attribute, elements);
}

function set_elements_by_attribute(instance, attribute, elements: gtv) {
var attr = map_attribute @? {instance, attribute};
if(attr == null) {
add_elements_by_attribute(instance, attribute, elements );
} else {
update_elements_by_attribute(instance, attribute, elements );
}
}

function remove_elements(instance, attribute_name: Attribute.I): gtv {
val attribute = Attribute.get(attribute_name);
return remove_elements_by_attribute(instance, attribute);
}

function remove_elements_by_attribute(instance, attribute): gtv {
val m = unpack_by_attribute(instance, attribute);

clear_by_attribute(instance, attribute);
delete map_attribute @ {instance, attribute};

return m!!.to_gtv();
}

function put(instance, attribute_name: Attribute.I, element: gtv) {
val attribute = Attribute.get(attribute_name);
put_by_attribute(instance, attribute, element);
}

function put_by_attribute(instance, attribute, element: gtv) {
val map_attrs = _get_map_types(attribute);
val e = list<gtv>.from_gtv(element);
_create_map_element(instance, attribute, (e[0], e[1]), map_attrs);
}

function put_all(instance, attribute_name: Attribute.I, elements: map<gtv, gtv>) {
val attribute = Attribute.get(attribute_name);
put_all_by_attribute(instance, attribute, elements);
}

function put_all_by_attribute(instance, attribute, elements: map<gtv, gtv>) {
val map_attrs = _get_map_types(attribute);
_create_map_elements(instance, attribute, elements, map_attrs);
}

function clear(instance, attribute_name: Attribute.I) {
val attribute = Attribute.get(attribute_name);
clear_by_attribute(instance, attribute);
}

function clear_by_attribute(instance, attribute) {
val map_attrs = _get_map_types(attribute);

val instances = Instance.instance_attribute @* {.value == instance, map_attrs.I};
for (i in instances) {
_remove_map_value(i.instance, map_attrs.K);
_remove_map_value(i.instance, map_attrs.V);
}

delete instances;
}

function remove(instance, attribute_name: Attribute.I, idx: gtv) {
val attribute = Attribute.get(attribute_name);
remove_by_attribute(instance, attribute, idx);
}

function remove_by_attribute(instance, attribute, idx: gtv) {
val map_attrs = _get_map_types(attribute);
_map_remove(instance, map_attrs.K, map_attrs.I, map_attrs.V, idx);
}

function _create_map_attribute (instance, attribute, elements: gtv?) {
if (elements??) {
val map_attrs = _get_map_types(attribute);
_create_map_elements(instance, attribute, map<gtv,gtv>.from_gtv(elements), map_attrs);
}
}

function _create_map_elements(instance, attribute, elements: map<gtv, gtv>, map_attrs: (K: attribute, V: attribute, I: attribute)) {
for (element in elements) {
_create_map_element(instance, attribute, element, map_attrs);
}
}

function _create_map_element(instance, attribute, element: (gtv, gtv), map_attrs: (K: attribute, V: attribute, I: attribute)) {
var element_instance = _find_instance_by_key_in_map(instance, element[0], map_attrs)?.instance;
if (element_instance == null) {
element_instance = create instance();
Instance.Unsafe.add_value_by_attribute(element_instance, map_attrs.I, instance);

when (map_attrs.K.type) {
Attribute.type.integer -> Integer.Unsafe.add_value_by_attribute(element_instance, map_attrs.K, integer.from_gtv(element[0]));
Attribute.type.text -> Text.Unsafe.add_value_by_attribute(element_instance, map_attrs.K, text.from_gtv(element[0]));
else -> require(false, "Unimplemented path");
}
_create_map_value(element_instance, map_attrs.V, element[1]);
} else {
_update_map_value(element_instance, map_attrs.V, element[1]);
}
}

function _create_map_value(i: instance, v_attr: attribute, value: gtv) {
when (v_attr.type) {
Attribute.type.boolean -> Boolean.Unsafe.add_value_by_attribute(i, v_attr, boolean.from_gtv(value));
Attribute.type.byte_array -> ByteArray.Unsafe.add_value_by_attribute(i, v_attr, byte_array.from_gtv(value));
Attribute.type.decimal -> Decimal.Unsafe.add_value_by_attribute(i, v_attr, decimal.from_gtv(value));
Attribute.type.instance -> Instance.Unsafe.add_value_by_attribute(i, v_attr, instance.from_gtv(value));
Attribute.type.integer -> Integer.Unsafe.add_value_by_attribute(i, v_attr, integer.from_gtv(value));
Attribute.type.text -> Text.Unsafe.add_value_by_attribute(i, v_attr, text.from_gtv(value));
else -> require(false, "Unimplemented path");
}
}

function _update_map_value(i: instance, v_attr: attribute, value: gtv) {
when (v_attr.type) {
Attribute.type.boolean -> Boolean.Unsafe.update_value_by_attribute(i, v_attr, boolean.from_gtv(value));
Attribute.type.byte_array -> ByteArray.Unsafe.update_value_by_attribute(i, v_attr, byte_array.from_gtv(value));
Attribute.type.decimal -> Decimal.Unsafe.update_value_by_attribute(i, v_attr, decimal.from_gtv(value));
Attribute.type.instance -> Instance.Unsafe.update_value_by_attribute(i, v_attr, instance.from_gtv(value));
Attribute.type.integer -> Integer.Unsafe.update_value_by_attribute(i, v_attr, integer.from_gtv(value));
Attribute.type.text -> Text.Unsafe.update_value_by_attribute(i, v_attr, text.from_gtv(value));
else -> require(false, "Unimplemented path");
}
}

function _map_remove(instance, k_attr: attribute, i_attr: attribute, v_attr: attribute, value: gtv) {
when (k_attr.type) {
Attribute.type.integer -> {
val (i, k) = (i: Instance.instance_attribute, a: Integer.integer_attribute) @ {
i.value == instance,
i.instance == a.instance,
i.attribute == i_attr,
a.attribute == k_attr,
a.value == integer.from_gtv(value)
} (i, a);

delete k;
_remove_map_value(i.instance, v_attr);
delete i;
}
Attribute.type.text -> {
val (i, k) = (i: Instance.instance_attribute, a: Text.text_attribute) @ {
i.value == instance,
i.instance == a.instance,
i.attribute == i_attr,
a.attribute == k_attr,
a.value == text.from_gtv(value)
} (i, a);

delete k;
_remove_map_value(i.instance, v_attr);
delete i;
}
else -> require(false, "Unimplemented path");
}
}

function _remove_map_value(instance, attribute) {
when (attribute.type) {
Attribute.type.boolean -> delete Boolean.boolean_attribute @ {.instance == instance, attribute};
Attribute.type.byte_array -> delete ByteArray.byte_array_attribute @ {.instance == instance, attribute};
Attribute.type.decimal -> delete Decimal.decimal_attribute @ {.instance == instance, attribute};
Attribute.type.instance -> delete Instance.instance_attribute @ {.instance == instance, attribute};
Attribute.type.integer -> delete Integer.integer_attribute @ {.instance == instance, attribute};
Attribute.type.text -> delete Text.text_attribute @ {.instance == instance, attribute};
}
}
}

namespace Map.Private {
function is_unique_value(instance, attribute, elements: gtv) {
require(false, "map is_unique_value: Not implemented");
return true;
}
}

@mount('dip')
                                    module;

                                    import ^.core.*;

/**
                                    * A set attribute contains its attributes in a child instance (elements).
                                    * The child instance has x amounts of attributes, which are stored as normal {type}_attribute.
                                    * Each {type}_attribute is linked with the same attribute as the set_attribute.
                                    * Elements can only be of simple types (i.e. not another container).
                                    */

                                    namespace SetInstanceDef {
                                    function T(instance_defs: list<attribute_type>) {
                                    return attribute_type(
                                    type = Attribute.type.unordered_container,
                                    value = instance_defs.to_gtv(),
                                    inner_type = Attribute.type.instance_def.to_gtv()
                                    );
                                    }
                                    }

                                    namespace Set {
                                    entity set_inner_type {
                                    key attribute;
                                    index attribute, Attribute.type;
                                    }

                                    entity set_attribute {
                                    index instance, attribute;
                                    }

                                    function T(inner_type: Attribute.type, value: gtv? = null): attribute_type {
                                    return attribute_type(inner_type = inner_type.to_gtv(), type = Attribute.type.unordered_container, value = value?.to_gtv());
                                    }

                                    function create_elements(instance, attribute_name: Attribute.I, elements: gtv) {
                                    val attribute = Attribute.get(attribute_name);
                                    util.ensure_not_implemented(instance, attribute);
                                    Meta.Engine.execute_value(instance, attribute, elements);
                                    Unsafe.add_elements_by_attribute(instance, attribute, elements);
                                    }

                                    function add_elements(instance, attribute_name: Attribute.I, elements: gtv) {
                                    val attribute = Attribute.get(attribute_name);
                                    util.ensure_attribute_can_be_added(instance, attribute);
                                    Meta.Engine.execute_value(instance, attribute, elements);
                                    Unsafe.add_elements_by_attribute(instance, attribute, elements);
                                    }

                                    function update_elements(instance, attribute_name: Attribute.I, elements: gtv) {
                                    val attribute = Attribute.get(attribute_name);
                                    Meta.Engine.execute_value(instance, attribute, elements);
                                    Unsafe.update_elements_by_attribute(instance, attribute, elements);
                                    }

                                    function set_elements(instance, attribute_name: Attribute.I, elements: gtv) {
                                    val attribute = Attribute.get(attribute_name);
                                    var attr = set_attribute @? {instance, attribute};
                                    if(attr == null) {
                                    add_elements(instance, attribute_name, elements);
                                    } else {
                                    update_elements(instance, attribute_name, elements);
                                    }
                                    }

                                    function remove_elements(instance, attribute_name: Attribute.I): gtv {
                                    val attribute = Attribute.get(attribute_name);
                                    util.ensure_optional(attribute);
                                    return Unsafe.remove_elements_by_attribute(instance, attribute);
                                    }

                                    function add_element(instance, attribute_name: Attribute.I, element: gtv) {
                                    val attribute = Attribute.get(attribute_name);
                                    Meta.Engine.execute_value(instance, attribute, element);
                                    Unsafe.add_by_attribute(instance, attribute, element);
                                    }

                                    function remove_element(instance, attribute_name: Attribute.I, element: gtv) {
                                    val attribute = Attribute.get(attribute_name);
                                    Meta.Engine.execute_value(instance, attribute, element);
                                    Unsafe.remove_by_attribute(instance, attribute, element);
                                    }

                                    /**
                                    * Get the set attribute from an instance and unpack it to a rell set.
                                    * @param instance instance The instance the attribute is mapped on
                                    * @param attribute attribute The set attribute to search for
                                    * @returns (type: a_type, values: gtv) A tuple containing the set type and the set parsed as set<T>(values).to_gtv()
                                    */
                                    function unpack(instance, attribute_name: Attribute.I): (type: Attribute.type, values: gtv)? {
                                    val attribute = Attribute.get(attribute_name);
                                    return unpack_by_attribute(instance, attribute);
                                    }

                                    function get_value_as_text(instance, attribute_name: Attribute.I): text {
                                    require(false, "set get_value_as_text: Not implementation");
                                    return "";
                                    }

                                    function unpack_by_attribute(instance, attribute): (type: Attribute.type, values: gtv)? {
                                    val set_type = set_inner_type @ {attribute}.type;

                                    var attr = set_attribute @? { instance, attribute };

                                    if(not attr??) {
                                    val prototypes = Prototype.get_all(instance);
                                    for (p in prototypes) {
                                    attr = set_attribute @? { p, attribute };
                                    if(attr??) {
                                    break;
                                    }
                                    }
                                    }

                                    if(not attr??) return null;

                                    var ret: gtv;
                                    when (set_type) {
                                    Attribute.type.byte_array -> ret = set(ByteArray.byte_array_attribute @* {attr.instance, attribute} (.value)).to_gtv();
                                    Attribute.type.decimal -> ret = set(Decimal.decimal_attribute @* {attr.instance, attribute} (.value)).to_gtv();
                                    Attribute.type.instance -> ret = set(Instance.instance_attribute @* {.instance == attr.instance, attribute} (.value)).to_gtv();
                                    Attribute.type.integer -> ret = set(Integer.integer_attribute @* {attr.instance, attribute} (.value)).to_gtv();
                                    Attribute.type.text -> ret = set(Text.text_attribute @* {attr.instance, attribute} (.value)).to_gtv();
                                    else -> {require(false, "Unimplemented path"); return (type = Attribute.type.instance, values = instance.to_gtv());}
                                    }

                                    return (type = set_type, values = ret);
                                    }

                                    /**
                                    * Like set.empty() in rell
                                    * @param instance instance The instance the attribute is mapped on
                                    * @param attribute attribute The set attribute to search for
                                    * @returns integer True if no elements in set, false if any
                                    */
                                    function is_empty(instance, attribute_name: Attribute.I): boolean {
                                    return size(instance, attribute_name) == 0;
                                    }


                                    function fetch_range_from(attribute, value: gtv, from: rowid) {
                                    val set_type = set_inner_type @ {attribute}.type;

                                    when (set_type) {
                                    Attribute.type.byte_array -> {
                                    return (s: set_attribute, v:ByteArray.byte_array_attribute) @* {
                                    v.attribute == attribute, v.value == byte_array.from_gtv(value), v.instance == s.instance,
                                    v.instance.rowid > from
                                    } (s.instance) limit 100;
                                    }
                                    Attribute.type.decimal -> {
                                    return (s: set_attribute, v:Decimal.decimal_attribute) @* {
                                    v.attribute == attribute, v.value == decimal.from_gtv(value), v.instance == s.instance,
                                    v.instance.rowid > from
                                    } (s.instance) limit 100;
                                    }
                                    Attribute.type.instance -> {
                                    return (s: set_attribute, v:Instance.instance_attribute) @* {
                                    v.attribute == attribute, v.value == instance.from_gtv(value), v.instance == s.instance,
                                    v.instance.rowid > from
                                    } (s.instance) limit 100;
                                    }
                                    Attribute.type.integer -> {
                                    return (s: set_attribute, v:Integer.integer_attribute) @* {
                                    v.attribute == attribute, v.value == integer.from_gtv(value), v.instance == s.instance,
                                    v.instance.rowid > from
                                    } (s.instance) limit 100;
                                    }
                                    Attribute.type.text -> {
                                    return (s: set_attribute, v:Text.text_attribute) @* {
                                    v.attribute == attribute, v.value == text.from_gtv(value), v.instance == s.instance,
                                    v.instance.rowid > from
                                    } (s.instance) limit 100;
                                    }
                                    else -> {require(false, "Unimplemented path"); return list<instance>();}
                                    }
                                    }

                                    /**
                                    * Like set.contains() in rell
                                    * @param instance instance The instance the attribute is mapped on
                                    * @param attribute attribute The set attribute to search for
                                    * @param value gtv The set.contains() parameter broken down to T(value).to_gtv()
                                    * @returns boolean True if element with key exists, false if not
                                    */
                                    function contains(root_instance: instance, attribute_name: Attribute.I, value: gtv): boolean {
                                    val attribute = Attribute.get(attribute_name);
                                    val set_type = set_inner_type @ {attribute}.type;
                                    val attr = set_attribute @ {.instance == root_instance, attribute};
                                    when (set_type) {
                                    Attribute.type.byte_array -> return ByteArray.byte_array_attribute @? {attr.instance, attribute, byte_array.from_gtv(value)} != null;
                                    Attribute.type.decimal -> return Decimal.decimal_attribute @? {attr.instance, attribute, decimal.from_gtv(value)} != null;
                                    Attribute.type.instance -> return Instance.instance_attribute @? {.instance == attr.instance, attribute, .value == instance.from_gtv(value)} != null;
                                    Attribute.type.integer -> return Integer.integer_attribute @? {attr.instance, attribute, integer.from_gtv(value)} != null;
                                    Attribute.type.text -> return Text.text_attribute @? {attr.instance, attribute, text.from_gtv(value)} != null;
                                    else -> {require(false, "Unimplemented path"); return false;}
                                    }
                                    }

                                    /**
                                    * Like set.contains_all() in rell
                                    * Note: Only set.contains_all(set<T>) exists, set.contains_all(list<T>) is not implemented.
                                    * @param instance instance The instance the attribute is mapped on
                                    * @param attribute attribute The set attribute to search for
                                    * @param values gtv The set.contains_all() parameter broken down to set<T>(values).to_gtv()
                                    * @returns boolean True if element with key exists, false if not
                                    */
                                    function contains_all(root_instance: instance, attribute_name: Attribute.I, values: gtv): boolean {
                                    val attribute = Attribute.get(attribute_name);
                                    val set_type = set_inner_type @ {attribute}.type;
                                    val attr = set_attribute @ {.instance == root_instance, attribute};
                                    when (set_type) {
                                    Attribute.type.byte_array -> {val vals = set<byte_array>.from_gtv(values); return ByteArray.byte_array_attribute @ {attr.instance, attribute, .value in vals} (@sum 1) == vals.size();}
                                    Attribute.type.decimal -> {val vals = set<decimal>.from_gtv(values); return Decimal.decimal_attribute @ {attr.instance, attribute, .value in vals} (@sum 1) == vals.size();}
                                    Attribute.type.instance -> {val vals = set<instance>.from_gtv(values); return Instance.instance_attribute @ {.instance == attr.instance, attribute, .value in vals} (@sum 1) == vals.size();}
                                    Attribute.type.integer -> {val vals = set<integer>.from_gtv(values); return Integer.integer_attribute @ {attr.instance, attribute, .value in vals} (@sum 1) == vals.size();}
                                    Attribute.type.text -> {val vals = set<text>.from_gtv(values); return Text.text_attribute @ {attr.instance, attribute, .value in vals} (@sum 1) == vals.size();}
                                    else -> {require(false, "Unimplemented path"); return false;}
                                    }
                                    }

                                    /**
                                    * Like set.size() in rell
                                    * @param instance instance The instance the attribute is mapped on
                                    * @param attribute attribute The set attribute to search for
                                    * @returns integer The amount of elements in the set
                                    */
                                    function size(root_instance: instance, attribute_name: Attribute.I): integer {
                                    val attribute = Attribute.get(attribute_name);
                                    val set_type = set_inner_type @ {attribute}.type;
                                    val attr = set_attribute @ {.instance == root_instance, attribute};
                                    when (set_type) {
                                    Attribute.type.byte_array -> return ByteArray.byte_array_attribute @ {attr.instance, attribute} (@sum 1);
                                    Attribute.type.decimal -> return Decimal.decimal_attribute @ {attr.instance, attribute} (@sum 1);
                                    Attribute.type.instance -> return Instance.instance_attribute @ {.instance == attr.instance, attribute} (@sum 1);
                                    Attribute.type.integer -> return Integer.integer_attribute @ {attr.instance, attribute} (@sum 1);
                                    Attribute.type.text -> return Text.text_attribute @ {attr.instance, attribute} (@sum 1);
                                    else -> {require(false, "Unimplemented path"); return 0;}
                                    }
                                    }
                                    }

                                    namespace Set.Unsafe {

                                    /**
                                    * Set attribute constructor. Can optionally be initialized with values, otherwise empty.
                                    * Note: Only set<T>(set<T>) exists, set<T>(list<T>) is not implemented.
                                    * @param instance instance The instance the attribute should be mapped with
                                    * @param attribute attribute The set attribute to map the instance to
                                    * @param values gtv? The set<T>() parameter broken down to set<T>(values).to_gtv()
                                    */
                                    function add_elements (instance, attribute_name: Attribute.I, values: gtv) {
                                    val attribute = Attribute.get(attribute_name);
                                    add_elements_by_attribute(instance, attribute, values);
                                    }

                                    function add_elements_by_attribute (instance, attribute, values: gtv) {
                                    util.ensure_type(Attribute.type.unordered_container, attribute.type);
                                    _create_set_elements(instance, attribute, values);
                                    create set_attribute ( instance, attribute );
                                    }

                                    function update_elements (instance, attribute_name: Attribute.I, elements: gtv) {
                                    val attribute = Attribute.get(attribute_name);
                                    update_elements_by_attribute(instance, attribute, elements);
                                    }

                                    function update_elements_by_attribute (instance, attribute, elements: gtv) {
                                    clear_by_attribute(instance, attribute);
                                    _create_set_elements(instance, attribute, elements);
                                    }

                                    function set_elements(instance, attribute_name: Attribute.I, elements: gtv) {
                                    val attribute = Attribute.get(attribute_name);
                                    set_elements_by_attribute(instance, attribute, elements);
                                    }

                                    function set_elements_by_attribute(instance, attribute, elements: gtv) {
                                    var attr = set_attribute @? {instance, attribute};
                                    if(attr == null) {
                                    add_elements_by_attribute(instance, attribute, elements );
                                    } else {
                                    update_elements_by_attribute(instance, attribute, elements );
                                    }
                                    }

                                    function remove_elements(instance, attribute_name: Attribute.I): gtv {
                                    val attribute = Attribute.get(attribute_name);
                                    return remove_elements_by_attribute(instance, attribute);
                                    }

                                    function remove_elements_by_attribute(instance, attribute): gtv {
                                    val s = unpack_by_attribute(instance, attribute);
                                    clear_by_attribute(instance, attribute);
                                    delete set_attribute @ {instance, attribute};

                                    return s!!.to_gtv();
                                    }


                                    /**
                                    * Like set.add() in rell
                                    * @param instance instance The instance the attribute is mapped on
                                    * @param attribute attribute The set attribute to search for
                                    * @param value gtv The set.add() parameter broken down to T(value).to_gtv()
                                    */
                                    function add (instance, attribute_name: Attribute.I, value: gtv): boolean {
                                    val attribute = Attribute.get(attribute_name);
                                    return add_by_attribute(instance, attribute, value);
                                    }

                                    function add_by_attribute(instance, attribute, value: gtv): boolean {
                                    val set_type = set_inner_type @ {attribute}.type;
                                    val attr = set_attribute @ {instance, attribute};
                                    return _create_set_element(attr.instance, attribute, set_type, value);
                                    }

                                    /**
                                    * Like set.add_all() in rell
                                    * Note: This function only implements set.add_all(set()), not set.add_all(list())
                                    * @param instance instance The instance the attribute is mapped on
                                    * @param attribute attribute The set attribute to search for
                                    * @param values gtv The set.add_all() parameter broken down to set<T>(values).to_gtv()
                                    */
                                    function add_all (instance, attribute_name: Attribute.I, values: gtv) {
                                    val attribute = Attribute.get(attribute_name);
                                    add_all_by_attribute(instance, attribute, values);
                                    }

                                    function add_all_by_attribute (instance, attribute, values: gtv) {
                                    val attr = set_attribute @ {instance, attribute};
                                    _create_set_elements(attr.instance, attribute, values);
                                    }


                                    /**
                                    * Like set.remove() in rell
                                    * @param instance instance The instance the attribute is mapped on
                                    * @param attribute attribute The set attribute to search for
                                    * @param value gtv The set.remove() parameter broken down to T(value).to_gtv()
                                    */
                                    function remove(root_instance: instance, attribute_name: Attribute.I, value: gtv) {
                                    val attribute = Attribute.get(attribute_name);
                                    remove_by_attribute(root_instance, attribute, value);
                                    }

                                    function remove_by_attribute(root_instance: instance, attribute, value: gtv) {
                                    val set_type = set_inner_type @ {attribute}.type;
                                    val attr = set_attribute @ {.instance == root_instance, attribute};
                                    when (set_type) {
                                    Attribute.type.byte_array -> delete ByteArray.byte_array_attribute @? {attr.instance, attribute, .value == byte_array.from_gtv(value)};
                                    Attribute.type.decimal -> delete Decimal.decimal_attribute @? {attr.instance, attribute, .value == decimal.from_gtv(value)};
                                    Attribute.type.instance -> delete Instance.instance_attribute @? {.instance == attr.instance, attribute, .value == instance.from_gtv(value)};
                                    Attribute.type.integer -> delete Integer.integer_attribute @? {attr.instance, attribute, .value == integer.from_gtv(value)};
                                    Attribute.type.text -> delete Text.text_attribute @? {attr.instance, attribute, .value == text.from_gtv(value)};
                                    }
                                    }

                                    /**
                                    * Like set.remove_all() in rell
                                    * Note: Only set.remove_all(set<T>) exists, set.remove_all(list<T>) is not implemented.
                                    * @param instance instance The instance the attribute is mapped on
                                    * @param attribute attribute The set attribute to search for
                                    * @param values gtv The set.remove_all() parameter broken down to set<T>(values).to_gtv()
                                    */
                                    function remove_all(root_instance: instance, attribute_name: Attribute.I, values: gtv) {
                                    val attribute = Attribute.get(attribute_name);
                                    remove_all_by_attribute(root_instance, attribute, values);
                                    }

                                    function remove_all_by_attribute(root_instance: instance, attribute, values: gtv) {
                                    val set_type = set_inner_type @ {attribute}.type;
                                    val attr = set_attribute @ {.instance == root_instance, attribute};
                                    when (set_type) {
                                    Attribute.type.byte_array -> {val vals = set<byte_array>.from_gtv(values); delete ByteArray.byte_array_attribute @* {attr.instance, attribute, .value in vals};}
                                    Attribute.type.decimal -> {val vals = set<decimal>.from_gtv(values); delete Decimal.decimal_attribute @* {attr.instance, attribute, .value in vals};}
                                    Attribute.type.instance -> {val vals = set<instance>.from_gtv(values); delete Instance.instance_attribute @* {.instance == attr.instance, attribute, .value in vals};}
                                    Attribute.type.integer -> {val vals = set<integer>.from_gtv(values); delete Integer.integer_attribute @* {attr.instance, attribute, .value in vals};}
                                    Attribute.type.text -> {val vals = set<text>.from_gtv(values); delete Text.text_attribute @* {attr.instance, attribute, .value in vals};}
                                    }
                                    }

                                    /**
                                    * Like set.clear() in rell
                                    * @param instance instance The instance the attribute is mapped on
                                    * @param attribute attribute The set attribute to search for
                                    */
                                    function clear(root_instance: instance, attribute_name: Attribute.I) {
                                    val attribute = Attribute.get(attribute_name);
                                    clear_by_attribute(root_instance, attribute);
                                    }

                                    function clear_by_attribute(root_instance: instance, attribute) {
                                    val set_type = set_inner_type @ {attribute}.type;
                                    val attr = set_attribute @ {.instance == root_instance, attribute};
                                    when (set_type) {
                                    Attribute.type.byte_array -> delete ByteArray.byte_array_attribute @* {attr.instance, attribute};
                                    Attribute.type.decimal -> delete Decimal.decimal_attribute @* {attr.instance, attribute};
                                    Attribute.type.instance -> delete Instance.instance_attribute @* {.instance == attr.instance, attribute};
                                    Attribute.type.integer -> delete Integer.integer_attribute @* {attr.instance, attribute};
                                    Attribute.type.text -> delete Text.text_attribute @* {attr.instance, attribute};
                                    }
                                    }



                                    function _create_set_elements(root_element: instance, attribute, values: gtv) {
                                    val set_type = set_inner_type @ {attribute}.type;
                                    for (value in util.gtv_to_set_of_gtv(values, set_type)) {
                                    _create_set_element(root_element, attribute, set_type, value);
                                    }
                                    }

                                    function _create_set_element(root_element: instance, attribute, type: Attribute.type, gtv_value: gtv): boolean {
                                    when (type) {
                                    Attribute.type.byte_array -> {
                                    val value = byte_array.from_gtv(gtv_value);
                                    if (ByteArray.byte_array_attribute @? {root_element, attribute, .value == value} == null) {
                                    ByteArray.Unsafe.add_value_by_attribute(root_element, attribute, value);
                                    return true;
                                    }
                                    return false;
                                    }
                                    Attribute.type.decimal -> {
                                    val value = decimal.from_gtv(gtv_value);
                                    if (Decimal.decimal_attribute @? {root_element, attribute, .value == value} == null) {
                                    Decimal.Unsafe.add_value_by_attribute(root_element, attribute, value);
                                    return true;
                                    }
                                    return false;
                                    }
                                    Attribute.type.instance -> {
                                    val value = instance.from_gtv(gtv_value);
                                    if (Instance.instance_attribute @? {.instance == root_element, attribute, .value == value} == null) {
                                    Instance.Unsafe.add_value_by_attribute(root_element, attribute, value);
                                    return true;
                                    }
                                    return false;
                                    }
                                    Attribute.type.integer -> {
                                    val value = integer.from_gtv(gtv_value);
                                    if (Integer.integer_attribute @? {root_element, attribute, .value == value} == null) {
                                    Integer.Unsafe.add_value_by_attribute(root_element, attribute, value);
                                    return true;
                                    }
                                    return false;
                                    }
                                    Attribute.type.text -> {
                                    val value = text.from_gtv(gtv_value);
                                    if (Text.text_attribute @? {root_element, attribute, .value == value} == null) {
                                    Text.Unsafe.add_value_by_attribute(root_element, attribute, value);
                                    return true;
                                    }
                                    return false;
                                    }
                                    else -> {require(false, "Unimplemented path"); return false;}
                                    }
                                    }
                                    }

                                    namespace Set.Private {
                                    function is_unique_value(instance, attribute, elements: gtv) {
                                    require(false, "set is_unique_value: Not implemented");
                                    return true;
                                    }
                                    }

namespace Text {
                                    entity text_attribute {
                                    index instance, attribute, value;
                                    index attribute, value;
                                    mutable value: text;
                                    }

                                    function T(value: text? = null): attribute_type {
                                    return attribute_type(type = Attribute.type.text, value = value?.to_gtv());
                                    }

                                    function create_value(instance, attribute_name: Attribute.I, value: text) {
                                    val attribute = Attribute.get(attribute_name);
                                    util.ensure_not_implemented(instance, attribute);
                                    Meta.Engine.execute_value(instance, attribute, value.to_gtv());
                                    Unsafe.add_value_by_attribute(instance, attribute, value);
                                    }

                                    function add_value(instance, attribute_name: Attribute.I, value: text) {
                                    val attribute = Attribute.get(attribute_name);
                                    util.ensure_attribute_can_be_added(instance, attribute);
                                    Meta.Engine.execute_value(instance, attribute, value.to_gtv());
                                    Unsafe.add_value_by_attribute(instance, attribute, value);
                                    }

                                    function update_value(instance, attribute_name: Attribute.I, value: text) {
                                    val attribute = Attribute.get(attribute_name);
                                    Meta.Engine.execute_value(instance, attribute, value.to_gtv());
                                    Unsafe.update_value_by_attribute(instance, attribute, value);
                                    }

                                    function set_value(instance, attribute_name: Attribute.I, value: text) {
                                    val attribute = Attribute.get(attribute_name);
                                    var attr = text_attribute @? {instance, attribute};
                                    if(attr == null) {
                                    add_value(instance, attribute_name, value);
                                    } else {
                                    update_value(instance, attribute_name, value);
                                    }
                                    }

                                    function remove_value(instance, attribute_name: Attribute.I): text {
                                    val attribute = Attribute.get(attribute_name);
                                    util.ensure_optional(attribute);
                                    return Unsafe.remove_value_by_attribute(instance, attribute);
                                    }

                                    function get_value(instance, attribute_name: Attribute.I): text? {
                                    val attribute = Attribute.get(attribute_name);
                                    var attr = text_attribute @? { instance, attribute };

                                    if(attr??) {
                                    return attr.value;
                                    } else {
                                    val prototypes = Prototype.get_all(instance);
                                    for (p in prototypes) {
                                    attr = text_attribute @? { p, attribute };
                                    if(attr??) {
                                    return attr.value;
                                    }
                                    }
                                    }
                                    return null;
                                    }

                                    function get_value_as_text(instance, attribute_name: Attribute.I): text {
                                    return "%s".format(get_value(instance, attribute_name));
                                    }

                                    function fetch_range_from(attribute, value: text, from: rowid, _limit: integer = 100) {
                                    return text_attribute @* {
                                    attribute, .value == value, .instance.rowid > from
                                    } (.instance) limit _limit;
                                    }

                                    function apply_filter(instances: list<instance>, filter: Filter.I_by_attribute, from: Filter.p_from):
                                    (results: list<instance>, from: Filter.p_from?) {
                                    val limit_count = 100;
                                    val attribute = filter.attribute;
                                    val value = text.from_gtv(filter.parameter);

                                    if(instances.empty()) {
                                    val attribute_name = Attribute.def_I(attribute.dclass.name, attribute.name);
                                    return Attribute.find_instances(attribute_name, value.to_gtv(), from, limit_count);
                                    };

                                    var res = list<instance>();

                                    val first = instances[0];
                                    val last = instances[instances.size() - 1];

                                    val in_prototype = (a: text_attribute, ip: instance_prototype) @* {
                                    a.attribute == attribute, a.value == value,
                                    ip.prototype == a.instance,
                                    ip.instance >= first, ip.instance <= last
                                    } (ip.instance) limit limit_count;

                                    res.add_all(in_prototype);

                                    val in_attribute = (a: text_attribute) @* {
                                    attribute,
                                    a.value == value,
                                    a.instance >= first, a.instance <= last
                                    } (a.instance) limit limit_count;

                                    res.add_all(in_attribute);

                                    val prior_instances = set(instances);
                                    res = res @* {prior_instances.contains($)};

                                    return (results = res, from = null);
                                    }
                                    }

                                    namespace Text.Unsafe {
                                    function add_value(instance, attribute_name: Attribute.I, value: text) {
                                    val attribute = Attribute.get(attribute_name);
                                    add_value_by_attribute(instance, attribute, value);
                                    }

                                    function add_value_by_attribute(instance, attribute, value: text) {
                                    util.ensure_type(Attribute.type.text, attribute.type);
                                    Hooks.before_add_value(instance, attribute, value);
                                    val text_attribute = create text_attribute ( instance, attribute, value );
                                    Hooks.after_add_value(text_attribute);
                                    }

                                    function update_value(instance, attribute_name: Attribute.I, value: text) {
                                    val attribute = Attribute.get(attribute_name);
                                    update_value_by_attribute(instance, attribute, value);
                                    }

                                    function update_value_by_attribute (instance, attribute, value: text) {
                                    util.ensure_type(Attribute.type.text, attribute.type);

                                    val text_attribute = text_attribute @ { instance, attribute };

                                    Hooks.before_update_value(text_attribute, value);
                                    if (text_attribute.value != value) {
                                    text_attribute.value = value;
                                    }
                                    Hooks.after_update_value(text_attribute);
                                    }

                                    function set_value(instance, attribute_name: Attribute.I, value: text) {
                                    val attribute = Attribute.get(attribute_name);
                                    set_value_by_attribute(instance, attribute, value);
                                    }

                                    function set_value_by_attribute(instance, attribute, value: text) {
                                    var attr = text_attribute @? {instance, attribute};
                                    Hooks.before_set_value(instance, attribute, attr, value);
                                    if(attr == null) {
                                    attr = create text_attribute ( instance, attribute, value );
                                    } else {
                                    attr.value = value;
                                    }
                                    Hooks.after_set_value(attr);
                                    }

                                    function remove_value(instance, attribute_name: Attribute.I): text {
                                    val attribute = Attribute.get(attribute_name);
                                    return remove_value_by_attribute(instance, attribute);
                                    }

                                    function remove_value_by_attribute(instance, attribute): text {
                                    val text_attribute = text_attribute @ {instance, attribute};
                                    val value = text_attribute.value;

                                    Hooks.before_remove_value(text_attribute);
                                    delete text_attribute;
                                    Hooks.after_remove_value(instance, attribute, value);

                                    return value;
                                    }
                                    }

                                    namespace Text.Hooks {
                                    @extendable
                                    function before_add_value(instance, attribute, value: text);

                                    @extendable
                                    function after_add_value(text_attribute);

                                    @extendable
                                    function before_remove_value(text_attribute);

                                    @extendable
                                    function after_remove_value(instance, attribute, value: text);

                                    @extendable
                                    function before_update_value(text_attribute, value: text);

                                    @extendable
                                    function after_update_value(text_attribute);

                                    @extendable
                                    function before_set_value(instance, attribute, text_attribute?, value: text);

                                    @extendable
                                    function after_set_value(text_attribute);
                                    }

                                    namespace Text.Private {
                                    function is_unique_value(instance, attribute, value: text) {
                                    val text_attribute = text_attribute @? { attribute, value } limit 1;
                                    return text_attribute == null or text_attribute.instance == instance;
                                    }
                                    }

entity instance {
                                    is_prototype: boolean = false;
                                    }

                                    // one entity might have more than one dclass
                                    entity instance_dclass {
                                    index Interface.dclass;
                                    key instance, dclass;
                                    direct: boolean;
                                    }

                                    entity attribute {
                                    key Interface.dclass, name;
                                    Attribute.type;
                                    }

                                    namespace Attribute {
                                    // TODO: id and instance_def don't represent real types,
                                    // make sure only valid types are assigned when creating attributes.
                                    enum type {
                                    boolean,
                                    byte_array,
                                    decimal,
                                    id,
                                    instance,
                                    integer,
                                    text,
                                    unordered_container,   // set
                                    ordered_container,	   // list
                                    addressable_container, // map
                                    file,
                                    instance_def
                                    }

                                    struct I {
                                    interface: name;
                                    name;
                                    }

                                    function def_I(interface: text, name) {
                                    return I(interface, name);
                                    }

                                    function get(I): attribute {
                                    return require(
                                    attribute @? { .dclass.name == I.interface, I.name },
                                    "Attribute '" + get_name(I) + "' not found"
                                    );
                                    }

                                    function get_all(Interface.dclass) = attribute @* { dclass };

                                    function get_all_in_dclasses(interfaces: list<Interface.dclass>) = attribute @* { .dclass in interfaces };

                                    function get_name(I) = I.interface + "." + I.name;

                                    function get_name_from_attribute(attribute) = attribute.dclass.name + "." + attribute.name;

                                    function get_meta(attribute_name: I, meta: list<Meta.meta>): map<name, gtv> {
                                    if (empty(meta)) return [:];

                                    val attribute = get(attribute_name);
                                    val categories = list<name>();
                                    val keys = list<name>();

                                    for (m in meta) {
                                    when (m.type) {
                                    Meta.type.category -> categories.add(m.name);
                                    Meta.type.tag -> keys.add(m.name);
                                    }
                                    }

                                    return map(
                                    AttributeMeta.attribute_meta @* {
                                    attribute,
                                    (.meta_key in keys or .category in categories)
                                    } (
                                    .meta_key, gtv.from_bytes(.meta_value)
                                    )
                                    );
                                    }
                                    }

                                    namespace Interface {
                                    entity dclass {
                                    key name;
                                    }

                                    entity dclass_dependency {
                                    key dclass, parent: dclass;
                                    direct: boolean;
                                    }

                                    function new_dependency(child: dclass, parents_in: list<dclass>) {
                                    val parents = list(parents_in);
                                    val gparents = dclass_dependency @* {.dclass in parents} .parent;
                                    parents.add_all(gparents);

                                    require(child not in parents, "Child inherits itself");
                                    require(parents.size() == set(parents).size(), "Duplicate inheritance violation");

                                    for (parent in parents) {
                                    create dclass_dependency(dclass = child, parent, parent in parents_in);
                                    }
                                    }

                                    function require_access(interface_name: text, account: ft3.acc.account): dclass {
                                    val dclass = Interface.get(interface_name);
                                    val owner_id = InterfaceMeta.get_owner(dclass);
                                    require(
                                    owner_id == null or owner_id == account.id,
                                    "Account " + account.id + " is not allowed to use interface "
                                    + dclass.name + "from " + owner_id
                                    );

                                    return dclass;
                                    }

                                    function require_accesses(interface_names: list<text>, account: ft3.acc.account): list<dclass> {
                                    val dclasses = list<Interface.dclass>();
                                    for(interface_name in interface_names) {
                                    val dclass = Interface.require_access(interface_name, account);
                                    dclasses.add(dclass);
                                    }

                                    return dclasses;
                                    }

                                    function is_open_or_owner(dclass, ft3.acc.account) {
                                    val owner_id = InterfaceMeta.get_owner(dclass);
                                    return owner_id == null or owner_id == account.id;
                                    }

                                    function is_a(instance, dclass): boolean {
                                    return get_all_in_instance(instance).contains(dclass);
                                    }

                                    function get(name) {
                                    val dclass = dclass @? { name };
                                    require(
                                    dclass,
                                    "Interface '" + name + "' not found"
                                    );

                                    return dclass;
                                    }

                                    function get_all(names: list<name>) = list(set(names) @* {} (get($)));

                                    function get_with_dependencies(dclass) {
                                    val interfaces = get_dependencies(dclass);
                                    interfaces.add(dclass);

                                    return interfaces;
                                    }

                                    function get_with_dependencies_by_name(name) {
                                    return get_with_dependencies(get(name));
                                    }

                                    function get_dependencies(dclass): list<dclass> {
                                    return dclass_dependency @* {.dclass == dclass}.parent;
                                    }

                                    function get_dependencies_by_name(name): list<dclass> {
                                    return get_dependencies(get(name));
                                    }

                                    function get_all_in_instance(instance): list<dclass> {
                                    return instance_dclass @* {instance} .dclass;
                                    }

                                    function get_all_in_prototype_chain(instance): list<dclass> {
                                    val interfaces = set<dclass>();
                                    val prototypes = Prototype.get_all(instance);
                                    prototypes.add(instance);

                                    for (p in prototypes) {
                                    interfaces.add_all(get_all_in_instance(p));
                                    }

                                    return list(interfaces);
                                    }
                                    }

import ^.util;

