                                    type.unordered_container -> Set.create_elements(i, attribute_name, value);
                                    type.addressable_container -> Map.create_elements(i, attribute_name, value);
                                    else -> require(false, "Unimplemented path");
                                    }

                                    return attribute;
                                    }

