import ^.core.*;
                                    import ^.util.*;

                                    struct attribute_def {
                                    attribute_type;
                                    meta: list<Meta.I>;
                                    }

                                    struct attribute_type {
                                    type: Attribute.type;
                                    value: gtv?;
                                    inner_type: gtv? = null;
                                    }

                                    namespace InterfaceFactory {
                                    function new(
                                    name,
                                    attribute_def_list: map<Attribute.I, attribute_def>,
                                    depends: list<Interface.dclass> = list(),
                                    meta: list<Meta.I> = list(),
                                    account: ft3.acc.account,
                                    is_open: boolean = false
                                    ) {
                                    validate_name(name);

                                    if(not is_open) {
                                    // is owner in meta list
                                    val has_owner = meta @? {.meta_key == InterfaceMeta.type.owner.name} ($) != null;
                                    // Add account as interface owner to meta data
                                    if(not has_owner)
                                    meta.add(0, Owner(account.id));
                                    }

                                    val dclass = create Interface.dclass (name);
                                    Interface.new_dependency(dclass, depends);

                                    for ((attribute_name, attribute_def) in attribute_def_list) {
                                    validate_name(attribute_name.name);
                                    val attribute_type = attribute_def.attribute_type;
                                    val attr = create attribute(dclass, attribute_name.name, attribute_type.type);

                                    when (attribute_type.type) {
                                    Attribute.type.ordered_container -> {
                                    val inner_type = Attribute.type.from_gtv(attribute_type.inner_type!!);
                                    List.create_type(attr, inner_type);
                                    }
                                    Attribute.type.unordered_container -> {
                                    val inner_type = Attribute.type.from_gtv(attribute_type.inner_type!!);
                                    util.ensure_simple_type(inner_type);
                                    create Set.set_inner_type(attr, inner_type);
                                    }
                                    Attribute.type.addressable_container -> {
                                    val inner_types = Map.types.from_gtv(attribute_type.inner_type!!);
                                    Map.create_type(attr, inner_types.K, inner_types.V);
                                    }
                                    }
                                    // Add attribute meta data
                                    for (m in attribute_def.meta) {
                                    AttributeMeta.add(attr, m);
                                    }

                                    // Add default value
                                    if(attribute_type.value??) {
                                    AttributeMeta.add(attr, Default(attribute_type.to_bytes()));
                                    }
                                    }

                                    // Add interface meta data
                                    for (m in meta) {
                                    InterfaceMeta.add(dclass, m.meta_key, m.meta_value);
                                    }
                                    }
                                    }

                                    namespace PrototypeFactory {
                                    function new(
                                    Interface.dclass,
                                    attribute_impl_list: map<Attribute.I, attribute_type>,
                                    name,
                                    prototype_name: text? = null
                                    ): instance {
                                    val instance = create instance (true);
                                    val interfaces = Interface.get_with_dependencies(dclass);

                                    create Prototype.prototype (name, instance);

                                    _create_instance_dclass(
                                    instance,
                                    interfaces,
                                    dclass
                                    );

                                    // Link prototype into prototype chain
                                    if (prototype_name??) {
                                    Prototype.link_instance_prototypes(
                                    instance,
                                    Prototype.get(prototype_name)
                                    );
                                    }

                                    _create_attribute_values(
                                    instance,
                                    interfaces,
                                    attribute_impl_list
                                    );

                                    return instance;
                                    }
                                    }

                                    namespace InstanceFactory {
                                    function new(
                                    Interface.dclass,
                                    attribute_impl_list: map<Attribute.I, attribute_type>,
                                    prototype_name: text? = null
                                    ): instance {
                                    val instance = create instance (false);
                                    val interfaces = Interface.get_with_dependencies(dclass);

                                    // Link instance into prototype chain
                                    if (prototype_name??) {
                                    var protoype = Prototype.get(prototype_name);
                                    val distinct_interfaces = Interface.get_all_in_prototype_chain(protoype);

                                    require(interfaces.contains_all(distinct_interfaces), "Prototype implements a not known interface");
                                    Prototype.link_instance_prototypes(instance, protoype);
                                    }

                                    val implemented_attributes =
                                    _create_attribute_values(
                                    instance,
                                    interfaces,
                                    attribute_impl_list
                                    );

                                    // Should we execute this after setting default values?
                                    // Perhaps computed value depends on an attribute that is initalized with default value
                                    _create_computed_attribute_values(instance, interfaces);

                                    _create_instance_dclass(
                                    instance,
                                    interfaces,
                                    dclass
                                    );

                                    // Check if all attributes are implemented or has default values
                                    val attributes = Attribute.get_all_in_dclasses(interfaces);
                                    attributes.remove_all(implemented_attributes);

                                    _initialize_with_default_values(instance, attributes);

                                    return instance;
                                    }
                                    }

                                    function _create_computed_attribute_values(instance, interfaces: list<Interface.dclass>) {
                                    // TODO: Extract to a function
                                    val attributes_meta = (
                                    a: attribute,
                                    am: AttributeMeta.attribute_meta
                                    ) @* {
                                    a.dclass in interfaces,
                                    am.attribute == a,
                                    am.category == AttributeMeta.category.computed_value.name
                                    } (a, am);

                                    for ((attribute, meta) in attributes_meta) {
                                    create_computed_attribute_value(instance, attribute, meta);
                                    }
                                    }

                                    function _initialize_with_default_values(instance, attributes: list<attribute>) {
                                    for (attr in attributes) {
                                    val is_implemented = util.is_implemented(instance, attr);


                                    if(not is_implemented) {
                                    val default_value = AttributeMeta.get_default_value(attr);

                                    if(default_value??) {
                                    val v = attribute_type.from_gtv(default_value);
                                    Attribute.create_value(instance,
                                    Attribute.I(interface = attr.dclass.name, name = attr.name),
                                    v.value!!
                                    );
                                    } else {
                                    require(AttributeMeta.is_attribute_optional(attr), "Attribute " + attr.name + " is not optional and has no default value");
                                    }
                                    }

                                    }
                                    }

                                    @extendable
                                    function create_computed_attribute_value(instance, attribute, meta: AttributeMeta.attribute_meta) {
                                    require(
                                    meta.category == AttributeMeta.category.computed_value.name,
                                    "Wrong meta category. Expected '%s', found '%s'"
                                    .format(AttributeMeta.category.computed_value.name, meta.category)
                                    );

                                    val meta_value = gtv.from_bytes(meta.meta_value);

                                    when (meta.meta_key) {
                                    AttributeMeta.type.composite_value.name ->
                                    _create_composite_value_attribute(instance, attribute, meta_value);
                                    }
                                    }

                                    function _create_attribute_values(
                                    instance,
                                    interfaces: list<Interface.dclass>,
                                    attribute_impl_list: map<Attribute.I, attribute_type>
                                    ): list<attribute> {
                                    val attributes = list<attribute>();
                                    for ((attribute_name, attribute_type) in attribute_impl_list) {
                                    val found = interfaces @? {.name == attribute_name.interface};
                                    require(found, "Attribute '" + Attribute.get_name(attribute_name) + "' not found in instance interfaces");

                                    val value: gtv;
                                    // Check if we need to create nested instances
                                    if (_is_instance_def_list(attribute_type) or _is_instance_def_set(attribute_type)) {
                                    val instance_defs = list<attribute_type>.from_gtv(attribute_type.value!!);
                                    value = instance_defs @* {} ( InstanceDef.Def.from_gtv($.value!!)) @* {} (
                                    InstanceFactory.new(
                                    Interface.get($.interface),
                                    $.attributes,
                                    $.prototype
                                    )
                                    ).to_gtv();
                                    } else if (_is_instance_def(attribute_type)) {
                                    val def = InstanceDef.Def.from_gtv(attribute_type.value!!);
                                    value = InstanceFactory.new(
                                    Interface.get(def.interface),
                                    def.attributes,
                                    def.prototype
                                    ).to_gtv();
                                    } else {
                                    value = attribute_type.value!!;
                                    }
                                    val attr = Attribute.create_value(instance, attribute_name, value);
                                    attributes.add(attr);
                                    }

                                    return attributes;
                                    }

                                    function _create_instance_dclass(
                                    instance,
                                    interfaces: list<Interface.dclass>,
                                    direct: Interface.dclass
                                    ) {
                                    for(interface in interfaces) {
                                    create instance_dclass(interface, instance, interface == direct);
                                    }
                                    }

                                    function _create_composite_value_attribute(instance, attribute, attributes: gtv) {
                                    val a = list<Attribute.I>.from_gtv(attributes);
                                    val value = Attribute.get_composite_value(instance, a)!!;
                                    Attribute.create_value(instance,
                                    Attribute.I(interface = attribute.dclass.name, name = attribute.name),
                                    value.to_gtv()
                                    );
                                    }

                                    // Used to define nested instances
                                    namespace InstanceDef {
                                    struct Def {
                                    interface: name;
                                    attributes: map<Attribute.I, attribute_type>;
                                    prototype: name? = null;
                                    }

                                    function T(
                                    interface: name,
                                    attributes: map<Attribute.I, attribute_type>,
                                    prototype: name? = null
                                    ) = attribute_type(
                                    type = Attribute.type.instance_def,
                                    value = Def(
                                    interface,
                                    attributes,
                                    prototype
                                    ).to_gtv()
                                    );
                                    }

                                    function _is_instance_def_list(attribute_type) =
                                    attribute_type.type == Attribute.type.ordered_container
                                    and
                                    attribute_type.inner_type!! == Attribute.type.instance_def.to_gtv();

                                    function _is_instance_def_set(attribute_type) =
                                    attribute_type.type == Attribute.type.unordered_container
                                    and
                                    attribute_type.inner_type!! == Attribute.type.instance_def.to_gtv();

                                    function _is_instance_def(attribute_type) =
                                    attribute_type.type == Attribute.type.instance_def;

                                    function Type(attribute_type, meta_list: list<Meta.I> = list()): attribute_def {
                                    return attribute_def(attribute_type, meta_list);
                                    }

namespace Filter {
enum type {
exact,
min,
max,
range,
contains,
contains_all,
starts_with
}

struct I {
attribute_name: Attribute.I;
parameter: gtv;
type = type.exact;
}

struct I_by_attribute {
attribute;
parameter: gtv;
type = type.exact;
}

// Pointing to a page with instance_prototype
struct p_from {
instance_rowid: rowid = util.r_zero();
prototype_rowid: rowid = util.r_zero();
}

function resolve(
instances: list<instance>,
filter: I_by_attribute,
from: p_from
): (results: list<instance>, from: p_from?) {
when(filter.attribute.type) {
Attribute.type.boolean -> return Boolean.apply_filter(instances, filter, from);
Attribute.type.byte_array -> return ByteArray.apply_filter(instances, filter, from);
Attribute.type.decimal -> return Decimal.apply_filter(instances, filter, from);
Attribute.type.instance -> return Instance.apply_filter(instances, filter, from);
Attribute.type.integer -> return Integer.apply_filter(instances, filter, from);
Attribute.type.text -> return Text.apply_filter(instances, filter, from);
else -> {
return (results=list<instance>(), from=null);
}
}
}

function find_instances(
filters: list<I>,
from: p_from,
page_size: integer
): (results: list<instance>, from: p_from) {
var results = list<instance>();
var cur_from = from;

val filter_mapped = list<I_by_attribute>();
for(filter in filters) {
val attr = Attribute.get(filter.attribute_name);
filter_mapped.add(
I_by_attribute(attr, filter.parameter, filter.type)
);
}

while (true) {
var instances = list<instance>();

for(filter in filter_mapped) {
val rf = resolve(instances, filter, cur_from);
instances = rf.results;

if(rf.from??) cur_from = rf.from!!;

if (instances.empty()) {
break;
}
}

results.add_all(instances);
if(results.size() >= page_size or cur_from.instance_rowid == util.r_zero()) break;
}

if(results.empty()) return (results = results, from = cur_from );

val min_size = min(page_size, results.size());

if(results.size() > page_size) {
val last_instance = results[min_size-1];
val first_filter = filter_mapped[0];
cur_from = get_prototype_from_instance(first_filter.attribute, last_instance);
}

return (results = results.sub(0, min_size), from = cur_from);
}

function get_prototype_from_instance(attribute, instance): p_from {
var prototype: instance? = null;

when(attribute.type) {
Attribute.type.boolean -> {
prototype = (ip: instance_prototype, a: Boolean.boolean_attribute) @? {
a.attribute == attribute,
ip.prototype == a.instance,
ip.instance == instance
} (ip.prototype);
}
Attribute.type.byte_array -> {
prototype = (ip: instance_prototype, a: ByteArray.byte_array_attribute) @? {
a.attribute == attribute,
ip.prototype == a.instance,
ip.instance == instance
} (ip.prototype);
}
Attribute.type.decimal -> {
prototype = (ip: instance_prototype, a: Decimal.decimal_attribute) @? {
a.attribute == attribute,
ip.prototype == a.instance,
ip.instance == instance
} (ip.prototype);
}
Attribute.type.instance -> {
prototype = (ip: instance_prototype, a: Instance.instance_attribute) @? {
a.attribute == attribute,
ip.prototype == a.instance,
ip.instance == instance
} (ip.prototype);
}
Attribute.type.integer -> {
prototype = (ip: instance_prototype, a: Integer.integer_attribute) @? {
a.attribute == attribute,
ip.prototype == a.instance,
ip.instance == instance
} (ip.prototype);
}
Attribute.type.text -> {
prototype = (ip: instance_prototype, a: Text.text_attribute) @? {
a.attribute == attribute,
ip.prototype == a.instance,
ip.instance == instance
} (ip.prototype);
}
}

if(prototype??) {
return p_from(instance_rowid = prototype.rowid, prototype_rowid = instance.rowid);
}

return p_from(instance_rowid = instance.rowid, prototype_rowid = util.r_zero());
}
}

namespace Mapper {
enum option {
remove_interface,
// TODO: add an option which handles case where removing interface leads
// to attribute name conflicts in resulting map

// Excludes attributes with null values from the resulting map
remove_null_values
}

/*
* Used to represent keys in resulting map. When `remove_interface` options is used, then
* prefix is ignored and only name is used as a map key. Otherwise resulting key has following
* format: `<prefix>.<name>`.
*/
struct key_name {
prefix: text? = null;
name;
}

// TODO: Improve logic for removing interface name from attribute name. Ideally all processing should be
// handled in a single place after all attributes are read from database, instead of having logic
// spread in multiple different places like it is now, i.e. in direct, to_list and to_map mappers.

/*
*  Maps instance entity to a map<name, gtv?> using provided mapping rules
*/

function map_instance(
instance,
mappers: list<(instance, map<name, gtv?>, list<option>) -> unit>,
options: list<option> = []
): map<name, gtv?> {
val instance_map = map<name, gtv?>();

for (mapper in mappers) {
mapper(instance, instance_map, options);
}

return instance_map;
}

/***************************************************************************************
*								 Mapping rules
***************************************************************************************/

/*
*	Reads instance attributes provided in the list
*/

function map_attributes(
attribute_names: list<Attribute.I>,
mapper: (map<name, gtv?>, map<key_name, gtv?>, list<option>) -> unit = direct(),
meta: list<Meta.meta>? = null
): (instance, map<name, gtv?>, list<option>) -> unit {
return _map_attributes(*, *, *, attribute_names, mapper, meta);
}

function _map_attributes(
instance,
instance_map: map<name, gtv?>,
options: list<option>,
attribute_names: list<Attribute.I>,
mapper: (map<name, gtv?>, map<key_name, gtv?>, list<option>) -> unit,
meta: list<Meta.meta>?
) {
val attributes = attribute_names
@* {} ((
key_name(prefix = $.interface, name=$.name),
decorate_with_meta_if_needed($, Attribute.get_value(instance, $), meta, options)
));

mapper(instance_map, map(attributes), options);
}

/*
*  Reads all instance attributes defined in provided interface list
*/

function map_attributes_of_interfaces(
interfaces: list<Interface.dclass>,
mapper: (map<name, gtv?>, map<key_name, gtv?>, list<option>) -> unit = direct(),
meta: list<Meta.meta>? = null
): (instance, map<name, gtv?>, list<option>) -> unit {
return _map_attributes_of_interfaces(*, *, *, interfaces, mapper, meta);
}

function _map_attributes_of_interfaces(
instance,
instance_map: map<name, gtv?>,
options: list<option>,
interfaces: list<Interface.dclass>,
mapper: (map<name, gtv?>, map<key_name, gtv?>, list<option>) -> unit,
meta: list<Meta.meta>?
) {
val attributes = attribute
@* { .dclass in interfaces }
@* {} ((
key_name(prefix=$.dclass.name, name=$.name),
decorate_with_meta_if_needed(
_get_attribute_name_from_attribute($),
Attribute.get_value(instance, _get_attribute_name_from_attribute($)),
meta,
options
)
));

mapper(instance_map, map(attributes), options);
}

/*
*  Reads all instance attributes that implement one of the interfaces provided in the list.
*  It is also possible to specify mapping rules for children instances.
*/

function map_attributes_implementing_interface(
interfaces: list<Interface.dclass>,
children_mappers: list<(instance, map<name, gtv?>, list<option>) -> unit> = [map_all_attributes()],
mapper: (map<name, gtv?>, map<key_name, gtv?>, list<option>) -> unit = direct(),
meta: list<Meta.meta>? = null
): (instance, map<name, gtv?>, list<option>) -> unit {
return _map_attributes_implementing_interface(*, *, *, children_mappers, interfaces, mapper, meta);
}

function _map_attributes_implementing_interface(
instance,
instance_map: map<name, gtv?>,
options: list<option>,
children_mappers: list<(instance, map<name, gtv?>, list<option>) -> unit>,
interfaces: list<Interface.dclass>,
mapper: (map<name, gtv?>, map<key_name, gtv?>, list<option>) -> unit,
meta: list<Meta.meta>?
) {
val mapped_instances = (
ia: Instance.instance_attribute,
id: instance_dclass
) @* {
ia.instance == instance,
id.dclass in interfaces,
id.instance == ia.value
} ((
key_name(prefix=ia.attribute.dclass.name, name=ia.attribute.name),
decorate_with_meta_if_needed(
_get_attribute_name_from_attribute(ia.attribute),
map_instance(ia.value, children_mappers, options).to_gtv(),
meta,
options
)
));

mapper(instance_map, map<key_name, gtv?>(mapped_instances), options);
}

/*
*  Reads all instance attributes
*/

function map_all_attributes(
mapper: (map<name, gtv?>, map<key_name, gtv?>, list<option>) -> unit = direct(),
meta: list<Meta.meta>? = null
): (instance, map<name, gtv?>, list<option>) -> unit {
return _map_all_attributes(*, *, *, mapper, meta);
}

function _map_all_attributes(
instance,
instance_map: map<name, gtv?>,
options: list<option>,
mapper: (map<name, gtv?>, map<key_name, gtv?>, list<option>) -> unit,
meta: list<Meta.meta>?
) {
var interfaces = Interface.get_all_in_instance(instance);

val attributes = attribute
@* { .dclass in interfaces } (attribute)
@* {} ((
key_name(prefix=$.dclass.name, name=$.name),
decorate_with_meta_if_needed(
_get_attribute_name_from_attribute($),
get_value(instance, _get_attribute_name_from_attribute($), options),
meta,
options
)
));

mapper(instance_map, map(attributes), options);
}

/*
*  Manually adds attributes to instance map.
*  Used to add attributes which are already fetched to avoid unnecessary db access.
*/

function add_attributes(
attributes: map<name, gtv?>,
mapper: (map<name, gtv?>, map<key_name, gtv?>, list<option>) -> unit = direct()
): (instance, map<name, gtv?>, list<option>) -> unit {
return _add_attributes(*, *, *, attributes, mapper);
}

function _add_attributes(
instance,
instance_map: map<name, gtv?>,
options: list<option>,
attributes: map<name, gtv?>,
mapper: (map<name, gtv?>, map<key_name, gtv?>, list<option>) -> unit
) {
val result = map<key_name, gtv?>();
for ((k, v) in attributes) {
result[key_name(prefix=null, name=k)] = v;
}
mapper(instance_map, result, options);
}

/*
*  Reads all instance attributes by meta tag
*/
function map_attributes_by_meta_tag(
meta_tag: text,
mapper: (map<name, gtv?>, map<Mapper.key_name, gtv?>, list<Mapper.option>) -> unit = Mapper.direct(),
meta: list<Meta.meta>? = null
): (instance, map<name, gtv?>, list<Mapper.option>) -> unit {
return _map_attributes_by_meta_tag(*, *, *, meta_tag, mapper, meta);
}

function _map_attributes_by_meta_tag(
instance,
instance_map: map<name, gtv?>,
options: list<Mapper.option>,
meta_tag: text,
mapper: (map<name, gtv?>, map<Mapper.key_name, gtv?>, list<Mapper.option>) -> unit,
meta: list<Meta.meta>?
) {
val interfaces = Interface.get_all_in_instance(instance);

val attributes = (a: attribute,  m: AttributeMeta.attribute_meta) @* {
a.dclass in interfaces,
m.meta_key == meta_tag,
m.attribute == a
} ((
Mapper.key_name(prefix=a.dclass.name, name=a.name),
Mapper.decorate_with_meta_if_needed(
Mapper._get_attribute_name_from_attribute(a),
Attribute.get_value(instance, Mapper._get_attribute_name_from_attribute(a)),
meta,
options
)
));

mapper(instance_map, map(attributes), options);
}

/*
*  Reads all instance attributes by meta categories
*/
function map_attributes_by_meta_categories(
categories: list<text>,
mapper: (map<name, gtv?>, map<Mapper.key_name, gtv?>, list<Mapper.option>) -> unit = Mapper.direct(),
meta: list<Meta.meta>? = null
): (instance, map<name, gtv?>, list<Mapper.option>) -> unit {
return _map_attributes_by_meta_categories(*, *, *, categories, mapper, meta);
}

function _map_attributes_by_meta_categories(
instance,
instance_map: map<name, gtv?>,
options: list<Mapper.option>,
categories: list<text>,
mapper: (map<name, gtv?>, map<Mapper.key_name, gtv?>, list<Mapper.option>) -> unit,
meta: list<Meta.meta>?
) {
val interfaces = Interface.get_all_in_instance(instance);

val attributes = (a: attribute,  m: AttributeMeta.attribute_meta) @* {
a.dclass in interfaces,
m.category in categories,
m.attribute == a
} ((
Mapper.key_name(prefix=a.dclass.name, name=a.name),
Mapper.decorate_with_meta_if_needed(
Mapper._get_attribute_name_from_attribute(a),
Attribute.get_value(instance, Mapper._get_attribute_name_from_attribute(a)),
meta,
options
)
));

mapper(instance_map, map(attributes), options);
}

/***************************************************************************************
*								 Mapping functions
***************************************************************************************/

/*
*	 Adds attributes map directly (merges) to instance map
*/

function direct(): (map<name, gtv?>, map<key_name, gtv?>, list<option>) -> unit {
return _direct(*);
}

function _direct(
instance_map: map<name, gtv?>,
attributes_map: map<key_name, gtv?>,
options: list<option>
) {
var result = map<name, gtv?>();
for ((k, v) in attributes_map) {
if (v == null and option.remove_null_values in options) continue;

val _key = if (option.remove_interface in options) k.name else get_key_name(k);

result[_key] = v;
}
instance_map.put_all(result);
}

/*
*  Assigns attributes map to `name` key in instance map
*/

function to_map(name): (map<name, gtv?>, map<key_name, gtv?>, list<option>) -> unit {
return _map(*, *, *, name);
}

function _map(
instance_map: map<name, gtv?>,
attributes_map: map<key_name, gtv?>,
options: list<option>,
name
) {
var result = map<name, gtv?>();
for ((k, v) in attributes_map) {
if (v == null and option.remove_null_values in options) continue;

val _key = if (option.remove_interface in options) k.name else get_key_name(k);

result[_key] = v;
}
instance_map[name] = result.to_gtv();
}

/*
*  Assigns attributes map values as a list to `name` key in instance map
*/

function to_list(name): (map<name, gtv?>, map<key_name, gtv?>, list<option>) -> unit {
return _list(*, *, *, name);
}

function _list(
instance_map: map<name, gtv?>,
attributes_map: map<key_name, gtv?>,
options: list<option>,
name
) {
val values: list<gtv?>;
if (option.remove_null_values in options) {
values = attributes_map.values() @* { $ != null };
} else {
values = attributes_map.values();
}

instance_map[name] = values.to_gtv();
}

function with_meta(meta: list<Meta.meta>) = meta;

/***************************************************************************************
*									  Helper
***************************************************************************************/

function _get_attribute_name_from_attribute(attribute) =
Attribute.I(interface = attribute.dclass.name, name = attribute.name);

function remove_interfaces(instance_map: map<name, gtv?>, options: list<option>) {
var result = map<name, gtv?>();
for ((name, value) in instance_map) {

}
return result;
}

function get_key_name(key_name) {
return if (key_name.prefix??) key_name.prefix + "." + key_name.name else key_name.name;
}

function get_value(instance, attribute_name: Attribute.I, options: list<option>) {
val attribute = Attribute.get(attribute_name);

when (attribute.type) {
Attribute.type.boolean ->
return Boolean.get_value(instance, attribute_name)?.to_gtv();
Attribute.type.byte_array ->
return ByteArray.get_value(instance, attribute_name)?.to_gtv();
Attribute.type.decimal ->
return Decimal.get_value(instance, attribute_name)?.to_gtv();
Attribute.type.instance ->
return Instance.get_value(instance, attribute_name)?.to_gtv();
Attribute.type.integer ->
return Integer.get_value(instance, attribute_name)?.to_gtv();
Attribute.type.text ->
return Text.get_value(instance, attribute_name)?.to_gtv();
Attribute.type.file ->
return File.get_value(instance, attribute_name)?.to_gtv();
Attribute.type.ordered_container ->
return list_map_instance_elements(List.unpack(instance, attribute_name), options);
Attribute.type.unordered_container ->
return list_map_instance_elements(Set.unpack(instance, attribute_name), options);
Attribute.type.addressable_container ->
return map_map_instance_elements(Map.unpack(instance, attribute_name), options);
else -> {
require(false, "Unimplemented path"); return null;
}
}
}

function list_map_instance_elements(collection: (type: Attribute.type, values: gtv)?, options: list<option>): gtv? {
if (collection == null) return null;

if (collection.type == Attribute.type.instance) {
return list<instance>.from_gtv(collection.values) @* {} (
map_instance($, [map_all_attributes()], options)
).to_gtv();
} else {
return collection.values.to_gtv();
}
}

function map_map_instance_elements(collection: (types: (K: Attribute.type, V: Attribute.type), values: map<gtv, gtv>)?, options: list<option>): gtv? {
if (collection == null) return null;

if (collection.types.K == Attribute.type.instance or collection.types.V == Attribute.type.instance) {
return map(
collection.values @* {} (
_map_if_instance(collection.types.K, $[0], options),
_map_if_instance(collection.types.V, $[1], options)
)
).to_gtv();
} else {
return collection.values.to_gtv();
}
}

function decorate_with_meta_if_needed(Attribute.I, value: gtv?, meta: list<Meta.meta>?, options: list<option>): gtv? {
if (empty(meta) or (empty(value) and option.remove_null_values in options)) return value;

val result = map<name, gtv?>(Attribute.get_meta(I, meta));

result["value"] = value?.to_gtv();

return result.to_gtv();
}

function _map_if_instance(Attribute.type, value: gtv, options: list<option>) {
return if (type == Attribute.type.instance) map_instance(instance.from_gtv(value), [map_all_attributes()], options).to_gtv() else value.to_gtv();
}
}

import ^.util.*;

                                    namespace Meta {
                                    struct I {
                                    meta_key: text;
                                    meta_value: byte_array;
                                    category: text;
                                    }
                                    }

                                    namespace AttributeMeta {
                                    enum category {
                                    access_constraint,
                                    value_constraint,
                                    computed_value
                                    }

                                    enum type {
                                    public_mutable,
                                    min,
                                    max,
                                    interface,
                                    one_interface,
                                    all_interface,
                                    optional,
                                    default_value,
                                    composite_value,
                                    unique,
                                    one_of
                                    }

                                    entity attribute_meta {
                                    index attribute, meta_key: text, category: text;
                                    meta_value: byte_array;
                                    }

                                    function add(attribute, meta: Meta.I) {
                                    create attribute_meta(
                                    attribute,
                                    meta_key = meta.meta_key,
                                    meta.meta_value,
                                    category = meta.category
                                    );
                                    }

                                    function get(attribute, meta_key: text): gtv? {
                                    // there could be two meta tags with same key but different value
                                    var meta_value = attribute_meta @? {attribute, meta_key} .meta_value;
                                    if(meta_value??) return gtv.from_bytes(meta_value); else return null;
                                    }

                                    function get_all_by_attribute_and_category(attribute, category: text) {
                                    return attribute_meta @* {attribute, category};
                                    }

                                    function is_attribute_optional(attribute): boolean {
                                    val res = get(attribute, type.optional.name);
                                    if(res??) return boolean.from_gtv(res); else return false;
                                    }

                                    function get_default_value(attribute): gtv? {
                                    return get(attribute, type.default_value.name);
                                    }

                                    function get_meta(attribute, Meta._Meta): attribute_meta? {
                                    return attribute_meta @? { attribute, .category == _Meta.category, .meta_key == _Meta.tag };
                                    }

                                    function get_meta_value(attribute, Meta._Meta): gtv? {
                                    val value = get_meta(attribute, _Meta)?.meta_value;
                                    return if (value??) gtv.from_bytes(value) else null;
                                    }
                                    }

                                    namespace InterfaceMeta {
                                    enum type {
                                    owner
                                    }

                                    entity dclass_meta {
                                    index Interface.dclass, meta_key: text, meta_value: byte_array;
                                    }

                                    function add(Interface.dclass, meta_key: text, meta_value: byte_array) {
                                    create dclass_meta(dclass, meta_key, meta_value);
                                    }

                                    function get(Interface.dclass, meta_key: text): gtv? {
                                    var meta_value = dclass_meta @? {dclass, meta_key} .meta_value;
                                    if(meta_value??) return gtv.from_bytes(meta_value); else return null;
                                    }

                                    function get_all_by_dclass(Interface.dclass) {
                                    return dclass_meta @* {dclass};
                                    }

                                    function get_owner(Interface.dclass): byte_array? {
                                    val meta_value = get(dclass, type.owner.name);
                                    if(meta_value??) return byte_array.from_gtv(meta_value); else return null;
                                    }
                                    }

                                    namespace Meta.Engine {
                                    struct access { ft3_a.account; }

                                    function execute_access(i: instance, attribute_name: Attribute.I, access) {
                                    val attribute = Attribute.get(attribute_name);
                                    var m_attrs = AttributeMeta.get_all_by_attribute_and_category(attribute, AttributeMeta.category.access_constraint.name);
                                    var access_granted = false;

                                    for (m_attr in m_attrs) {
                                    val meta_value_gtv = gtv.from_bytes(m_attr.meta_value);
                                    if (not access_granted) access_granted = access_constraint(attribute, i, m_attr.meta_key, meta_value_gtv, access);
                                    }

                                    require(access_granted, "Tried to change immutable attribute " + attribute.name);
                                    }

                                    function execute_value(i: instance, attribute, value: gtv) {
                                    var m_attrs = AttributeMeta.get_all_by_attribute_and_category(attribute, AttributeMeta.category.value_constraint.name);

                                    for (m_attr in m_attrs) {
                                    val meta_value_gtv = gtv.from_bytes(m_attr.meta_value);
                                    value_constraint(i, attribute, m_attr.meta_key, meta_value_gtv, value);
                                    }
                                    }

                                    @extendable function access_constraint(attribute, i: instance, m_k: text, m_v: gtv, access): boolean {
                                    when (m_k) {
                                    AttributeMeta.type.public_mutable.name -> return true;
                                    }

                                    return false;
                                    }

                                    @extendable function value_constraint(instance, attribute, m_k: text, m_v: gtv, value: gtv) {
                                    when (m_k) {
                                    AttributeMeta.type.min.name -> check_range_constraint(attribute, value, _min = m_v);
                                    AttributeMeta.type.max.name -> check_range_constraint(attribute, value, _max = m_v);
                                    AttributeMeta.type.interface.name -> check_interface_constraint(attribute, value, m_v, true);
                                    AttributeMeta.type.one_interface.name -> check_interface_constraint(attribute, value, m_v, false);
                                    AttributeMeta.type.all_interface.name -> check_interface_constraint(attribute, value, m_v, true);
                                    AttributeMeta.type.unique.name -> check_unique_constraint(instance, attribute, value);
                                    AttributeMeta.type.one_of.name -> check_one_of_constraint(instance, attribute, value, m_v);
                                    }
                                    }

                                    function check_range_constraint(attribute, value: gtv, _min: gtv? = null, _max: gtv? = null) {
                                    var min = if(_min??) integer.from_gtv(_min) else integer.MIN_VALUE;
                                    var max = if(_max??) integer.from_gtv(_max) else integer.MAX_VALUE;
                                    var is_valid = true;

                                    when (attribute.type) {
                                    Attribute.type.decimal -> is_valid = decimal.from_gtv(value) >= min and decimal.from_gtv(value) <= max;
                                    Attribute.type.integer -> is_valid = integer.from_gtv(value) >= min and integer.from_gtv(value) <= max;
                                    Attribute.type.text -> is_valid = text.from_gtv(value).size() >= min and text.from_gtv(value).size() <= max;
                                    Attribute.type.byte_array -> is_valid = byte_array.from_gtv(value).size() >= min and byte_array.from_gtv(value).size() <= max;
                                    }

                                    require(is_valid,
                                    "Range constraint violation on attribute " + attribute.name +
                                    " with value " + value +
                                    " on range " + min + " - " + max
                                    );
                                    }

                                    function check_unique_constraint(instance, attribute, value: gtv) {
                                    require(
                                    Attribute.Private.is_unique_value(instance, attribute, value),
                                    "Unique constraint violation on attribute " + attribute.name +
                                    " with value " + value
                                    );
                                    }

                                    function check_one_of_constraint(instance, attribute, value: gtv, values: gtv) {
                                    val valid_values = list<text>.from_gtv(values);
                                    val attribute_value = text.from_gtv(value);
                                    require(
                                    attribute_value in valid_values,
                                    "Invalid value '%s'. Expected one of %s".format(attribute_value, valid_values)
                                    );
                                    }

                                    function get_interface_values(value: gtv): set<instance> {
                                    val peek = value.to_bytes()[0];
                                    if (peek == x'a3'[0]) {
                                    return set([instance.from_gtv(value)]);
                                    } else if (peek == x'a5'[0]) {
                                    return set<instance>.from_gtv(value);
                                    }

                                    return set<instance>();
                                    }

                                    function get_interface_meta_value(meta_value: gtv): set<text> {
                                    val peek = meta_value.to_bytes()[0];
                                    if (peek == x'a2'[0]) {
                                    return set([text.from_gtv(meta_value)]);
                                    } else if (peek == x'a5'[0]) {
                                    return set<text>.from_gtv(meta_value);
                                    }

                                    return set<text>();
                                    }

                                    function check_interface_constraint(attribute, value: gtv, meta_value: gtv, implements_all: boolean) {
                                    val instances = get_interface_values(value);
                                    if (instances.size() > 0) {
                                    val constraint_values = get_interface_meta_value(meta_value);

                                    for(instance in instances) {
                                    val interfaces_from_instance = Interface.get_all_in_instance(instance) @* {}(.name);

                                    if (implements_all) {
                                    require(
                                    interfaces_from_instance.contains_all(constraint_values),
                                    "Instance not implementing interface(s) " + constraint_values
                                    );
                                    } else {
                                    require(
                                    interfaces_from_instance @ {$ in constraint_values} (@sum 1) > 0,
                                    "Instance not implementing interface(s) " + constraint_values
                                    );
                                    }
                                    }
                                    }
                                    }
                                    }

                                    namespace Meta {
                                    function Category(name) = Meta.meta(Meta.type.category, name);

                                    function Tag(name) = Meta.meta(Meta.type.tag, name);

                                    enum type {
                                    category,
                                    tag
                                    }

                                    struct meta {
                                    type;
                                    name;
                                    }

                                    struct _Meta {
                                    category: name;
                                    tag: name;
                                    }
                                    }

                                    function Owner(account_id: byte_array): Meta.I {
                                    return Meta.I(
                                    meta_key = InterfaceMeta.type.owner.name,
                                    meta_value = account_id.to_gtv().to_bytes(),
                                    category = ""
                                    );
                                    }

                                    function Default(value: byte_array): Meta.I {
                                    return Meta.I(
                                    meta_key = AttributeMeta.type.default_value.name,
                                    meta_value = value,
                                    category = ""
                                    );
                                    }

                                    function Mutable(): Meta.I {
                                    return Meta.I(
                                    meta_key = AttributeMeta.type.public_mutable.name,
                                    meta_value = true.to_gtv().to_bytes(),
                                    category = AttributeMeta.category.access_constraint.name
                                    );
                                    }

                                    function Optional(): Meta.I {
                                    return Meta.I(
                                    meta_key = AttributeMeta.type.optional.name,
                                    meta_value = true.to_gtv().to_bytes(),
                                    category = ""
                                    );
                                    }

                                    function Max(max: integer): Meta.I {
                                    return Meta.I(
                                    meta_key = AttributeMeta.type.max.name,
                                    meta_value = max.to_gtv().to_bytes(),
                                    category = AttributeMeta.category.value_constraint.name
                                    );
                                    }

                                    function Min(min: integer): Meta.I {
                                    return Meta.I(
                                    meta_key = AttributeMeta.type.min.name,
                                    meta_value = min.to_gtv().to_bytes(),
                                    category = AttributeMeta.category.value_constraint.name
                                    );
                                    }

                                    function ImplementsInterface(interface: text): Meta.I {
                                    return Meta.I(
                                    meta_key = AttributeMeta.type.interface.name,
                                    meta_value = interface.to_gtv().to_bytes(),
                                    category = AttributeMeta.category.value_constraint.name
                                    );
                                    }

                                    function ImplementsAllInterfaces(interfaces: set<text>): Meta.I {
                                    return Meta.I(
                                    meta_key = AttributeMeta.type.all_interface.name,
                                    meta_value = interfaces.to_gtv().to_bytes(),
                                    category = AttributeMeta.category.value_constraint.name
                                    );
                                    }

                                    function ImplementsOneInterface(interfaces: set<text>): Meta.I {
                                    return Meta.I(
                                    meta_key = AttributeMeta.type.one_interface.name,
                                    meta_value = interfaces.to_gtv().to_bytes(),
                                    category = AttributeMeta.category.value_constraint.name
                                    );
                                    }

                                    function Unique(): Meta.I {
                                    return Meta.I(
                                    meta_key = AttributeMeta.type.unique.name,
                                    meta_value = x'00'.to_gtv().to_bytes(), // make meta value optional?
                                    category = AttributeMeta.category.value_constraint.name
                                    );
                                    }

                                    function CompositeValue(attributes: list<Attribute.I>): Meta.I {
                                    return Meta.I(
                                    meta_key = AttributeMeta.type.composite_value.name,
                                    meta_value = attributes.to_gtv().to_bytes(),
                                    category = AttributeMeta.category.computed_value.name
                                    );
                                    }

                                    function OneOf(values: list<text>): Meta.I {
                                    return Meta.I(
                                    meta_key = AttributeMeta.type.one_of.name,
                                    meta_value = values.to_gtv().to_bytes(),
                                    category = AttributeMeta.category.value_constraint.name
                                    );
                                    }

@mount('dip')
                                    module;

                                    import ^.attributes.*;
                                    import ^^.ft3_helper.*;

entity instance_prototype {
p_index: integer; // index of this prototype in the chain, p_index = 0 is highest priority, etc.
key instance, p_index; // make sure we have only one prototype at given priority level, also can find all instance_prototype for a given instance
key prototype: instance, instance; // also serves as index which retrieves instances by the prototype
}

namespace Prototype {
entity prototype {
key instance, name;
}

function get(prototype_name: text): instance {
return require(
prototype @? { prototype_name } (.instance),
"Prototype '" + prototype_name + "' not found"
);
}

function get_all(instance) {
return instance_prototype @* { instance } (.prototype, @omit @sort .p_index);
}

function get_first(instance) {
return instance_prototype @? { instance } (.prototype, @omit @sort .p_index ) limit 1;
}

function get_name(instance) {
return prototype @? { instance } ( .name);
}

function get_first_prototype_name(instance) {
val prototype = get_first(instance);

return if (prototype??) get_name(prototype) else null;
}

function link_instance_prototypes(instance, parent_prototype: instance) {
val prototypes = instance_prototype @* { .instance == parent_prototype } (.prototype, @omit @sort .p_index);
prototypes.add(0, parent_prototype);

require(instance not in prototypes, 'Instance already in prototype chain');

var idx = 0;
for (prototype in prototypes) {
require(prototype.is_prototype, 'Tried to link non prototype instance');
create instance_prototype(idx++, instance, prototype);
}
}

function require_access(prototype_name: text, account: ft3.acc.account) {
val prototype = get(prototype_name);
val dclass = instance_dclass @ { prototype, .direct == true} .dclass;
Interface.require_access(dclass.name, account);
}

function is_open_or_owner(instance, ft3.acc.account) {
val prototype_dclass = instance_dclass @ { instance, .direct == true} .dclass;
val owner_id = InterfaceMeta.get_owner(prototype_dclass);
return owner_id == null or owner_id == account.id;
}

function fetch_range_from(prototype: instance, from: rowid, _limit: integer): list<instance> {
return instance_prototype @* {
prototype, .instance.is_prototype == false, .instance.rowid > from
} (.instance) limit _limit;
}

function unpack_instances(
instances: list<instance>, from: Filter.p_from, _limit: integer
): (results: list<instance>, from: Filter.p_from) {
var out = list<instance>();
var last_seen = util.r_zero();

val prototype = instance_prototype @? {
.prototype.rowid == from.instance_rowid,
.instance.rowid == from.prototype_rowid
} (.prototype);

if(prototype??) {
instances.add(0, prototype);
last_seen = from.prototype_rowid;
}

for(i in instances) {
if(i.is_prototype) {
val res = fetch_range_from(i, last_seen, (_limit - out.size()));
out.add_all(res);
last_seen = util.r_zero();

} else {
out.add(i);
}

if (out.size() >= _limit) {
val last_prot = if(i.is_prototype) out[out.size() - 1].rowid else util.r_zero();
return (results = out, from = Filter.p_from(instance_rowid = i.rowid, prototype_rowid = last_prot) );
}
}

val last_instance = if (out.size() >= 1) out[out.size() - 1].rowid else util.r_zero();
return (results = out, from = Filter.p_from(instance_rowid = last_instance, prototype_rowid = util.r_zero()));
}
}

@mount('dip')
