@extendable
function has_interface_definition_permission(account, dependencies: list<Interface.dclass>): boolean;

@extendable
function has_prototype_definition_permission(account, Interface.dclass, instance?): boolean;

@extendable
function has_instance_creation_permission(account, Interface.dclass): boolean;

import ^^^^.ft3.account.*;
import ^^^^.dip.core.*;
import ^^.access;

@extend(access.has_interface_definition_permission)
function (account, dependencies: list<Interface.dclass>): boolean {
for (interface in dependencies) {
if (not Interface.is_open_or_owner(interface, account)) return false;
}
return true;
}

@extend(access.has_prototype_definition_permission)
function (account, Interface.dclass, prototype: instance?): boolean {
return
Interface.is_open_or_owner(dclass, account)
and
if (prototype??) Prototype.is_open_or_owner(prototype, account) else true;
}

@extend(access.has_instance_creation_permission)
function (account, Interface.dclass): boolean {
return Interface.is_open_or_owner(dclass, account);
}

import ^^^.ft3.account;

                                    function require_interface_definition_permission(account.account, dependencies: list<Interface.dclass>) {
                                    require(
                                    has_interface_definition_permission(account, dependencies),
                                    "Account '%s' does not have access to some interface dependencies %s".format(account.id, dependencies @* {} (.name))
                                    );
                                    }

                                    function require_prototype_definition_permission(
                                    account.account,
                                    interface: Interface.dclass,
                                    parent_prototype: instance?
                                    ) {
                                    require(
                                    has_prototype_definition_permission(account, interface, parent_prototype),
                                    "Account '%s' does not have access to interface or parent prototype".format(account.id)
                                    );
                                    }

                                    function require_instance_creation_permission(
                                    account.account,
                                    interface: Interface.dclass
                                    ) {
                                    require(
                                    has_instance_creation_permission(account, interface),
                                    "Account '%s' does not have access to interface '%s'".format(account.id, interface.name)
                                    );
                                    }

