@mount('ft3')
                                    module;

                                    import dev_op: ^^.core.dev_op;
                                    import acc: ^^.account;



                                    /*
                                    * Can be negative
                                    */
                                    operation dev_give_points(account_id: byte_array, amount: integer){
                                    val account = acc.account@{.id == account_id};
                                    dev_op.dev_give_points_(account, amount);
