// from hedget: https://bitbucket.org/chromawallet/hedget_0/src/b4cbd207b16af9f3b0a9baa8a956071b89d04e84/rell/src/lib/ft3_helper/account_fun.rell

                                    import ft3_a: ^.ft3.account;
                                    import ft3: ^.ft3.core;

                                    function LOCKED(reason: text) = "LOCKED_" + reason;

                                    // TODO: this should be part of FT3

                                    struct auth_id {
                                    account_id: byte_array;
                                    auth_descriptor_id: byte_array;
                                    }

                                    function do_auth(auth_id, required_flags: list<text>): ft3_a.account {
                                    return ft3_a.auth_and_log(auth_id.account_id, auth_id.auth_descriptor_id, required_flags);
                                    }

                                    // special account is a virtual account which no one has keys to
                                    // it can be based on existing user account

                                    function special_account_id (kind: text, refid: byte_array, params: gtv): byte_array {
                                    return ("SA", kind, refid, params).hash();
                                    }

                                    function find_special_account (kind:text, refid: byte_array, params: gtv): ft3_a.account? {
                                    val id = special_account_id (kind, refid, params);
                                    return ft3_a.account @? { id };
                                    }

                                    // create a special account or return one if it already exists
                                    // E.g. for locked funds related to existing account, we could use:
                                    // ensure_special_account("LOCKED_FUNDS", account.id, list<gtv>().to_gtv())
                                    function ensure_special_account (kind: text, refid: byte_array, params: gtv): ft3_a.account {
                                    val id = special_account_id (kind, refid, params);
                                    val existing_acc = ft3_a.account @? { id };
                                    return if (exists(existing_acc)) existing_acc
                                    else
                                    create ft3_a.account ( id );
                                    }

                                    // simplified version of ensure_special_account
                                    function ensure_locked_account (reason: text, ft3_a.account): ft3_a.account {
                                    return ensure_special_account(LOCKED(reason), account.id,
                                    list<gtv>().to_gtv()
                                    );
                                    }

                                    function find_locked_account(reason: text, ft3_a.account): ft3_a.account? {
                                    return find_special_account(LOCKED(reason), account.id,  list<gtv>().to_gtv());
                                    }

                                    function transfer_asset (from: ft3_a.account, to: ft3_a.account, ft3.asset, amount: integer) {
                                    val b1 = ft3.ensure_balance(from, asset);
                                    require(b1.amount >= amount);
                                    val b2 = ft3.ensure_balance(to, asset);
                                    b1.amount -= amount;
                                    b2.amount += amount;

                                    create ft3.payment_history_entry (
                                    from,
                                    asset,
                                    .delta = amount,
                                    .op_index = 0,
                                    .is_input = true,
                                    .entry_index = 0
                                    );
                                    create ft3.payment_history_entry (
                                    to,
                                    asset,
                                    .delta = amount,
                                    .op_index = 0,
                                    .is_input = false,
                                    .entry_index = 0
                                    );
                                    }

                                    // automatically flip sides when amount is negative
                                    function transfer_asset_auto(from: ft3_a.account, to: ft3_a.account, ft3.asset, amount: integer) {
                                    if (amount < 0)
                                    transfer_asset(to, from, asset, -amount);
                                    else
                                    transfer_asset(from, to, asset, amount);
                                    }

                                    function issue_asset (to: ft3_a.account, ft3.asset, amount: integer): ft3.payment_history_entry {
                                    val b = ft3.ensure_balance(to, asset);
                                    b.amount += amount;
                                    return create ft3.payment_history_entry (
                                    to,
                                    asset,
                                    .delta = amount,
                                    .op_index = 0,
                                    .is_input = false,
                                    .entry_index = 0
                                    );
                                    }

                                    function destroy_asset (from: ft3_a.account, ft3.asset, amount: integer): ft3.payment_history_entry {
                                    val b = ft3.ensure_balance(from, asset);
                                    require(b.amount >= amount);
                                    b.amount -= amount;
                                    return create ft3.payment_history_entry (
                                    from,
                                    asset,
                                    .delta = amount,
                                    .op_index = 0,
                                    .is_input = true,
                                    .entry_index = 0
                                    );
                                    }

namespace Badge {
function require_interface(badge: Dip.instance) {
require(
chromia.IBadge.has(badge),
"Badge instance not implementing interface " + chromia.IBadge.interface
);
}
}

namespace Badge.Account {
entity account_badge {
key ft3.acc.account, Dip.instance;
}

function add(ft3.acc.account, badge: Dip.instance) {
require_interface(badge);
create account_badge(account, badge);
}

function get_all(ft3.acc.account): list<Dip.instance> {
return account_badge @* {account} .instance;
}
}

namespace Badge.Original {
function add(original_instance: Dip.instance, badge: Dip.instance) {
require(
chromia.IHasBadges.has(original_instance),
"Original instance not implementing interface " + chromia.IHasBadges.interface
);

require_interface(badge);

Wrapper.Attribute.Unsafe.add_container_element(original_instance, chromia.IHasBadges.badges, badge.to_gtv());
}

function get_all(Dip.instance): set<Dip.instance> {
val values = Wrapper.Attribute.get_value(instance, chromia.IHasBadges.badges);
val instances = set<Dip.instance>();

if(values??) {
instances.add_all(set<Dip.instance>.from_gtv(values));
}

return instances;
}
}

namespace chromia.IOriginal {
val interface = "chromia.IOriginal";

function dependencies(): list<text> {return [];}

val name = Dip.Attribute.I(interface, name = "name");
val description = Dip.Attribute.I(interface, name = "description");
// later web of trust identifier
val creator_id = Dip.Attribute.I(interface, name = "creator_id");
val creator_name = Dip.Attribute.I(interface, name = "creator_name");

function register(account: ft3.acc.account) {
Dip.InterfaceFactory.new(interface,
[
name: Dip.Type(Dip.Text.T()),
creator_id: Dip.Type(Dip.ByteArray.T()),
creator_name: Dip.Type(Dip.Text.T()),
description: Dip.Type(Dip.Text.T(), [Dip.Optional(), CreatorMutable()])
],
dependencies() @* {} (Dip.Interface.get($)),
account = account,
is_open = true
);
}

function get() = Dip.Interface.get(interface);
function has(Dip.instance) = Dip.Interface.is_a(instance, get());
}

namespace chromia.INonFungibleOriginal {
val interface = "chromia.INonFungibleOriginal";

function dependencies(): list<text> {return [IOriginal.interface];}

function register(account: ft3.acc.account) {
Dip.InterfaceFactory.new(interface,
[:],
dependencies() @* {} (Dip.Interface.get($)),
account = account,
is_open = true
);
}

function get() = Dip.Interface.get(interface);
function has(Dip.instance) = Dip.Interface.is_a(instance, get());
}

