import Marketplace: ^.marketplace;

                                    namespace OMapper {
                                    enum type {
                                    id,
                                    owner,
                                    prototype
                                    }

                                    function map_original_meta(
                                    original_meta_list: list<type>,
                                    mapper: (map<name, gtv?>, map<Dip.Mapper.key_name, gtv?>, list<Dip.Mapper.option>) -> unit = Dip.Mapper.direct()
                                    ): (Dip.instance, map<name, gtv?>, list<Dip.Mapper.option>) -> unit {
                                    return _map_original_meta(*, *, *, original_meta_list, mapper);
                                    }

                                    function _map_original_meta(
                                    Dip.instance,
                                    instance_map: map<name, gtv?>,
                                    options: list<Dip.Mapper.option>,
                                    original_meta_list: list<type>,
                                    mapper: (map<name, gtv?>, map<Dip.Mapper.key_name, gtv?>, list<Dip.Mapper.option>) -> unit
                                    ) {
                                    val values = map<Dip.Mapper.key_name, gtv?>();

                                    for (meta in original_meta_list) {
                                    when (meta) {
                                    type.id ->
                                    values[Dip.Mapper.key_name(name=type.id.name)] = Id.get_id(instance).to_gtv();

                                    // TODO: investigate what to send when original instance has multiple owners
                                    // - owner count
                                    // - owners page
                                    // - list of all owners
                                    // - special account that represents all owners
                                    // - special id `0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF`
                                    // - original id
                                    type.owner ->
                                    values[Dip.Mapper.key_name(name=type.owner.name)] = Ownership.get_owner_if_one_by_original_instance(instance)?.to_gtv();
                                    type.prototype ->
                                    values[Dip.Mapper.key_name(name=type.prototype.name)] = Dip.Prototype.get_first_prototype_name(instance)?.to_gtv();
                                    }
                                    }

                                    mapper(instance_map, values, options);
                                    }

                                    /*
                                    *  Reads all instance marketplace listing values
                                    */

                                    function map_marketplace_listing(
                                    mapper: (map<name, gtv?>, map<Dip.Mapper.key_name, gtv?>, list<Dip.Mapper.option>) -> unit = Dip.Mapper.direct()
                                    ): (Dip.instance, map<name, gtv?>, list<Dip.Mapper.option>) -> unit {
                                    return _map_marketplace_listing(*, *, *, mapper);
                                    }

                                    function _map_marketplace_listing(
                                    Dip.instance,
                                    instance_map: map<name, gtv?>,
                                    options: list<Dip.Mapper.option>,
                                    mapper: (map<name, gtv?>, map<Dip.Mapper.key_name, gtv?>, list<Dip.Mapper.option>) -> unit
                                    ) {
                                    val values = map<Dip.Mapper.key_name, gtv?>();
                                    val listing = Marketplace.Listing.original_listing @? {.original.instance == instance};

                                    if(listing??) {
                                    values.put_all([
                                    Dip.Mapper.key_name(name="owner"): listing.owner.id.to_gtv(),
                                    Dip.Mapper.key_name(name="price"): listing.price.to_gtv(),
                                    Dip.Mapper.key_name(name="asset_id"): listing.asset.id.to_gtv()
                                    ]);
                                    }

                                    mapper(instance_map, values, options);
                                    }

                                    /*
                                    *  Reads all instance linked originals.
                                    *  It is also possible to specify mapping rules for children instances.
                                    */
                                    function map_linked(
                                    children_mappers: list<(Dip.instance, map<name, gtv?>, list<Dip.Mapper.option>) -> unit> = [Dip.Mapper.map_all_attributes()],
                                    mapper: (map<name, gtv?>, map<Dip.Mapper.key_name, gtv?>, list<Dip.Mapper.option>) -> unit = Dip.Mapper.direct(),
                                    meta: list<Dip.Meta.meta>? = null
                                    ): (Dip.instance, map<name, gtv?>, list<Dip.Mapper.option>) -> unit {
                                    return _map_linked(*, *, *, children_mappers, mapper, meta);
                                    }

                                    function _map_linked(
                                    Dip.instance,
                                    instance_map: map<name, gtv?>,
                                    options: list<Dip.Mapper.option>,
                                    children_mappers: list<(Dip.instance, map<name, gtv?>, list<Dip.Mapper.option>) -> unit>,
                                    mapper: (map<name, gtv?>, map<Dip.Mapper.key_name, gtv?>, list<Dip.Mapper.option>) -> unit,
                                    meta: list<Dip.Meta.meta>?
                                    ) {
                                    val mapped_instances = (i: Dip.Instance.instance_attribute, ai: Id.asset_instance) @* {
                                    i.instance == instance, i.value == ai.instance
                                    } ((
                                    Dip.Mapper.key_name(prefix=i.attribute.dclass.name, name=i.attribute.name),
                                    Dip.Mapper.decorate_with_meta_if_needed(
                                    Dip.Mapper._get_attribute_name_from_attribute(i.attribute),
                                    Dip.Mapper.map_instance(i.value, children_mappers, options).to_gtv(),
                                    meta,
                                    options
                                    )
                                    ));

                                    mapper(instance_map, map<Dip.Mapper.key_name, gtv?>(mapped_instances), options);
                                    }

                                    /*
                                    *  Reads all instance badges
                                    *  can be replaced by map_attributes_implementing_interface when set of instances are supported
                                    */
                                    function map_badges(
                                    mapper: (map<name, gtv?>, map<Dip.Mapper.key_name, gtv?>, list<Dip.Mapper.option>) -> unit = Dip.Mapper.direct()
                                    ): (Dip.instance, map<name, gtv?>, list<Dip.Mapper.option>) -> unit {
                                    return _map_badges(*, *, *, mapper);
                                    }

                                    function _map_badges(
                                    Dip.instance,
                                    instance_map: map<name, gtv?>,
                                    options: list<Dip.Mapper.option>,
                                    mapper: (map<name, gtv?>, map<Dip.Mapper.key_name, gtv?>, list<Dip.Mapper.option>) -> unit
                                    ) {
                                    val values = list<gtv?>();
                                    val badge_instances = Badge.Original.get_all(instance);

                                    for(badge_instance in badge_instances) {
                                    values.add(
                                    Dip.Mapper.map_instance(
                                    badge_instance,
                                    [Dip.Mapper.map_attributes_of_interfaces([chromia.IBadge.get()])]
                                    ).to_gtv()
                                    );
                                    }

                                    mapper(instance_map, [Dip.Mapper.key_name(name="badges"): values.to_gtv()], options);
                                    }

                                    function map_tx_history(
                                    mapper: (map<name, gtv?>, map<Dip.Mapper.key_name, gtv?>, list<Dip.Mapper.option>) -> unit = Dip.Mapper.direct()
                                    ): (Dip.instance, map<name, gtv?>, list<Dip.Mapper.option>) -> unit {
                                    return _map_tx_history(*, *, *, mapper);
                                    }

                                    function _map_tx_history(
                                    Dip.instance,
                                    instance_map: map<name, gtv?>,
                                    options: list<Dip.Mapper.option>,
                                    mapper: (map<name, gtv?>, map<Dip.Mapper.key_name, gtv?>, list<Dip.Mapper.option>) -> unit
                                    ) {
                                    val trade_events = Marketplace.History.find_original_trade_events(instance);
                                    val trade_events_map = map<Dip.Mapper.key_name, gtv?>();

                                    for(trade_event in trade_events) {
                                    trade_events_map[Dip.Mapper.key_name(name=trade_event.block_height.to_text())] = trade_event.to_gtv_pretty();
                                    }

                                    mapper(instance_map, trade_events_map, options);
                                    }
                                    }

namespace Meta {
                                    enum type {
                                    creator_mutable,
                                    owner_mutable
                                    }

                                    @extend(Dip.Meta.Engine.access_constraint) function(
                                    Dip.attribute,
                                    Dip.instance,
                                    meta_key: text,
                                    meta_value: gtv,
                                    Dip.Meta.Engine.access
                                    ): boolean {
                                    when (meta_key) {
                                    type.owner_mutable.name -> {
                                    check_owner_mutable(instance, attribute, meta_value, access);
                                    return true;
                                    }
                                    type.creator_mutable.name -> {
                                    check_creator_mutable(instance, attribute, meta_value, access);
                                    return true;
                                    }
                                    }

                                    return false;
                                    }

                                    function check_owner_mutable(Dip.instance, Dip.attribute, meta_value: gtv, Dip.Meta.Engine.access) {
                                    val id = Id.get_id(instance);
                                    require(Ft3Helper.owns_original(access.account.id, id), "Attribute " + attribute.name + " can only be changed by owner.");
                                    }

                                    function check_creator_mutable(Dip.instance, Dip.attribute, meta_value: gtv, Dip.Meta.Engine.access) {
                                    val creator_id = Dip.ByteArray.get_value(instance, chromia.IOriginal.creator_id);
                                    require(creator_id, "No creator value found from instance");

                                    require(creator_id == access.account.id, "Only the creator can modify that attribute");
                                    }
                                    }

                                    function OwnerMutable(): Dip.Meta.I {
                                    return Dip.Meta.I(
                                    meta_key = Meta.type.owner_mutable.name,
                                    meta_value = true.to_gtv().to_bytes(),
                                    category = Dip.AttributeMeta.category.access_constraint.name
                                    );
                                    }

                                    function CreatorMutable(): Dip.Meta.I {
                                    return Dip.Meta.I(
                                    meta_key = Meta.type.creator_mutable.name,
                                    meta_value = true.to_gtv().to_bytes(),
                                    category = Dip.AttributeMeta.category.access_constraint.name
                                    );
                                    }

namespace Minter {
struct I {
interface_name: name;
mutable types: map<Dip.Attribute.I, Dip.attribute_type>;
prototype_name: text? = null;
}

function mint_non_fungible_original(
account: ft3.acc.account,
original_type: I
): Dip.instance {
_require_interface(chromia.INonFungibleOriginal.interface, original_type);
return Unsafe._mint(account, original_type, 1);
}

function mint_non_fungible_original_batch(
account: ft3.acc.account,
original_type: I,
quantity: integer
): list<Dip.instance> {
require(quantity > 0, "Quantity has to be greater than 0");
_require_interface(chromia.INonFungibleOriginal.interface, original_type);

val ids = list<Dip.instance>();
for (i in range(quantity)) {
ids.add(Unsafe._mint(account, original_type, 1));
}

return ids;
}

function mint_non_fungible_original_to_account(
account: ft3.acc.account,
original_type: I,
to_account_id: byte_array
): Dip.instance {
val id = mint_non_fungible_original(account, original_type);

Ownership.transfer(account, id, to_account_id, 1);

return id;
}

function mint_non_fungible_original_to_account_batch(
account: ft3.acc.account,
original_type: I,
to_account_id: byte_array,
quantity: integer
): list<Dip.instance> {
require(quantity > 0, "Quantity has to be greater than 0");
_require_interface(chromia.INonFungibleOriginal.interface, original_type);

val ids = list<Dip.instance>();
for (i in range(quantity)) {
val id = mint_non_fungible_original(account, original_type);
Ownership.transfer(account, id, to_account_id, 1);
ids.add(id);
}

return ids;
}

function create_fungible_original(
account: ft3.acc.account,
original_type: I,
quantity: integer = 1
): Dip.instance {
require(quantity > 0, "Quantity has to be greater than 0");
_require_interface(chromia.IFungibleOriginal.interface, original_type);

return Unsafe._mint(account, original_type, quantity);
}

function create_fungible_original_to_account(
account: ft3.acc.account,
original_type: I,
to_account_id: byte_array,
quantity: integer = 1
): Dip.instance {
val id = create_fungible_original(account, original_type, quantity);
Ownership.transfer(account, id,to_account_id, quantity);

return id;
}

function mint_fungible_original_to_account(
account: ft3.acc.account,
fungible_id: byte_array,
to_account_id: byte_array,
quantity: integer = 1
): Dip.instance {
val instance = mint_fungible_original(account, fungible_id, quantity);
Ownership.transfer(account, instance, to_account_id, quantity);

return instance;
}

function mint_fungible_original(
account: ft3.acc.account,
fungible_id: byte_array,
quantity: integer = 1
): Dip.instance {
val instance = Id.get_instance(fungible_id);
val creator_id =  Dip.ByteArray.get_value(instance, chromia.IOriginal.creator_id);
require(creator_id, "No creator value found from instance");
require(creator_id == account.id, "Only creator can mint new originals");

return Unsafe.mint_fungible_original(account, fungible_id, quantity);
}

function _require_interface(interface: text, original_type: I) {
val type_interface = Dip.Interface.get(original_type.interface_name);
val interfaces = Dip.Interface.get_with_dependencies(type_interface);
val has_interface = interface in interfaces @* {} .name;

require(has_interface, "Type not implementing interface " + interface);
}

function _convert_id_type_to_instance(
types: map<Dip.Attribute.I, Dip.attribute_type>
): (v: map<Dip.Attribute.I, Dip.attribute_type>, i: list<byte_array>) {
val instance_ids = list<byte_array>();
val local_types = map<Dip.Attribute.I, Dip.attribute_type>(types);

for ((k, v) in types) {
when (v.type) {
Dip.Attribute.type.id -> {
if (v.value??) {
instance_ids.add(byte_array.from_gtv(v.value!!));

val converted = Dip.attribute_type(
Dip.Attribute.type.instance,
value = Id.get_instance(byte_array.from_gtv(v.value!!)).to_gtv()
);
local_types[k] = converted;
}
}
Dip.Attribute.type.unordered_container -> {
if (v.value??) {
if (v.inner_type?? and Dip.Attribute.type.from_gtv(v.inner_type!!) == Dip.Attribute.type.id) {
val ids = set<byte_array>.from_gtv(v.value!!);
instance_ids.add_all(ids);

val converted = Dip.attribute_type(
Dip.Attribute.type.instance,
value = set(ids @* {} (Id.get_instance($))).to_gtv()
);

local_types[k] = converted;
}
}
}
Dip.Attribute.type.instance -> require(false, "Use ID type to link originals after minting.");
}
}

return (v = local_types, i = instance_ids);
}
}

namespace Minter.Unsafe {
function _mint(ft3.acc.account, original_type: I, quantity: integer): Dip.instance {
val (types, instance_ids) = _convert_id_type_to_instance(original_type.types);

val asset = Ft3Helper.create_and_mint_asset(Id.generate(), account.id, quantity);
val interface = Dip.Interface.get(original_type.interface_name);
val instance = Dip.InstanceFactory.new(interface, types, original_type.prototype_name);

Id.new(asset, instance);

for (id in instance_ids) {
Ft3Helper.lock_asset(account.id, id, Ft3Helper.SPECIAL);
}

return instance;
}

function mint_fungible_original(
ft3.acc.account,
fungible_id: byte_array,
quantity: integer = 1
): Dip.instance {
require(quantity > 0, "Quantity has to be greater than 0");

val instance = Id.get_instance(fungible_id);
val max_supply = Dip.Integer.get_value(instance, chromia.IFungibleOriginal.max_supply);

val total_supply = Ft3Helper.get_asset_supply(fungible_id);
require(total_supply + quantity <= max_supply!!, "Total supply exceeds max supply");

Ft3Helper.mint_existing_asset(fungible_id, account.id, quantity);

return instance;
}
}

