namespace Filter {
                                    function get_by_interface(name): map<name, gtv> {
                                    val filters_definition = map<name, gtv>();
                                    val attribute_tag_pairs = Meta.find_interface_attributes_by_meta_tag(name, Meta.tag.marketplace_filter);

                                    for((attribute, tag_value) in attribute_tag_pairs) {
                                    when(attribute.type) {
                                    Dip.Attribute.type.text -> filters_definition[tag_value] = _handle_text_filter(attribute).to_gtv();
                                    Dip.Attribute.type.integer -> filters_definition[tag_value] = _handle_integer_filter(attribute).to_gtv();
                                    }
                                    }

                                    return filters_definition;
                                    }

                                    /*
                                    * TODO only on protoypes and fungible originals?
                                    * or limit
                                    */
                                    function _handle_text_filter(Dip.attribute): map<name, gtv> {
                                    val values = Dip.Text.text_attribute @* {attribute} .value;
                                    return _options_filter(
                                    attribute.name,
                                    Dip.gtv_to_list_of_gtv(values.to_gtv(), attribute.type)
                                    );
                                    }

                                    function _options_filter(name, values: list<gtv>): map<text, gtv> {
                                    return [
                                    "name": name.to_gtv(),
                                    "type": "options".to_gtv(),
                                    "values": values.to_gtv()
                                    ];
                                    }

                                    /*
                                    * TODO only on protoypes and fungible originals?
                                    * or limit
                                    */
                                    function _handle_integer_filter(Dip.attribute): map<name, gtv> {
                                    val values = Dip.Integer.integer_attribute @* {attribute} (@sort .value);

                                    if (values.size() == 0) return _range_filter(attribute.name, 0,100);
                                    if (values.size() == 1) return _range_filter(attribute.name, values[0], values[0]);

                                    return _range_filter(
                                    attribute.name,
                                    values[0], values[values.size()-1]
                                    );
                                    }

                                    function _range_filter(name, min: integer, max: integer): map<text, gtv> {
                                    return [
                                    "name": name.to_gtv(),
                                    "type": "range".to_gtv(),
                                    "values": [
                                    "min": min.to_gtv(),
                                    "max": max.to_gtv()
                                    ].to_gtv()
                                    ];
                                    }
                                    }

/***************************************************************************************
                                    *                                 Query mapping helper
                                    ***************************************************************************************/

                                    function map_original_instance(Dip.instance): map<name, gtv?> {
                                    val mapping_rules = [
                                    Originals.OMapper.map_original_meta([Originals.OMapper.type.id]),
                                    Originals.OMapper.map_marketplace_listing(Dip.Mapper.to_map("listing")),
                                    Originals.OMapper.map_tx_history(Dip.Mapper.to_list("tx_history")),
                                    Originals.OMapper.map_badges(),
                                    Dip.Mapper.map_attributes_by_meta_tag(Meta.tag.marketplace_filter.name, Dip.Mapper.to_map("attributes")),
                                    Dip.Mapper.map_attributes_of_interfaces([Originals.chromia.IOriginal.get()])
                                    ];

                                    val children_rule = Originals.OMapper.map_linked(mapping_rules, Dip.Mapper.to_list("children"));
                                    mapping_rules.add(children_rule);

                                    return Dip.Mapper.map_instance(instance, mapping_rules);
                                    }

                                    function map_instances_to_query_result(
                                    instances: list<Dip.instance>, Dip.Filter.p_from? = null
                                    ): (count: integer, instances: list<map<text, gtv?>>, last_p_from: Dip.Filter.p_from)
                                    {
                                    val result = list<map<text, gtv?>>();

                                    for (instance in instances) {
                                    result.add(map_original_instance(instance));
                                    }

                                    var cur_from = p_from;
                                    if(p_from == null) {
                                    val last_rowid =
                                    if (instances.size() > 0)
                                    instances[instances.size()-1].rowid
                                    else
                                    Dip.r_zero();

                                    cur_from = Dip.Filter.p_from(instance_rowid = last_rowid);
                                    }

                                    return (
                                    count = instances.size(),
                                    instances = result,
                                    last_p_from = cur_from!!
                                    );
                                    }

                                    /***************************************************************************************
                                    *                              Query find instances wrapper
                                    ***************************************************************************************/

                                    function find_distinct_original_names_by_interface(interface_name: name): list<(display_name: text)> {
                                    var original_name = Originals.chromia.IOriginal.name;

                                    return (id: Dip.instance_dclass, t: Dip.Text.text_attribute) @* {
                                    id.dclass.name == interface_name,
                                    t.attribute.name == original_name.name, id.instance == t.instance
                                    } (@group display_name = t.value);
                                    }

                                    function find_listed_originals_by_interface(
                                    interface_name: name,
                                    Dip.Filter.p_from,
                                    page_size: integer
                                    ): (count: integer, instances: list<map<text, gtv?>>, last_p_from: Dip.Filter.p_from) {
                                    val instances = (ol: Listing.original_listing, id: Dip.instance_dclass) @* {
                                    id.instance.rowid > p_from.instance_rowid,
                                    id.dclass.name == interface_name,
                                    ol.original.instance == id.instance
                                    }(@sort ol.original.instance) limit page_size;

                                    return map_instances_to_query_result(instances);
                                    }

                                    function find_listed_originals_by_interface_price_range(
                                    interface_name: name,
                                    min: integer,
                                    max: integer,
                                    Dip.Filter.p_from,
                                    page_size: integer
                                    ): (count: integer, instances: list<map<text, gtv?>>, last_p_from: Dip.Filter.p_from) {
                                    val instances = (ol: Listing.original_listing, id: Dip.instance_dclass) @* {
                                    id.instance.rowid > p_from.instance_rowid,
                                    id.dclass.name == interface_name,
                                    ol.original.instance == id.instance,
                                    ol.price > min, ol.price < max
                                    }(@sort ol.original.instance) limit page_size;

                                    return map_instances_to_query_result(instances);
                                    }

                                    function find_original_by_id(id: byte_array): map<name, gtv?>? {
                                    val instance = Originals.Id.asset_instance @? {.asset.id == id} .instance;
                                    return if(instance??) map_original_instance(instance) else null;
                                    }

                                    function find_original_instances_by_owner_id(
                                    owner_id: byte_array,
                                    Dip.Filter.p_from,
                                    page_size: integer
                                    ): (count: integer, instances: list<map<text, gtv?>>, last_p_from: Dip.Filter.p_from) {
                                    val original_account_id = Ft3Helper.get_original_account_id(owner_id);
                                    val marketplace_account_id = special_account_id(LOCKED(Ft3Helper.LISTED), owner_id, list<gtv>().to_gtv());

                                    val instances = (a: Originals.Id.asset_instance, b: ft3.balance) @* {
                                    a.instance.rowid > p_from.instance_rowid,
                                    (b.account.id == original_account_id or b.account.id == marketplace_account_id),
                                    a.asset == b.asset,
                                    b.amount > 0
                                    } .instance limit page_size;

                                    return map_instances_to_query_result(instances);
                                    }

                                    function find_original_instances_by_owner_id_and_status(
                                    owner_id: byte_array,
                                    listed_state: boolean,
                                    Dip.Filter.p_from,
                                    page_size: integer
                                    ): (count: integer, instances: list<map<text, gtv?>>, last_p_from: Dip.Filter.p_from) {
                                    val original_account_id = Ft3Helper.get_original_account_id(owner_id);
                                    val marketplace_account_id = special_account_id(LOCKED(Ft3Helper.LISTED), owner_id, list<gtv>().to_gtv());

                                    val instances = (ia: Originals.Id.asset_instance, b: ft3.balance) @* {
                                    ia.instance.rowid > p_from.instance_rowid, b.amount > 0,
                                    ia.asset == b.asset,
                                    when (listed_state) {
                                    true -> b.account.id == marketplace_account_id;
                                    else -> b.account.id == original_account_id;
                                    }
                                    } (ia.instance) limit page_size;
                                    return map_instances_to_query_result(instances);
                                    }

                                    function find_originals_by_creator_id(
                                    creator_id: byte_array,
                                    Dip.Filter.p_from,
                                    page_size: integer
                                    ): (count: integer, instances: list<map<text, gtv?>>, last_p_from: Dip.Filter.p_from) {
                                    val instances = Dip.Attribute.find_instances(
                                    Originals.chromia.IOriginal.creator_id,
                                    creator_id.to_gtv(),
                                    p_from,
                                    page_size
                                    );

                                    return map_instances_to_query_result(instances.results, instances.from);
                                    }

                                    function search(
                                    text
                                    ): (type: text, hit: gtv)? {
                                    if (text.size() != 64) return null;
                                    val id = byte_array(text);

                                    if (Ft3Helper.does_account_exist(id)) {
                                    return (
                                    type = "account",
                                    hit = find_original_instances_by_owner_id(id, Dip.Filter.p_from(), 10).to_gtv()
                                    );
                                    } else if (Originals.Id.does_original_exist(id)) {
                                    return (
                                    type = "original",
                                    hit = find_original_by_id(id)!!.to_gtv()
                                    );
                                    }

                                    return null;
                                    }

                                    function get_grouped_interfaces(): map<name, list<map<name, gtv>>> {
                                    val category_interfaces = Meta.get_category_values();

                                    val grouped_interfaces = map<name, list<map<name, gtv>>>();
                                    for ((category_name, interface_name) in category_interfaces) {
                                    val interface = Dip.Interface.get(interface_name);
                                    val dclasses = Dip.Interface.get_with_dependencies(interface);
                                    val attributes = Dip.Attribute.get_all_in_dclasses(dclasses);
                                    val mapped_attributes = map<name, gtv>();
                                    for (attribute in attributes) {
                                    mapped_attributes.put(
                                    Dip.Attribute.get_name_from_attribute(attribute),
                                    (meta = list<integer>().to_gtv(), type = attribute.type.name).to_gtv()
                                    );
                                    }

                                    val meta = map<name, gtv>();
                                    val description_tag = Meta.tag.marketplace_description.name;
                                    val description = Dip.InterfaceMeta.get(interface, description_tag);
                                    if (description??) {
                                    meta.put(description_tag, description.to_gtv());
                                    }

                                    val name_tag = Meta.tag.marketplace_name.name;
                                    val name = Dip.InterfaceMeta.get(interface, name_tag);
                                    if (name??) {
                                    meta.put(name_tag, name.to_gtv());
                                    }

                                    grouped_interfaces.put(category_name, [mapped_attributes, meta]);
                                    }

                                    return grouped_interfaces;
                                    }

namespace History {
@log
entity trade_event {
index Originals.Id.asset_instance;
seller: ft3.acc.account;
buyer: ft3.acc.account;
asset: ft3.asset;
price: integer;
}

@log
entity indirect_trade {
index Originals.Id.asset_instance, trade_event;
}

function log_buy_event(
Originals.Id.asset_instance,
seller: ft3.acc.account,
buyer: ft3.acc.account,
asset: ft3.asset,
price: integer
) {
return create trade_event(
asset_instance,
seller,
buyer,
asset,
price
);
}

function log_indirect_buy(
Originals.Id.asset_instance,
trade_event
) {
create indirect_trade (
asset_instance,
trade_event
);
}

function find_original_trade_events(Dip.instance) {
return trade_event @* { .asset_instance.instance == instance } (
seller_id = .seller.id,
buyer_id = .buyer.id,
asset_id = .asset.id,
price = .price,
timestamp = .transaction.block.timestamp,
@sort_desc block_height = .transaction.block.block_height,

indirect = find_indirect_trade_events($)
);
}

function find_indirect_trade_events(trade_event) {
return indirect_trade @* {trade_event} .asset_instance.asset.id;
}

function find_original_trade_events_page(
Dip.instance,
before_rowid: rowid,
page_size: integer
) {
val events = trade_event @* {
.rowid > before_rowid , .asset_instance.instance == instance
} (
seller_id = .seller.id,
buyer_id = .buyer.id,
asset_id = .asset.id,
price = .price,
timestamp = .transaction.block.timestamp,
block_height = .transaction.block.block_height,
@sort_desc .rowid,

indirect = find_indirect_trade_events($)
) limit page_size;

val last_rowid =
if (events.size() > 0)
events[events.size()-1].rowid.to_gtv()
else
(0).to_gtv();

return (
count = events.size(),
events = events,
last_rowid = last_rowid
);
}
}

namespace Listing {
entity original_listing {
key original: Originals.Id.asset_instance;
owner: ft3.acc.account;
asset: ft3.asset;
mutable price: integer;
}

function get(original_id: byte_array): original_listing {
return require(
original_listing @? {.original.asset.id == original_id},
"Original with id " + original_id + " not listed."
);
}

function list_original(
account: ft3.acc.account,
original_id: byte_array,
asset_id: byte_array,
price: integer
) {
require(price > 0, "Price has to be positive");
val original_asset_instance = Originals.Id.get_by_id(original_id);
require(
Originals.chromia.ITradable.has(original_asset_instance.instance),
"Original does not implement '" + Originals.chromia.ITradable.interface + "' interface"
);

Ft3Helper.lock_asset(account.id, original_id, Ft3Helper.LISTED);
create original_listing (original_asset_instance, account, Ft3Helper.get_asset(asset_id), price);
}

function change_price(
account: ft3.acc.account,
original_id: byte_array,
price: integer
) {
require(price > 0, "Price has to be positive");
val listing = original_listing @ {.original.asset.id == original_id};
require(listing.owner == account, "Only owner can change the price.");
listing.price = price;
}

function unlist_original(
account: ft3.acc.account,
original_id: byte_array
) {
Ft3Helper.unlock_asset(account.id, original_id, Ft3Helper.LISTED);
delete original_listing @ {.original.asset.id == original_id};
}

function buy_original(
account: ft3.acc.account,
original_id: byte_array
) {
val listing = get(original_id);
transfer_asset(account, listing.owner, listing.asset, listing.price);
Ft3Helper.transfer_listed_asset(listing.owner, account, original_id);

val original = Originals.Id.get_instance(original_id);
val transferred_ids = Originals.Ownership.transfer_linked_originals(listing.owner, account, original);

val log = History.log_buy_event(listing.original, listing.owner, account, listing.asset, listing.price);
for (id in transferred_ids) {
History.log_indirect_buy(Originals.Id.get_by_id(id), log);
}

delete listing;
}
}

namespace Meta {
enum category {
marketplace
}

enum tag {
marketplace_description,
marketplace_label,
marketplace_category,
marketplace_name,
marketplace_filter
}

function Category(name): Dip.Meta.I {
return Dip.Meta.I(
meta_key = tag.marketplace_category.name,
meta_value = name.to_gtv().to_bytes(),
category = category.marketplace.name
);
}

function Name(name): Dip.Meta.I {
return Dip.Meta.I(
meta_key = tag.marketplace_name.name,
meta_value = name.to_gtv().to_bytes(),
category = category.marketplace.name
);
}

function Description(text): Dip.Meta.I {
return Dip.Meta.I(
meta_key = tag.marketplace_description.name,
meta_value = text.to_gtv().to_bytes(),
category = category.marketplace.name
);
}

function Label(name): Dip.Meta.I {
return Dip.Meta.I(
meta_key = tag.marketplace_label.name,
meta_value = name.to_gtv().to_bytes(),
category = category.marketplace.name
);
}

function Filter(name): Dip.Meta.I {
return Dip.Meta.I(
meta_key = tag.marketplace_filter.name,
meta_value = name.to_gtv().to_bytes(),
category = category.marketplace.name
);
}

/***************************************************************************************
*                                 Interface meta helper
***************************************************************************************/

function get_category_values(): list<(name: text, interface: text)> {
val tradable_interface = Originals.chromia.ITradable.interface;
return (m: Dip.InterfaceMeta.dclass_meta, d: Dip.Interface.dclass_dependency) @* {
m.meta_key == tag.marketplace_category.name,
d.parent.name == tradable_interface,
m.dclass == d.dclass
} (name = text.from_gtv(gtv.from_bytes(m.meta_value)), interface = m.dclass.name);
}

function get_interface_by_category(name): Dip.Interface.dclass? {
return Dip.InterfaceMeta.dclass_meta @? {
.meta_key == tag.marketplace_category.name,
.meta_value == name.to_bytes()
} (.dclass);
}

/***************************************************************************************
*                                 Attribute meta helper
***************************************************************************************/

function find_interface_attributes_by_meta_tag(name, tag):
list<(attribute: Dip.attribute, tag_value: text)> {

val interfaces = Dip.Interface.get_with_dependencies(Dip.Interface.get(name));

return (m: Dip.AttributeMeta.attribute_meta) @* {
m.meta_key == tag.name, m.attribute.dclass in interfaces
} (attribute = m.attribute, tag_value = text.from_gtv(gtv.from_bytes(m.meta_value)));
}
}

